/******************************
 * FUNCTION: DATABASE CONNECT *
 ******************************/
function db_open() {

    if (isset($GLOBALS['db_global']) && $GLOBALS['db_global']) {
        return $GLOBALS['db_global'];
    }

    // Not usable until the whole try-block below completes. `db_global` alone
    // cannot answer "is the database usable?": it is assigned the moment
    // `new PDO` returns, which is BEFORE the first query runs. A connection
    // that opens against an empty or half-restored schema, or under a grant
    // with no SELECT on `settings`, sets db_global and then throws -- so any
    // code that treats a non-empty db_global as health will happily issue more
    // queries on the failure path. That is how the outage page recurses.
    $GLOBALS['db_connection_ready'] = false;

    // Connect to the database
    try {

        // Set the simplerisk timezone for any datetime functions
        $offset = currentTimezoneOffset();

        // PHP 8.5 moved PDO MySQL constants to the Pdo\Mysql namespace and
        // deprecated the PDO::MYSQL_ATTR_* aliases. Prefer the new constants
        // when available so 8.5+ stops emitting deprecation notices; fall
        // back to the old constants on 8.1-8.4 where the new ones don't
        // exist. The new constants are looked up via constant() (a string
        // lookup) rather than a direct \Pdo\Mysql::* reference so static
        // analyzers running against the PHP 8.3 floor don't flag the class
        // (added in 8.4) as undeclared.
        $pdo_mysql_init_command = defined('Pdo\Mysql::ATTR_INIT_COMMAND') ? constant('Pdo\Mysql::ATTR_INIT_COMMAND') : PDO::MYSQL_ATTR_INIT_COMMAND;
        $pdo_mysql_ssl_ca       = defined('Pdo\Mysql::ATTR_SSL_CA')       ? constant('Pdo\Mysql::ATTR_SSL_CA')       : PDO::MYSQL_ATTR_SSL_CA;

        // Set the default options array
        $options = array(
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            $pdo_mysql_init_command => "SET NAMES utf8mb4, @@group_concat_max_len = 4294967295, time_zone='{$offset}'"
        );

        // If a database SSL certificate path has been defined
        if (defined("DB_SSL_CERTIFICATE_PATH") && DB_SSL_CERTIFICATE_PATH != '') {
            // If the path is set but the file is missing or unreadable,
            // surface a precise diagnostic before PDO bubbles a generic
            // "Cannot connect to MySQL using SSL" error. We deliberately
            // do NOT silently fall back to a non-SSL connection — the
            // operator declared SSL was required, and downgrading would
            // mask a misconfigured mount or permission and let traffic
            // flow unencrypted without warning.
            if (!file_exists(DB_SSL_CERTIFICATE_PATH)) {
                error_log("[SimpleRisk] DB_SSL_CERTIFICATE_PATH is set to '" . DB_SSL_CERTIFICATE_PATH . "' but that file does not exist. PDO will fail to connect with a generic SSL error.");
            } elseif (!is_readable(DB_SSL_CERTIFICATE_PATH)) {
                error_log("[SimpleRisk] DB_SSL_CERTIFICATE_PATH is set to '" . DB_SSL_CERTIFICATE_PATH . "' but the file is not readable by the PHP process. PDO will fail to connect with a generic SSL error.");
            }
            // Add the SSL certificate to the options array
            $options[$pdo_mysql_ssl_ca] = DB_SSL_CERTIFICATE_PATH;
        }

        // Create the PDO object
        $GLOBALS['db_global'] = new PDO("mysql:charset=UTF8;dbname=" . DB_DATABASE . ";host=" . DB_HOSTNAME . ";port=" . DB_PORT, DB_USERNAME, DB_PASSWORD, $options);

        // Get the value set for the timezone in the database
        $stmt = $GLOBALS['db_global']->prepare("
            SELECT 
                `value` 
            FROM 
                `settings` 
            WHERE 
                `name` = 'default_timezone';
        ");
        $stmt->execute();

        // Store the list in the array
        $default_timezone = $stmt->fetch(PDO::FETCH_COLUMN);

        // If no timezone is set, set it to CST
        if (!$default_timezone) {

            $default_timezone = "America/Chicago";
            
            update_setting("default_timezone", $default_timezone);

        // otherwise, validate the timezone
        } else {
            
            // Get the list of timezones
            $timezones = timezone_list();
    
            // If the selected timezone is not valid, set it to CST
            if (!array_key_exists($default_timezone, $timezones)) {

                $default_timezone = "America/Chicago";

                update_setting("default_timezone", $default_timezone);

            }
        }

        // Set the timezone for PHP date functions
        date_default_timezone_set($default_timezone);

        // Set the simplerisk timezone for any datetime functions
        $offset = currentTimezoneOffset();

        // Setting the connection's timezone to the timezone set in the database
        $GLOBALS['db_global']->exec("SET time_zone = " . $GLOBALS['db_global']->quote(currentTimezoneOffset()));

    	// FOR DEBUGGING DATABASE CONNECTIONS ONLY
    	/*
    	$log_file = "/tmp/debug_log";
    	$connection = new PDO("mysql:charset=UTF8;dbname=".DB_DATABASE.";host=".DB_HOSTNAME.";port=".DB_PORT,DB_USERNAME,DB_PASSWORD, $options);
    	$stmt = $connection->prepare("SHOW VARIABLES LIKE 'max_connections';");
    	$stmt->execute();
    	$results = $stmt->fetch();
    	$max_connections = $results['Value'];
    	$stmt = $connection->prepare("SHOW STATUS WHERE `variable_name` = 'Threads_connected';");
    	$stmt->execute();
    	$results = $stmt->fetch();
    	$current_connections = $results['Value'];
    	error_log(date('c')." Database Connections: ".$current_connections . " / " . $max_connections."\n", 3, $log_file);
    	$connection = null;
    	*/

        // Every query above succeeded, so the connection is genuinely usable.
        // Set last, and only here.
        $GLOBALS['db_connection_ready'] = true;

        return $GLOBALS['db_global'];

    } catch (PDOException $e) {

        // Log the connection failure so operators have a diagnostic that
        // matches the friendly "Unable to Communicate with the Database"
        // page's instruction to check the web server's error log. Direct
        // error_log() is used (not write_debug_log) because write_debug_log
        // calls get_setting() to read the log-level configuration, which
        // requires the database connection we just failed to open.
        error_log("[SimpleRisk] Database connection failed: " . $e->getMessage());

        // We were unable to connect to the SimpleRisk database
        require_once(realpath(__DIR__ . '/healthcheck.php'));
        unable_to_communicate_with_database();

    }

    return null;

}


/**
 * Returns the current UTC offset for a timezone.
 *
 * @param string|null $timezoneName IANA timezone name or null for PHP default
 * @param bool $returnSeconds When true, returns offset in seconds; otherwise '+HH:MM'
 * @return int|string
 * @throws Exception If timezone name is invalid
 *
 *
 *
 * Examples:
 *
 * currentTimezoneOffset();
 * // "+01:00" (depends on PHP default TZ)
 *
 * currentTimezoneOffset('Europe/Budapest');
 * // "+01:00" or "+02:00"
 *
 * currentTimezoneOffset('Europe/Budapest', true);
 * // 3600 or 7200
 */
function currentTimezoneOffset(?string $timezoneName = null, bool $returnSeconds = false) {
    $tz = $timezoneName !== null
            ? new DateTimeZone($timezoneName)
            : new DateTimeZone(date_default_timezone_get());

    $now = new DateTimeImmutable('now', $tz);
    $seconds = $tz->getOffset($now);

    if ($returnSeconds) {
        return $seconds;
    }

    $sign = $seconds < 0 ? '-' : '+';
    $seconds = abs($seconds);

    return sprintf(
            '%s%02d:%02d',
            $sign,
            intdiv($seconds, 3600),
            intdiv($seconds % 3600, 60)
    );
}



