/***************************************
 * FUNCTION: TEAMS THE LOGIN USER IS A MEMBER OF*
 ***************************************/
function get_teams_by_login_user(){
    // Open the database connection
    $db = db_open();

    // Order by name
    if (!team_separation_extra()){
        $stmt = $db->prepare("SELECT * FROM `team` ORDER BY name");
    }else{
        // Include the team separation extra
        require_once(realpath(__DIR__ . '/../extras/separation/index.php'));

        // Get the teams the user is assigned to
        $user_teams = implode(",", get_user_teams($_SESSION['uid']));

        $stmt = $db->prepare("
            SELECT
                *
            FROM
                `team`
            WHERE
                FIND_IN_SET(`value`, '{$user_teams}')
            ORDER BY
                `name`;
        ");
    }

    $stmt->execute();

    // Store the list in the array
    $array = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Close the database connection
    db_close($db);

    return $array;
}

/*****************************************************************
 * FUNCTION: SANITIZE TEAMS REQUESTED FROM AN AUTHENTICATED USER *
 * $team_options: the caller's own accessible team list, as      *
 * returned by get_teams_by_login_user() (optionally with the    *
 * synthetic "Unassigned" 0 entry unshifted on) -- this already  *
 * collapses to every team when the Separation Extra isn't       *
 * active, and to only the user's own teams when it is.          *
 * $requested: the requested team ids, either a comma-separated  *
 * string (e.g. $_GET['teams']) or an array (e.g. $_POST['teams'] *
 * from a multiselect), or null/anything else when absent.       *
 * Returns the requested ids intersected with $team_options, so  *
 * a caller can never widen its scope past its own team access   *
 * by naming another team's id; absent input falls back to the   *
 * caller's full accessible list, matching prior default         *
 * behavior for pages that had no explicit request value.        *
 *****************************************************************/
function sanitize_requested_teams($team_options, $requested) {
    $allowed = [];
    if (is_array($team_options)) {
        foreach ($team_options as $team_option) {
            $allowed[] = (int) $team_option['value'];
        }
    }

    if (is_array($requested)) {
        $requested_ids = array_map('intval', array_filter($requested, 'ctype_digit'));
        return array_values(array_intersect($requested_ids, $allowed));
    }

    if (!is_string($requested)) {
        return $allowed;
    }

    $requested_ids = array_map('intval', array_filter(explode(',', $requested), 'ctype_digit'));
    return array_values(array_intersect($requested_ids, $allowed));
}

/***************************************
 * FUNCTION: GET TABLE ORDERED BY NAME *
 ***************************************/
function get_table_ordered_by_name($table_name) {

    // Open the database connection
    $db = db_open();

    // Create the query statement
    $stmt = $db->prepare("
        SELECT
            * 
        FROM 
            `{$table_name}` 
        ORDER BY 
            name
    ");

    // Execute the database query
    $stmt->execute();

    // Store the list in the array
    $array = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Close the database connection
    db_close($db);

    // Try decrypt if encrypted fields
    if ($table_name == "frameworks" || $table_name == "parent_frameworks" || $table_name == "projects") {

        // For each option
        foreach ($array as &$option) {

            // Try to decrypt it
            $option['name'] = try_decrypt($option['name']);

        }

        usort($array, function($a, $b) {
            return strcmp(strtolower(trim($a['name'])), strtolower(trim($b['name'])));
        });

    }
    
    return $array;

}

/******************************
 * FUNCTION: GET CUSTOM TABLE *
 *
 * Some info on the user management for some of the options.
 * "user"/"team": Will return the users/teams of the selected business unit (EVEN FOR ADMINS) when the Organizational Hierarchy Extra is enabled. Use it outside of admin-only areas
 * "user_all"/"team_all": Will return every user/team, ignoring the selected business unit. Use it ONLY inside of admin-only areas
 * "enabled/disabled_users": Will return the enabled/disabled users of the selected business unit(EVEN FOR ADMINS). Use it outside of admin-only area
 * "enabled/disabled_users_all": Will return the enabled/disabled users, ignoring the selected business unit. Use it ONLY inside of admin-only area
 *
 ******************************/
function get_custom_table($type) {

    // Open the database connection
    $db = db_open();

    // to notify that the result is supposed to be fetched as grouped
    $grouped = false;
    $encryption = encryption_extra();
    $stmt = null;
    $array = [];

    // Array of CVSS values
    $allowed_cvss_values = array('AccessComplexity', 'AccessVector', 'Authentication', 'AvailabilityRequirement', 'AvailImpact', 'CollateralDamagePotential', 'ConfidentialityRequirement', 'ConfImpact', 'Exploitability', 'IntegImpact', 'IntegrityRequirement', 'RemediationLevel', 'ReportConfidence', 'TargetDistribution');

    // If we want users, or want every user regardless of business unit
    if (in_array($type, ["user", "user_all"])) {

        // SR-1954: BU-scope for every user, admins included -- "user_all" is
        // the explicit escape hatch for admin-area screens (e.g. deleting a
        // user, resetting a password/MFA for a user) that must be able to
        // reach a user outside the viewer's own selected business unit.
        if ($type == "user" && organizational_hierarchy_extra()) {

            $stmt = $db->prepare("
                SELECT
                    `u`.*
                FROM
                    `user` u
                    INNER JOIN `user_to_team` u2t ON `u2t`.`user_id` = `u`.`value`
                    INNER JOIN `business_unit_to_team` bu2t ON `u2t`.`team_id` = `bu2t`.`team_id`
                WHERE
                    `bu2t`.`business_unit_id` = :selected_business_unit
                GROUP BY
                    `u`.`value`
                ORDER BY
                    `u`.`name`;
            ");

            if (!isset($_SESSION['selected_business_unit'])) {
                require_once(realpath(__DIR__ . '/../extras/organizational_hierarchy/index.php'));
                $selected_business_unit = get_selected_business_unit($_SESSION['uid']);
            } else {
                $selected_business_unit = $_SESSION['selected_business_unit'];
            }

            $stmt->bindParam(":selected_business_unit", $selected_business_unit, PDO::PARAM_INT);

        } else {
            $stmt = $db->prepare("SELECT * FROM `user` ORDER BY `name`;");
        }

    // If we want enabled/disabled users or want the enabled users without caring for business units
    } else if (in_array($type, ["enabled_users", "disabled_users", "enabled_users_all", "disabled_users_all"])) { // $type == "enabled_users" || $type == "disabled_users" || $type == "enabled_users_all") {
        
        if (in_array($type, ["enabled_users", "disabled_users"]) && organizational_hierarchy_extra()) {

            // The business-unit membership test is a SEMI-join (EXISTS), not a
            // second pair of INNER JOINs onto `user_to_team`/`business_unit_to_team`.
            // Both shapes select exactly the same users -- the INNER JOIN pair only
            // ever asked "does this user have at least one team in the selected
            // business unit?", and GROUP BY `u`.`value` + GROUP_CONCAT(DISTINCT ...)
            // collapsed the duplicate rows back out again -- but the JOIN form pays
            // for a full cross product of `user_to_team` against ITSELF for every
            // user before collapsing it. On a dataset of the size this was measured
            // against -- a few hundred users carrying dozens of team memberships
            // each -- that is upwards of a MILLION intermediate rows funneled
            // through a temporary table and a filesort: ~950-1,230 ms for a result
            // set of under 200 rows. The EXISTS form lets MySQL stop at the first
            // matching team per user (FirstMatch), leaving only the single
            // `user_to_team` join the `teams` column actually needs: ~23 ms for a
            // byte-identical result set (verified row-by-row, `teams` string
            // included, for both enabled=1 and enabled=0).
            //
            // Intentionally stated as an order of magnitude rather than exact row
            // counts: the numbers this was first measured against drifted within
            // weeks as the dev dataset grew, and a comment that has to be re-derived
            // every time someone adds a user stops being maintained. The argument
            // does not depend on the exact figures -- see the scaling note below.
            //
            // Do NOT "simplify" this back into a join -- it is not a stylistic
            // choice, and the cost is invisible on a small dataset because it
            // scales with the SQUARE of a user's team count.
            $stmt = $db->prepare("
                SELECT
                    `u`.*, GROUP_CONCAT(DISTINCT `t`.`value`) as teams
                FROM
                    `user` u
                    LEFT JOIN `user_to_team` u2t ON `u2t`.`user_id` = `u`.`value`
                    LEFT JOIN `team` t ON `u2t`.`team_id` = `t`.`value`
                WHERE
                    `u`.`enabled` = :enabled
                    AND EXISTS (
                        SELECT
                            1
                        FROM
                            `user_to_team` u2t_bu
                            INNER JOIN `business_unit_to_team` bu2t ON `bu2t`.`team_id` = `u2t_bu`.`team_id`
                        WHERE
                            `u2t_bu`.`user_id` = `u`.`value`
                            AND `bu2t`.`business_unit_id` = :selected_business_unit
                    )
                GROUP BY
                    `u`.`value`
                ORDER BY
                    `u`.`name`;
            ");

            if (!isset($_SESSION['selected_business_unit'])) {
                require_once(realpath(__DIR__ . '/../extras/organizational_hierarchy/index.php'));
                $selected_business_unit = get_selected_business_unit($_SESSION['uid']);
            } else {
                $selected_business_unit = $_SESSION['selected_business_unit'];
            }

            $stmt->bindParam(":selected_business_unit", $selected_business_unit, PDO::PARAM_INT);

        } else {
            $stmt = $db->prepare("
                SELECT
                    `u`.*, GROUP_CONCAT(DISTINCT `t`.`value`) as teams
                FROM
                    `user` u
                    LEFT JOIN `user_to_team` u2t ON `u2t`.`user_id` = `u`.`value`
                    LEFT JOIN `team` t ON `u2t`.`team_id` = `t`.`value`
                WHERE
                    `u`.`enabled` = :enabled
                GROUP BY 
                    `u`.`value`
                ORDER BY
                    `u`.`name`;
            ");
        }

        $enabled = in_array($type, ["enabled_users", "enabled_users_all"]) ? 1 : 0;
        $stmt->bindParam(":enabled", $enabled, PDO::PARAM_INT);

    // If we want a languages table
    } else if ($type == "languages") {

        $stmt = $db->prepare("
            SELECT 
                value, full as name 
            FROM 
                languages 
            ORDER BY 
                name
        ");
        
    // If we want a CVSS scoring table
    } else if (in_array($type, $allowed_cvss_values)) {

        $stmt = $db->prepare("
            SELECT 
                * 
            FROM 
                CVSS_scoring 
            WHERE 
                metric_name = :type 
            ORDER BY 
                id
        ");
        $stmt->bindParam(":type", $type, PDO::PARAM_STR, 30);

    // If we want a family table
    } else if ($type == "family") {

        $stmt = $db->prepare("
            SELECT 
                value, name as name 
            FROM 
                family 
            ORDER BY 
                name
        ");

    // If we want a frameworks table
    } else if ($type == "frameworks") {
        
        $stmt = $db->prepare("
            SELECT 
                value, name 
            FROM 
                frameworks 
            WHERE 
                status=1 
            ORDER BY 
                `order`
        ");

    // If we want a date_formats table
    } else if ($type == "date_formats") {

        $stmt = $db->prepare("
            SELECT 
                value, value as name 
            FROM 
                date_formats;
        ");

    // If we want a parent frameworks from frameworks table
    } else if ($type == "parent_frameworks") {

        $stmt = $db->prepare("
            SELECT 
                value, name 
            FROM 
                frameworks 
            WHERE 
                parent=0 
            ORDER BY 
                name
        ");

    // If we want the framework controls
    } else if ($type == "framework_controls") {

        $stmt = $db->prepare("
            SELECT 
                `id` as value, `short_name` as name 
            FROM 
                `framework_controls` 
            WHERE 
                `deleted`=0 
            ORDER BY 
                `short_name`;
        ");

    // If we want the framework controls
    } else if ($type == "framework_control_tests") {

        $stmt = $db->prepare("
            SELECT 
                `id` as value, `name` 
            FROM 
                `framework_control_tests` 
            ORDER BY 
                `name`;
        ");

    // If we want the tags used on risks
    } else if ($type == "risk_tags") {

        $stmt = $db->prepare("
            SELECT
                `t`.`id` as value, `t`.`tag` as name
            FROM
                `tags` `t`
                INNER JOIN `tags_taggees` `tt` ON `t`.`id`=`tt`.`tag_id`
            WHERE
                `tt`.`type`='risk'
            GROUP BY 
                `t`.`tag`
            ORDER BY 
                `t`.`tag`;
        ");

        
    // If we want the tags used on assets
    } else if ($type == "asset_tags") {

        $stmt = $db->prepare("
            SELECT
                `t`.`id` as value, `t`.`tag` as name
            FROM
                `tags` `t`
                INNER JOIN `tags_taggees` `tt` ON `t`.`id`=`tt`.`tag_id`
            WHERE
                `tt`.`type`='asset'
            GROUP BY 
                `t`.`tag`
            ORDER BY 
                `t`.`tag`;
        ");

    // If we want the test results(used for setting the test result)
    } else if ($type == "test_results") {

        $stmt = $db->prepare("
            SELECT 
                name as value, name 
            FROM 
                test_results 
            ORDER BY 
                name
        ");

    // If we want the test results(used for filtering on the test result)
    } else if ($type == "test_results_filter") {

        $stmt = $db->prepare("
            SELECT 
                value, name 
            FROM 
                test_results 
            ORDER BY 
                name
        ");

    } else if ($type == "policies") {

        $stmt = $db->prepare("
            SELECT 
                id as value, document_name as name 
            FROM 
                documents 
            where 
                document_type = 'policies' 
            ORDER BY 
                document_name
            ");

    // If we want teams, or want every team regardless of business unit
    } else if (in_array($type, ["team", "team_all"])) {

        // SR-1954: BU-scope for every viewer, admins included -- "team_all" is
        // the explicit escape hatch for admin-area screens (e.g. renaming or
        // deleting a team, managing team membership) that must be able to
        // reach a team outside the viewer's own selected business unit.
        //
        // Resolves the business unit the same way the "user"/"enabled_users"
        // branches do (session first, DB fallback) rather than joining live
        // against user.selected_business_unit -- the two must agree, since
        // set_selected_business_unit() writes both in the same request, but a
        // second concurrent session could otherwise see the DB-fresh value
        // here while this session's own $_SESSION still reports the old one.
        if ($type == "team" && organizational_hierarchy_extra()) {

            $stmt = $db->prepare("
                SELECT
                    `t`.*
                FROM
                    `business_unit_to_team` bu2t
                    INNER JOIN `team` t ON `t`.`value` = `bu2t`.`team_id`
                WHERE
                    `bu2t`.`business_unit_id` = :selected_business_unit
                ORDER BY
                    `t`.`name`;
            ");

            if (!isset($_SESSION['selected_business_unit'])) {
                require_once(realpath(__DIR__ . '/../extras/organizational_hierarchy/index.php'));
                $selected_business_unit = get_selected_business_unit($_SESSION['uid']);
            } else {
                $selected_business_unit = $_SESSION['selected_business_unit'];
            }

            $stmt->bindParam(":selected_business_unit", $selected_business_unit, PDO::PARAM_INT);

        } else {

            $stmt = $db->prepare("
                SELECT
                    *
                FROM
                    `team`
                ORDER BY
                    name
            ");

        }

    } else if ($type == "risk_catalog") {

        $stmt = $db->prepare("
            SELECT 
                id as value, CONCAT(`number`, ' - ', `name`) AS name 
            FROM 
                `risk_catalog` 
            ORDER BY 
                `grouping`,`order`;
        ");

    } else if ($type == "threat_catalog") {
        
        $stmt = $db->prepare("
            SELECT 
                id as value, CONCAT (`number`, ' - ', `name`) AS name 
            FROM 
                `threat_catalog` 
            ORDER BY 
                `grouping`, `order`;
        ");

    } else if (in_array($type, ["remote_team-SAML", "remote_role-SAML", "remote_team-LDAP"]) && custom_authentication_extra()) {

        list($table, $remote_type) = explode('-', $type);
        $stmt = $db->prepare("
            SELECT
                *
            FROM
                `{$table}`
            WHERE
                `type` = '{$remote_type}'
            ORDER BY
                `name`;
        ");

    } else if ($type == "data_classification") {

        $stmt = $db->prepare("
            SELECT 
                id as value, name 
            FROM 
                `data_classification` 
            ORDER BY 
                `order`
        ");

    } else if (in_array($type, ['risk_catalog_grouped', 'threat_catalog_grouped'])) {
        
        $catalog_type = $type === 'risk_catalog_grouped' ? 'risk' : 'threat';
        $grouped = true;
        $stmt = $db->prepare("
            SELECT
            	`g`.`name`,
                `c`.`id` AS value,
                CONCAT(`c`.`number`, ' - ', `c`.`name`) AS name
            FROM
                `{$catalog_type}_catalog` c
                LEFT JOIN `{$catalog_type}_grouping` g ON `c`.`grouping` = `g`.`value`
            ORDER BY
                `g`.`order`,
                `c`.`order`;
        ");

    } else if ($type == "asset_valuation") {

        $stmt = $db->prepare("
            SELECT 
                * 
            FROM 
                `asset_values` 
            ORDER BY 
                `min_value` ASC;
        ");

    } else if ($type == "risks" || $type == "risks_with_id") {

        $stmt = $db->prepare("
            SELECT 
                `id` AS value , `subject` AS name 
            FROM 
                `risks` 
            ORDER BY 
                `" . ($encryption ? 'order_by_subject' : 'subject') . "` ASC, `id` ASC;
        ");

    }

    // Execute the database query
    if ($stmt) {
        $stmt->execute();

        // Store the list in the array
        $array = $stmt->fetchAll($grouped ? PDO::FETCH_GROUP|PDO::FETCH_ASSOC : PDO::FETCH_ASSOC);
    }

    // Close the database connection
    db_close($db);

    // Try decrypt if encrypted fields
    if ($type == "frameworks" || $type == "parent_frameworks" || $type == "projects") {

        // For each option
        foreach ($array as &$option) {
            // Try to decrypt it
            $option['name'] = try_decrypt($option['name']);
        }

        usort($array, function($a, $b){
            return strcmp( strtolower(trim($a['name'])), strtolower(trim($b['name'])));
        });
        
    }

    if ($type == "risks" || $type == "risks_with_id") {

        if ($encryption) {
            // Decrypt the subjects
            foreach ($array as &$option) {
                $option['name'] = try_decrypt($option['name']);
            }
        }

        if ($type == "risks_with_id") {
            foreach ($array as &$option) {
                $risk_id = (int)$option['value'] + 1000;
                $option['name'] = "[{$risk_id}] {$option['name']}";
            }
        }
    }
    
    if ($type == "asset_valuation") {

        global $escaper;
        $currency_sign = $escaper->escapeHtml(get_setting("currency"));
        $result = [];
        foreach ($array as $asset_value) {

            $valuation_level_name = !empty($asset_value['valuation_level_name']) ? " ({$escaper->escapeHtml($asset_value['valuation_level_name'])})" : '';

            if ($asset_value['min_value'] === $asset_value['max_value']) {
                $asset_value_name = "{$currency_sign}{$escaper->escapeHtml(number_format($asset_value['min_value']))}{$valuation_level_name}";
            } else {
                $asset_value_name = "{$currency_sign}{$escaper->escapeHtml(number_format($asset_value['min_value']))} to {$currency_sign}{$escaper->escapeHtml(number_format($asset_value['max_value']))}{$valuation_level_name}";
            }

            $result []= ['value' => $asset_value['id'], 'name' => $asset_value_name];
        }

        return $result;

    }

    // Localize test results names
    if ($type == "test_results" || $type == "test_results_filter") {

        global $lang;
        // For each option
        foreach ($array as &$option) {
            // Try to localize it
            $option['name'] = $lang[$option['name']];
        }
    }

    return $array;

}

/************************************
 * FUNCTION: GET OPTIONS FROM TABLE *
 * Some info on the user management for some of the options.
 * "user"/"team": Will return the users/teams of the selected business unit (EVEN FOR ADMINS) when the Organizational Hierarchy Extra is enabled. Use it outside of admin-only areas
 * "user_all"/"team_all": Will return every user/team, ignoring the selected business unit. Use it ONLY inside of admin-only areas
 * "enabled/disabled_users": Will return the enabled/disabled users of the selected business unit(EVEN FOR ADMINS). Use it outside of admin-only area
 * "enabled/disabled_users_all": Will return the enabled/disabled users, ignoring the selected business unit. Use it ONLY inside of admin-only area
 ************************************/
function get_options_from_table($name) {

    global $lang, $escaper;

    // If we want a table that should be ordered by name instead of value
    if (in_array($name, array("category", "technology",
        "location", "regulation", "projects", "file_types", "file_type_extensions",
        "planning_strategy", "close_reason", "status", "source", "import_export_mappings", "test_status"))) {

        $options = get_table_ordered_by_name($name);

    } else if (in_array($name, array("user", "user_all", "team", "team_all", "enabled_users", "disabled_users", "enabled_users_all", "disabled_users_all", "languages", "family", "date_formats",
            "parent_frameworks", "frameworks", "framework_controls", "risk_tags", "asset_tags", "test_results", "test_results_filter",
            "policies", "framework_control_tests", "risk_catalog", "threat_catalog", "risk_catalog_grouped", "threat_catalog_grouped", "remote_team-SAML",
            "remote_role-SAML", "remote_team-LDAP", "data_classification", "asset_valuation", "risks", "risks_with_id"))) {

        $options = get_custom_table($name);

    } else if ($name === "yes_no") {

        $options = [
            [
                'value' => 0,
                'name' => $lang['No']
            ],
            [
                'value' => 1,
                'name' => $lang['Yes']
            ]
        ];
        
    // Otherwise
    } else {

        // Get the list of options
        $options = get_table($name);

    }

    // Sort options array
    if ($name == "parent_frameworks" || $name == "projects") {
        uasort($options, function($a, $b) {
            if ($a['name'] == $b['name']) return 0;
            return ($a['name'] < $b['name']) ? -1 : 1;
        });
    }

    return $options;
    
}


/*****************************
 * FUNCTION: GET RISK LEVELS *
 *****************************/
function get_risk_levels()
{
    // Open the database connection
    $db = db_open();

    // Query the database
    $stmt = $db->prepare("SELECT * FROM `risk_levels` ORDER BY value");
    $stmt->execute();

    // Store the list in the array
    $array = $stmt->fetchAll();

    // Close the database connection
    db_close($db);

    return $array;
}

/*******************************
 * FUNCTION: GET REVIEW LEVELS *
 *******************************/
function get_review_levels()
{
    // Open the database connection
    $db = db_open();

    // Query the database
    $stmt = $db->prepare("SELECT * FROM review_levels GROUP BY id ORDER BY value");
    $stmt->execute();

    // Store the list in the array
    $array = $stmt->fetchAll();

    // Close the database connection
    db_close($db);

    return $array;
}

