    // Close the database connection
    db_close($db);

    return $stmt->rowCount();
}

/****************************************************************************
 * FUNCTION: REDACT SENSITIVE SETTING VALUE                                 *
 ****************************************************************************
 * add_setting() and update_or_insert_setting() log the value they just wrote
 * at `debug`, which is genuinely useful for diagnosing a misconfigured
 * instance -- except when the settings row holds a credential. This decides
 * which is which, and returns the value to log.
 *
 * Match on the SUFFIX, not a substring. SimpleRisk's credential settings END
 * with the noun naming the secret, while the names that merely mention one end
 * with the thing they actually measure or toggle:
 * password_reset_token_expiration and password_reset_attempt_lockout_time are
 * durations, and every pass_policy_* is a policy knob. A substring match on
 * "password" would redact all of those and blind the debug log for exactly the
 * settings people debug most.
 *
 * The suffixes are matched case-insensitively against the WHOLE name and are
 * deliberately BARE nouns -- 'key', not 'api_key'. Setting names do not share a
 * casing or separator convention: SAML_SP_KEY (a PEM private key) is screaming
 * snake case, JiraUserAPIKey and UCFAPIKey are camel case with no separator at
 * all, services_api_key is snake case. A compound suffix like 'api_key' matches
 * only the last of those and silently leaks the first two, which is exactly the
 * bug the first version of this function shipped with.
 *
 * $never_sensitive is the escape hatch for a name that ends with a credential
 * noun but holds no credential. Keep it SHORT and keep each entry justified --
 * every addition is a value that will be logged in full, so the burden of proof
 * is on the exception, not on the redaction.
 *
 * A credential setting that ends with something else entirely (something like
 * `smtp_password_encrypted`) still will not match. Add its suffix here, or
 * better, name it so it ends with the secret.
 ****************************************************************************/
function redact_sensitive_setting_value($name, $value)
{
    // Boolean gate on whether the API accepts a key in the URL -- not a key.
    static $never_sensitive = [
        'api_allow_url_key',
    ];

    static $sensitive_suffixes = [
        'password', 'passwd', 'pwd', 'secret', 'salt', 'token',
        'key', 'credential', 'credentials', 'pepper',
    ];

    $lowered = strtolower((string)$name);

    if (in_array($lowered, $never_sensitive, true)) return (string)$value;

    foreach ($sensitive_suffixes as $suffix)
    {
        if (str_ends_with($lowered, $suffix)) return '[redacted]';
    }

    return (string)$value;
}

/*************************
 * FUNCTION: ADD SETTING *
 *************************/
function add_setting($name, $value, ?PDO $db = null): void
{
    $close_db = false;

    if ($db === null)
    {
        $db = db_open();
        $close_db = true;
    }

    try {
        $stmt = $db->prepare("
            INSERT IGNORE INTO settings (`name`, `value`)
            VALUES (:name, :value)
        ");
        $stmt->bindParam(":name", $name, PDO::PARAM_STR);
        $stmt->bindParam(":value", $value, PDO::PARAM_STR);
        $stmt->execute();

        $affectedRows = $stmt->rowCount();
        $logged_value = redact_sensitive_setting_value($name, $value);
        if ($affectedRows === 1) {
            write_debug_log("The setting '{$name}' was added with value '{$logged_value}'.", "debug");
        } else if ($affectedRows === 2) {
            write_debug_log("The setting '{$name}' was updated to value '{$logged_value}'.", "debug");
        }

        // Update cached value
        $GLOBALS['setting_' . $name] = $value;

    } catch (Exception $e) {
        write_debug_log(
                "[add_setting] DB error adding setting '{$name}': " . $e->getMessage(),
                "error"
        );
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/***************************************
 * FUNCTION: UPDATE OR INSERT SETTINGS *
 ***************************************/
function update_or_insert_setting($name, $value, ?PDO $db = null): bool
{
    $close_db = false;

    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        $stmt = $db->prepare("
            REPLACE INTO settings (`name`, `value`) 
            VALUES (:name, :value)
        ");
        $stmt->bindParam(":name", $name, PDO::PARAM_STR);
        $stmt->bindParam(":value", $value, PDO::PARAM_STR);
        $stmt->execute();

        $affectedRows = $stmt->rowCount();
        $logged_value = redact_sensitive_setting_value($name, $value);
        if ($affectedRows === 1) {
            write_debug_log("The setting '{$name}' was added with value '{$logged_value}'.", "debug");
        } else if ($affectedRows === 2) {
            write_debug_log("The setting '{$name}' was updated to value '{$logged_value}'.", "debug");
        }

        // Update cached value
        $GLOBALS['setting_' . $name] = $value;

        return true;

    } catch (Exception $e) {
        write_debug_log(
                "[update_or_insert_setting] DB error updating/inserting setting '{$name}': " . $e->getMessage(),
                "error"
        );
        return false;
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/*******************************************************************************
 * FUNCTION: HASH MANAGEMENT API KEY                                            *
 * SR-1651: derive the stored form of the management API key (settings.api_key) *
 * from its plaintext. It's a high-entropy generate_token() value, so a fast    *
 * SHA-256 is the right primitive (bcrypt's slowness buys nothing for a random  *
 * token and this is verified per management-API request). The 'sha256:' prefix *
 * is an explicit marker so verify_management_api_key() can distinguish a hashed *
 * value from a legacy plaintext one without guessing by length/charset.        *
 *******************************************************************************/
function hash_management_api_key($plaintext) {
    return 'sha256:' . hash('sha256', (string)$plaintext);
}

/*******************************************************************************
 * FUNCTION: VERIFY MANAGEMENT API KEY                                          *
 * SR-1651: constant-time check of a presented management API key against the   *
 * stored settings.api_key. Transition-tolerant: a value tagged 'sha256:' is     *
 * verified against the hash; a legacy (un-tagged) plaintext value is compared   *
 * directly, so a key saved before the hashing migration still authenticates —   *
 * critical because the migration that hashes the value runs inside the upgrade  *
 * reached via this very key. $stored is injectable for testing; it defaults to  *
 * settings.api_key.                                                            *
 *******************************************************************************/
function verify_management_api_key($presented, $stored = null) {
    if ($stored === null) {
        $stored = get_setting('api_key');
    }
    if (!is_string($stored) || $stored === '' || !is_string($presented) || $presented === '') {
        return false;
    }
    if (strncmp($stored, 'sha256:', 7) === 0) {
        return hash_equals($stored, hash_management_api_key($presented));
    }
    // Legacy plaintext (not yet migrated) — constant-time compare.
    return hash_equals($stored, $presented);
}

/****************************
 * FUNCTION: UPDATE SETTING *
 ****************************/
function update_setting($name, $value, ?PDO $db = null): bool
{
    global $escaper;
    $close_db = false;

    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    // Quick check: if value hasn't changed, return early
    $old_value = get_setting($name, db: $db);
    if ($old_value == $value) {
        write_debug_log("Setting {$name} was not changed. Nothing to do.", "debug");
        return false;
    }

    try {
        $stmt = $db->prepare("
            INSERT INTO settings (`name`, `value`) 
            VALUES (:name, :value)
            ON DUPLICATE KEY UPDATE `value` = :value_update
        ");
        $stmt->bindParam(":name", $name, PDO::PARAM_STR, 100);
        $stmt->bindParam(":value", $value, PDO::PARAM_STR);
        $stmt->bindParam(":value_update", $value, PDO::PARAM_STR);
        $stmt->execute();

        // Update cache
        $GLOBALS['setting_' . $name] = $value;

        // Ensure session defaults for audit
        if (!isset($_SESSION['user'])) $_SESSION['user'] = "System User";
        if (!isset($_SESSION['uid'])) $_SESSION['uid'] = -1;

        // Audit log
        $risk_id = 1000;
        if ($name === "max_upload_size") {
            $message = "The maximum upload file size was updated by \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
        } else {
            $message = "A setting value named \"{$name}\" was updated by \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
        }
        write_log($risk_id, $_SESSION['uid'] ?? 0, $message);

        return true;

    } catch (Exception $e) {
        write_debug_log(
                "[update_setting] Error updating setting '{$name}': " . $e->getMessage(),
                "error"
        );
        return false;
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/****************************
 * FUNCTION: DELETE SETTING *
 ****************************/
function delete_setting($name, ?PDO $db = null): void
{
    $close_db = false;

    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        $stmt = $db->prepare("
            DELETE FROM settings
            WHERE name = :name
        ");
        $stmt->bindParam(":name", $name, PDO::PARAM_STR, 50);
        $stmt->execute();

        // Clear cached value
        $key = 'setting_' . $name;
        if (isset($GLOBALS[$key])) {
            unset($GLOBALS[$key]);
        }
    } catch (Exception $e) {
        write_debug_log(
                "[delete_setting] DB error deleting setting '{$name}': " . $e->getMessage(),
                "error"
        );
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/**********************************************
 * FUNCTION: SSL EXTERNAL VERIFY ENABLED       *
 * Whether outbound calls to external services *
 * should verify the TLS certificate.          *
 **********************************************/
/**
 * Secure by default: verifies the certificate unless an admin has explicitly
 * disabled it (the 'ssl_certificate_check_external' setting is the string '0').
 * An unset setting — e.g. on a fresh install before it is seeded — still
 * verifies. The setting is only ever written as the integer 1 or 0
 * (admin/settings_security.php and includes/upgrade.php), so the strict `!== '0'`
 * comparison is exact: never the strings "true"/"false".
 */
function ssl_external_verify_enabled(?PDO $db = null): bool
{
    return get_setting('ssl_certificate_check_external', false, true, $db) !== '0';
}

/*************************
 * FUNCTION: GET SETTING *
 *************************/
function get_setting($setting, $default = false, $cached = true, ?PDO $db = null)
{
    $close_db = false;
    $key = 'setting_' . $setting;

    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try
    {
        // If we want to cache the setting
        if ($cached)
        {
            if (isset($GLOBALS[$key]))
            {
                return $GLOBALS[$key];
            }
        }

        // Get the setting
        $stmt = $db->prepare("
            SELECT 
                * 
            FROM 
                settings 
            where 
                name=:setting
        ");
        $stmt->bindParam(":setting", $setting, PDO::PARAM_STR, 100);
        $stmt->execute();

        // Store the list in the array
        $array = $stmt->fetchAll();
        $value = $array ? trim($array[0]['value']) : false;
        $result = ($value === false) ? $default : $value;

        // If we want to cache the setting
        if ($cached)
        {
            // Put the setting in the global variable
            $GLOBALS[$key] = $result;
        }

        return $result;
    } catch (Exception $e) {
        write_debug_log(
                "[get_setting] DB error retrieving setting '{$setting}': " . $e->getMessage(),
                "error"
        );
        return false;
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/************************************************************
 * FUNCTION: GET CURRENCY SYMBOL                            *
 * Returns the configured currency symbol from the settings *
 * with a "$" fallback. Pass $sql_safe = true when the      *
 * value will be embedded in an SQL CONCAT literal so any   *
 * single quotes are stripped (defense-in-depth — prefer a  *
 * parameterized query when possible).                      *
 ************************************************************/
function get_currency_symbol($sql_safe = false)
{
    $currency = get_setting('currency') ?: '$';
    if ($sql_safe) {
        $currency = str_replace("'", '', $currency);
    }
    return $currency;
}

/************************************************************
 * FUNCTION: GET SETTINGS                                   *
 * Gets a list of settings and returns it as an associative *
 * array where the key is the name of the setting and       *
 * the value is the actual value of said setting            *
 ************************************************************/
function get_settings($settings, ?PDO $db = null)
{
    $close_db = false;

    // Normalize settings list
    if (!is_array($settings)) {
        $settings = explode(',', $settings);
    }

    $settings = array_map('trim', $settings);
    if (empty($settings)) {
        return [];
    }

    // Build placeholders
    $params = [];
    $placeholders = [];

    foreach ($settings as $i => $setting) {
        $key = ":param{$i}";
        $placeholders[] = $key;
        $params[$key] = $setting;
    }

    $settings_in = implode(", ", $placeholders);

    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        $stmt = $db->prepare("
            SELECT
                name,
                value
            FROM
                settings
            WHERE
                name IN ({$settings_in})
        ");

        $stmt->execute($params);

        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);

        $results = [];
        foreach ($rows as $row) {
            $results[$row['name']] = $row['value'];
        }

        return $results;
    } catch (Exception $e) {
        write_debug_log(
                "[get_settings] DB error retrieving settings: " . $e->getMessage(),
                "error"
        );
        return [];
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/*********************************************************
 * FUNCTION: SETTING EXISTS                              *
 * Check whether a setting exists in the settings table. *
 *                                                       *
 * @param PDO|null $db                                   *
 * @param string $setting_name                           *
 * @return bool                                          *
 *********************************************************/
function setting_exists(string $setting_name, ?PDO $db = null): bool
{
    $close_db = false;

    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        $sql = "
            SELECT 1
            FROM settings
            WHERE name = :name
            LIMIT 1
        ";

        $stmt = $db->prepare($sql);
        $stmt->bindValue(':name', $setting_name, PDO::PARAM_STR);
        $stmt->execute();
        $setting_exists = (bool) $stmt->fetchColumn();

        // If the setting exists
        if ($setting_exists)
        {
            write_debug_log("[setting_exists] Found the '{$setting_name}' setting name in the settings table.", "debug");
        }
        else
        {
            write_debug_log("[setting_exists] Unable to find the '{$setting_name}' setting name in the settings table.", "debug");
        }

        return $setting_exists;
    } catch (Exception $e) {
        write_debug_log(
                "[setting_exists] DB error checking setting '{$setting_name}': " . $e->getMessage(),
                "error"
        );
        return false;
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/*********************************************************************
 * FUNCTION: ENSURE RANDOM SECRET SETTING                            *
 * Returns the value of a per-install random secret kept in the      *
 * settings table (SAML_SECRETSALT, api_key_pepper, ...), generating  *
 * it exactly once when absent.                                      *
 *                                                                   *
 * The insert is INSERT ... ON DUPLICATE KEY UPDATE `value` = `value` *
 * (a self-assignment no-op for a populated row), so two concurrent   *
 * first requests cannot clobber each other: whichever INSERT commits *
 * first wins and both re-read the same row. A leftover empty row is  *
 * treated as absent and filled in place, so it cannot wedge every    *
 * later call into the fail-closed throw. update_or_insert_setting()'s*
 * REPLACE INTO would leave a check-then-act race. The reads here     *
 * bypass get_setting()'s per-request cache; the one cache clear at    *
 * the top is for OTHER callers, whose earlier cached miss (false)     *
 * must not outlive the value this call stores. The re-read is retried*
 * briefly because get_setting() returns false on a caught exception  *
 * rather than throwing.                                               *
 *                                                                   *
 * Pass $db to reuse an open connection, as with get_setting().       *
 *                                                                   *
 * Fails closed: throws when no value can be read back. Returning the *
 * locally generated candidate instead would hand a losing writer a   *
 * secret that differs from the committed one, and anything derived   *
 * from it (session HMACs, key hashes) would silently diverge.        *
 *                                                                   *
 * $generated is set to true when this call created the value, so a  *
 * caller can react to a first-time generation.                      *
 *********************************************************************/
function ensure_random_secret_setting(string $name, int $bytes, ?bool &$generated = null, ?PDO $db = null): string
{
    $generated = false;

    // A caller that looked this setting up before it existed holds a cached
    // miss; clear it so its next ordinary read sees the value stored below.
    unset($GLOBALS['setting_' . $name]);

    $close_db = false;
    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        $existing = get_setting($name, false, false, $db);
        if (is_string($existing) && $existing !== '') {
            return $existing;
        }

        $candidate = bin2hex(random_bytes($bytes));

        $stmt = $db->prepare("
            INSERT INTO `settings` (`name`, `value`)
            VALUES (:name, :value)
            ON DUPLICATE KEY UPDATE `value` = IF(`value` = '', VALUES(`value`), `value`)
        ");
        $stmt->bindParam(":name", $name, PDO::PARAM_STR);
        $stmt->bindParam(":value", $candidate, PDO::PARAM_STR);
        $stmt->execute();

        $stored = false;
        for ($attempt = 1; $attempt <= 3; $attempt++) {
            $stored = get_setting($name, false, false, $db);
            if (is_string($stored) && $stored !== '') {
                break;
            }
            if ($attempt < 3) {
                usleep(20000);
            }
        }
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
    if (!is_string($stored) || $stored === '') {
        throw new RuntimeException("Could not read back the per-install secret setting {$name} after inserting it.");
    }

    $generated = ($stored === $candidate);
    if ($generated) {
        write_debug_log("Generated per-install secret setting {$name}.", 'notice');
    }

    return $stored;
}

/****************************
 * FUNCTION: RENAME SETTING *
 ****************************/
function rename_setting($from_setting_name, $to_setting_name, $setting_value = false, ?PDO $db = null)
{
    $close_db = false;

    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        // If a setting value was not provided
        if ($setting_value === false)
        {
            // Get the value from the current setting
            $setting_value = get_setting($from_setting_name, "", false);
            write_debug_log ("[rename_setting] No setting value was provided. Using the value '{$setting_value}' from the '{$from_setting_name}' setting.", "debug");
        }

        // Add or update the new setting
        update_or_insert_setting($to_setting_name, $setting_value);

        // Delete the old setting
        delete_setting($from_setting_name);

        write_debug_log("[rename_setting] Renamed setting from '{$from_setting_name}' to '{$to_setting_name}'.", "info");
    } catch (Exception $e) {
        write_debug_log(
                "[rename_setting] There was an error renaming the setting '{$from_setting_name}' to '{$to_setting_name}': " . $e->getMessage(),
                "error"
        );
        return false;
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/*******************************************************
 * FUNCTION: CONVERT DEFAULT DATE FORMAT TO PHP FORMAT *
 *******************************************************/
function get_default_date_format() {

    $default_date_format = get_setting("default_date_format");
    $php_date_format = str_ireplace("YYYY", "Y", $default_date_format);
    $php_date_format = str_ireplace("MM", "m", $php_date_format);
    $php_date_format = str_ireplace("DD", "d", $php_date_format);

    return $php_date_format;

}

/*******************************************************
 * FUNCTION: CONVERT DEFAULT DATE FORMAT FOR DATEPICKER *
 *******************************************************/
function get_default_date_format_for_datepicker() {
    $default_date_format = get_setting("default_date_format");
    $php_date_format = str_ireplace("YYYY", "yy", $default_date_format);
    $php_date_format = str_ireplace("MM", "mm", $php_date_format);
    $php_date_format = str_ireplace("DD", "dd", $php_date_format);
    return $php_date_format;
}

/******************************************************
 * FUNCTION: CONVERT DEFAULT DATE FORMAT TO JS FORMAT *
 ******************************************************/
function get_default_date_format_for_js()
{
    return get_setting("default_date_format");
}

function get_default_datetime_format_for_js() {
    return get_default_date_format_for_js() . " HH:mm:ss";
}
/************************************************************
 * FUNCTION: CONVERT DEFAULT DATE TIME FORMAT TO PHP FORMAT *
 ************************************************************/
function get_default_datetime_format($time_format = "H:i:s") {

    $format = get_default_date_format();

    return "{$format} {$time_format}";

}

/*********************************************************************************
 * FUNCTION: GET FORMATTED DATE/DATETIME                                         *
 *                                                                               *
 * Use it only on dates got from the database, as strtotime is not suited to be  *
 * used on user input since it can't handle all the date formats we support.     *
 *                                                                               *
 * On user input use the `get_standard_date_from_default_format` function before *
 * writing into the database                                                     *
 *********************************************************************************/
function format_date($date, $default = "")
{
    // If the date is not 0000-00-00
    if ($date && $date != "0000-00-00" && $date != "0000-00-00 00:00:00")
    {
        // Set it to the proper format
        return strtotime($date) ? date(get_default_date_format(), strtotime($date)) : "";
    }
    else return $default;
}

function format_datetime($date, $default = "", $timeformat = "H:i:s") {

    // If the date is not 0000-00-00
    if ($date && $date != "0000-00-00" && $date != "0000-00-00 00:00:00") {
        // Set it to the proper format
        return strtotime($date) ? date(get_default_datetime_format($timeformat), strtotime($date)) : "";
    } else {
        return $default;
    }
}

/******************************************************
 * FUNCTION: CONVERT EMPTY DATE VALUE TO EMTPY STRING *
 ******************************************************/
function trim_date($date, $default = "")
{
    // If the date is not 0000-00-00
    if ($date && stripos($date, "0000-00") === false)
    {
        // Set it to the proper format
        return $date;
    }
    else
    {
        return $default;
    }
}

/****************************************************************************
 * FUNCTION: GET STANDARD DATE FROM STRING FORMATTED BY DEFAULT DATE FORMAT *
 ****************************************************************************/
function get_standard_date_from_default_format($formatted_date, $time=false)
{
    // Return 0000-00-00 if formatted date is invalid or unset
    if(!$formatted_date || strpos($formatted_date, "0000")  !== false){
        return "0000-00-00";
    }

    // If time is requested
    if($time){
        // Get default date format
        $format = get_default_datetime_format("H:i:s");

        // Convert date string to Y-m-d H:i:s date
        $d = DateTime::createFromFormat($format, $formatted_date);
        $standard_date = $d ? $d->format('Y-m-d H:i:s') : "";
    }else{
        // Get default date format
        $format = get_default_date_format();

        // Convert date string to Y-m-d date
        $d = DateTime::createFromFormat($format, $formatted_date);
        $standard_date = $d ? $d->format('Y-m-d') : "";
    }

    return $standard_date;
}
/************************************************
 * FUNCTION: GET STANDARD DATE FROM DATE STRING *
 ************************************************/
function get_standard_date_from_date_string($date_string, $time=false)
{
    // Return 0000-00-00 if formatted date is invalid or unset
    if(!$date_string || strpos($date_string, "0000")  !== false){
        return "0000-00-00";
    }

    $d = new DateTime($date_string);
    // If time is requested
    if($time){
        $standard_date = $d ? $d->format('Y-m-d H:i:s') : "";
    }else{
        $standard_date = $d ? $d->format('Y-m-d') : "";
    }

    return $standard_date;
}

/**********************
 * FUNCTION: ADD NAME *
 **********************/
function add_name($table, $name, $size=20)
{
    global $escaper;
    if(!$name){
        return false;
    }

    // Check if the value already exists in the table
    $id = get_value_by_name($table, $name);

    // If the id was not returned
    if (!is_int($id))
    {
        // Open the database connection
        $db = db_open();

        // Add the name value pair into the table
        $stmt = $db->prepare("INSERT IGNORE INTO {$table} (`name`) VALUES (:name); ");

        // If size is null, no set param length
        if ($size === null)
        {
            $stmt->bindParam(":name", $name, PDO::PARAM_STR);
        }
        // If size is not null, no set param length
        else
        {
            $stmt->bindParam(":name", $name, PDO::PARAM_STR, $size);
        }
        $stmt->execute();
        $insertedId = $db->lastInsertId();

        // Audit log
        switch ($table)
        {
            case "projects":
                $risk_id = 1000;
                $message = "A new project \"" . try_decrypt($name) . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "category":
                $risk_id = 1000;
                $message = "A new category \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "team":
                $risk_id = 1000;
                $message = "A new team \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "technology":
                $risk_id = 1000;
                $message = "A new technology \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "location":
                $risk_id = 1000;
                $message = "A new location \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "source":
                $risk_id = 1000;
                $message = "A new source \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "regulation":
                $risk_id = 1000;
                $message = "A new control regulation \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "planning_strategy":
                $risk_id = 1000;
                $message = "A new planning strategy \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "close_reason":
                $risk_id = 1000;
                $message = "A new close reason \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "file_types":
                $risk_id = 1000;
                $message = "A new upload file type \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            case "control_class":
                $risk_id = 1000;
                $message = "A new control_class \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
            default:
                $risk_id = 1000;
                $message = "A new " . $table . " \"" . $name . "\" was added by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.";
                write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
                break;
        }

        // Close the database connection
        db_close($db);

        return $insertedId;
    }
    // If the value already exists in the table return the id for that value
    else return $id;
}

