    $stmt = $db->prepare("SELECT submission_date FROM mgmt_reviews WHERE risk_id=:risk_id ORDER BY submission_date DESC LIMIT 1");
    $stmt->bindParam(":risk_id", $risk_id, PDO::PARAM_INT);
    $stmt->execute();
    // Store the list in the array
    $array = $stmt->fetchAll();

    // Close the database connection
    db_close($db);

    // If the array is empty
    if (empty($array))
    {
            return "";
    }
    else return $array[0]['submission_date'];
}

/**
* Get next review date by risk scoring.
*
* @param mixed $risk_id
* @return string Raw date string (e.g. "2026-05-09" or "0000-00-00"); the caller is
*                responsible for HTML-escaping at output. The only consumer chain
*                (details.php -> edit_review_submission -> display_set_next_review_date_edit)
*                escapes via $escaper->escapeHtml() before rendering.
*/
function get_next_review_default($risk_id){
    $id = intval($risk_id) + 1000;
    $risk = get_risk_by_id($id);
    if($risk)
    {
        if(get_setting('next_review_date_uses') == "ResidualRisk")
        {
            $next_review = next_review_by_score($risk[0]['residual_risk']);
        }
        // If next_review_date_uses setting is Inherent Risk.
        else
        {
            $next_review = next_review_by_score($risk[0]['calculated_risk']);
        }

    }
    else
    {
        $next_review = "0000-00-00";
    }

    return $next_review;
}

/**********************************
 * FUNCTION: GET NEXT REVIEW DATE *
 **********************************/
function next_review($risk_level, $id, $next_review, $html = true, $review_levels = array(), $submission_date = false, $return_standard_format = false)
{
    global $lang;
    global $escaper;

    // If the next_review is null
    if ($next_review == null)
    {
        // The risk has not been reviewed yet
        $text = $lang['UNREVIEWED'];
    }
    // If the risk has been reviewed
    else
    {
        // If the review used the default date
        if ($next_review == "0000-00-00")
        {
            // Get the last review for this risk
            if($submission_date === false){
                $last_review = get_last_review($id);
            }else{
                $last_review = $submission_date;
            }

            // Get the review levels
            if(!$review_levels){
                $review_levels = get_review_levels();
            }

            $very_high_display_name = get_risk_level_display_name('Very High');
            $high_display_name      = get_risk_level_display_name('High');
            $medium_display_name    = get_risk_level_display_name('Medium');
            $low_display_name       = get_risk_level_display_name('Low');
            $insignificant_display_name = get_risk_level_display_name('Insignificant');

            // If very high risk
            if ($risk_level === $very_high_display_name)
            {
                // Get days to review very high risks
                $days = $review_levels[0]['value'];
            }
            // If high risk
            else if ($risk_level == $high_display_name)
            {
                // Get days to review high risks
                $days = $review_levels[1]['value'];
            }
            // If medium risk
            else if ($risk_level == $medium_display_name)
            {
                // Get days to review medium risks
                $days = $review_levels[2]['value'];
            }
            // If low risk
            else if ($risk_level == $low_display_name)
            {
                // Get days to review low risks
                $days = $review_levels[3]['value'];
            }
            // If insignificant risk
//            else if ($color == "white")
            else
            {
                // Get days to review insignificant risks
                $days = $review_levels[4]['value'];
            }

            // Next review date
            $last_review = new DateTime($last_review);
            $next_review = $last_review->add(new DateInterval('P'.$days.'D'));
        }
        // A custom next review date was used
        else if($next_review == $lang['PASTDUE']){

        }else{
            $next_review = new DateTime($next_review);
        }

        // If the next review date is after today
        if ($next_review != $lang['PASTDUE'] && (strtotime($next_review->format('Y-m-d')) + 24*3600) > time())
        {
            $date_format = $return_standard_format ? 'Y-m-d' : get_default_date_format();
            
            $text = $next_review->format($date_format);
        }
        else $text = $lang['PASTDUE'];
    }

    // If we want to include the HTML code
    if ($html == true)
    {
        // Convert the database ID to a risk ID
        $risk_id = convert_to_risk_id($id);

        // Add the href tag to make it HTML
        $html = "<a href='../management/view.php?id={$escaper->escapeHtml($risk_id)}&type=2&action=editreview#review' target='_blank' class='open-in-new-tab'>{$escaper->escapeHtml($text)}</a>";

        // Return the HTML code
        return $html;
    }
    // Otherwise just return the text
    else return $escaper->escapeHtml($text);
}

/**
 * Classify a risk's review urgency without producing display markup --
 * mirrors next_review()'s (functions.php:16709) date-resolution branches
 * (null -> unreviewed, "0000-00-00" -> cadence fallback via $review_levels,
 * otherwise a real date checked against the past-due boundary) but returns a
 * machine-readable bucket instead of an HTML string, so callers can filter
 * and sort on it without re-parsing rendered text.
 */
function classify_review_urgency($next_review_raw, $review_level_index, $risk_id, array $review_levels, $submission_date = false, $due_soon_days = 30)
{
    if ($next_review_raw === null) {
        return ['bucket' => 'unreviewed', 'resolved_date' => null];
    }

    if ($next_review_raw === "0000-00-00") {
        $last_review = $submission_date !== false ? $submission_date : get_last_review($risk_id);

        // $review_level_index is pre-resolved by the caller (0=Very High .. 4=Insignificant,
        // matching $review_levels's own order) -- no DB lookup here, keeping this function
        // genuinely pure. See next_review() (functions.php:16709) for the display-rendering
        // twin of this branch, which resolves the index via get_risk_level_display_name()
        // because it already has a display string on hand; this function never does.
        $days = $review_levels[$review_level_index]['value'];

        $resolved_date = date('Y-m-d', strtotime($last_review . " +{$days} days"));
    } else {
        $resolved_date = (new \DateTime($next_review_raw))->format('Y-m-d');
    }

    $days_until = (strtotime($resolved_date) - strtotime(date('Y-m-d'))) / 86400;

    if ((strtotime($resolved_date) + 24 * 3600) <= time()) {
        $bucket = 'past_due';
    } elseif ($days_until <= $due_soon_days) {
        $bucket = 'due_soon';
    } else {
        $bucket = 'on_track';
    }

    return ['bucket' => $bucket, 'resolved_date' => $resolved_date];
}

/**
 * Earlier of a mitigation's planned date and a review's resolved due date,
 * skipping whichever is null -- drives the merged queue's single "Due"
 * sort/display column when a row needs both actions.
 */
function compute_next_action_due_date($mitigation_date, $review_resolved_date)
{
    if ($mitigation_date === null) {
        return $review_resolved_date;
    }
    if ($review_resolved_date === null) {
        return $mitigation_date;
    }
    return strtotime($mitigation_date) <= strtotime($review_resolved_date) ? $mitigation_date : $review_resolved_date;
}

/**
 * "Show my action items" predicate: not ownership, permission relevance --
 * can the viewer actually act on at least one of this row's active needs?
 * See docs/superpowers/specs/2026-09-09-review-risk-page-design.md,
 * "Correction: from ownership filter to permission-relevance filter."
 */
function user_can_act_on_risk_need($needs_mitigation, $needs_review, $risk_level_name, $has_plan_mitigations, array $review_permissions_by_level)
{
    if ($needs_mitigation && $has_plan_mitigations) {
        return true;
    }
    if ($needs_review && !empty($review_permissions_by_level[$risk_level_name])) {
        return true;
    }
    return false;
}

/**********************************
 * FUNCTION: NEXT REVIEW BY SCORE *
 **********************************/
function next_review_by_score($calculated_risk)
{
    // Get risk level name by score
    $level = get_risk_level_name($calculated_risk);

        // Get the review levels
    $review_levels = get_review_levels();

    $very_high_display_name = get_risk_level_display_name('Very High');
    $high_display_name      = get_risk_level_display_name('High');
    $medium_display_name    = get_risk_level_display_name('Medium');
    $low_display_name       = get_risk_level_display_name('Low');
    $insignificant_display_name = get_risk_level_display_name('Insignificant');

    // If very high risk
    if ($level == $very_high_display_name)
    {
        // Get days to review high risks
        $days = $review_levels[0]['value'];
    }
    // If high risk
    else if ($level == $high_display_name)
    {
        // Get days to review high risks
        $days = $review_levels[1]['value'];
    }
    // If medium risk
    else if ($level == $medium_display_name)
    {
        // Get days to review medium risks
        $days = $review_levels[2]['value'];
    }
    // If low risk
    else if ($level == $low_display_name)
    {
        // Get days to review low risks
        $days = $review_levels[3]['value'];
    }
    // If insignificant risk
//    else if ($color == "white")
    else
    {
        // Get days to review insignificant risks
        $days = $review_levels[4]['value'];
    }

    // Next review date
    $today = new DateTime('NOW');
    $next_review = $today->add(new DateInterval('P'.$days.'D'));
    $default_date_format = get_default_date_format();
    $next_review = $next_review->format($default_date_format);

    // Return the next review date
    return $next_review;
}

/*******************************************
 * FUNCTION: RESOLVE CLOSE REASON LABEL     *
 * Pulled out of close_risk() so the        *
 * unselected-vs-"Rejected" (value 0)       *
 * ambiguity is independently testable      *
 * without going through the DB-touching,   *
 * test-mode-skipped workflow trigger.      *
 *******************************************/
function resolve_close_reason_label($close_reason)
{
    // $close_reason can be '' when the closer left the dropdown unselected.
    // Casting straight to (int) collapsed that case onto value 0 ("Rejected"),
    // making an unselected reason indistinguishable from an explicit Rejected
    // wherever the label is displayed (e.g. the risk.closed workflow trigger's
    // notification email). Resolve the code to its label like the rest of the
    // codebase does (see get_name_by_value() call in process_notification_template_risk()
    // in extras/notification/index.php) instead of passing the raw int.
    if ($close_reason === '' || $close_reason === null) {
        return '-';
    }

    return get_name_by_value('close_reason', (int)$close_reason, '-');
}

/************************
 * FUNCTION: CLOSE RISK *
 ************************/
function close_risk($risk_id, $user_id, $status, $close_reason, $note, $closure_date = false)
{
    global $escaper;
    // Subtract 1000 from risk_id
    $id = (int)$risk_id - 1000;

    // Open the database connection
    $db = db_open();

    // Get current datetime for closure_date
    if($closure_date == false) $closure_date = date("Y-m-d H:i:s");

    $stmt = $db->prepare("INSERT INTO closures (`risk_id`, `user_id`, `close_reason`, `note`, `closure_date`) VALUES (:risk_id, :user_id, :close_reason, :note, :closure_date)");
    $stmt->bindParam(":closure_date", $closure_date, PDO::PARAM_STR, 20);

    $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":close_reason", $close_reason, PDO::PARAM_INT);
    $stmt->bindParam(":note", $note, PDO::PARAM_STR);

    $stmt->execute();

    // Get the new mitigation id
    $close_id = $db->lastInsertId();

    // Update the risk
    $stmt = $db->prepare("UPDATE risks SET status=:status,last_update=:date,close_id=:close_id WHERE id = :id");

    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->bindParam(":status", $status, PDO::PARAM_STR, 50);
    $stmt->bindParam(":date", $closure_date, PDO::PARAM_STR);
    $stmt->bindParam(":close_id", $close_id, PDO::PARAM_INT);
    $stmt->execute();

    // Update the risk scoring history to set the risk score to zero since it is closed
    $stmt = $db->prepare("INSERT INTO risk_scoring_history (`risk_id`, `calculated_risk`, `last_update`) VALUES (:id, 0, :date);");
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->bindParam(":date", $closure_date, PDO::PARAM_STR);
    $stmt->execute();

    // Send the notification (no-op if notification extra is disabled)
    call_extra_function(
        'notification_extra',
        __DIR__ . '/../extras/notification/index.php',
        'notify_risk_close',
        [$id]
    );

    // Audit log. The reason/note captured on close are otherwise only
    // visible by adding the Close Reason/Close-Out Information columns to a
    // Dynamic Risk Report (reports/dynamic_risk_report.php) -- surfacing
    // them here too puts them somewhere a reviewer would actually look
    // first. resolve_close_reason_label() is the same lookup the
    // risk.closed workflow trigger below already uses for its own
    // notification text, computed once and reused for both.
    //
    // The reason/note go on a SECOND line, after a "\n" -- classify_risk_
    // audit_activity() anchors its close-message regex to the start of the
    // string only (no trailing anchor), so this doesn't affect activity-pill
    // classification, and get_risk_audit_log_api() (includes/api.php)
    // already splits everything after the first "\n" out as a `detail` hint
    // line under the pill -- the exact mechanism update_risk_details()'s own
    // field-diff messages use, reused here rather than inventing a second
    // convention.
    $close_reason_label = resolve_close_reason_label($close_reason);
    $message = "Risk ID \"" . $risk_id . "\" was marked as closed by username \"" . $escaper->escapeHtml($_SESSION['user'] ?? 'unknown') . "\".";
    $message .= "\nReason: \"" . $escaper->escapeHtml($close_reason_label) . "\"";
    if (trim((string)$note) !== '') {
        $message .= ", Close-out information: \"" . $escaper->escapeHtml($note) . "\"";
    }
    write_log($risk_id, (int)($_SESSION['uid'] ?? 0), $message);

    // Capture risk owner for workflow context before closing the connection
    $stmt = $db->prepare("SELECT `owner` FROM `risks` WHERE `id` = :id LIMIT 1");
    $stmt->bindParam(':id', $id, PDO::PARAM_INT);
    $stmt->execute();
    $_wf_owner = (int)(($stmt->fetch(PDO::FETCH_ASSOC))['owner'] ?? 0);

        // Close the database connection
        db_close($db);

    // Fire the risk.closed workflow trigger
    trigger_workflow_event('risk.closed', [
        'trigger_type'   => 'risk.closed',
        'risk_id'        => $id,
        'display_risk_id'=> $id + 1000,
        'owner'          => $_wf_owner,
        'closure_reason' => $close_reason_label,
    ]);

        return true;
}

/**************************
 * FUNCTION: GET CLOSE ID *
 **************************/
function get_close_id($risk_id)
{
        // Open the database connection
        $db = db_open();

        // Query the database
        // Get the close id
        $stmt = $db->prepare("SELECT id FROM closures WHERE risk_id=:risk_id ORDER BY closure_date DESC LIMIT 1");
        $stmt->bindParam(":risk_id", $risk_id, PDO::PARAM_INT);
        $stmt->execute();

        // Store the list in the array
        $array = $stmt->fetchAll();

        // Close the database connection
        db_close($db);

        return $array[0]['id'];
}

/*************************
 * FUNCTION: REOPEN RISK *
 *************************/
function reopen_risk($risk_id)
{
    global $escaper;
    // Subtract 1000 from id
    $id = (int)$risk_id - 1000;

    // Get current datetime for last_update
    $current_datetime = date('Y-m-d H:i:s');

    // Open the database connection
    $db = db_open();

    // Update the risk
    $stmt = $db->prepare("UPDATE risks SET status=\"Reopened\",last_update=:date,close_id=\"0\" WHERE id = :id");
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->bindParam(":date", $current_datetime, PDO::PARAM_STR);
    $stmt->execute();

    // Update the risk scoring history
    $stmt = $db->prepare("INSERT INTO risk_scoring_history (`risk_id`, `calculated_risk`, `last_update`) SELECT r.id, rs.calculated_risk, r.last_update FROM risks r LEFT JOIN risk_scoring rs ON r.id = rs.id WHERE r.id = :id;");
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->execute();

    // Audit log
    $message = "Risk ID \"" . $risk_id . "\" was reopened by username \"" . $escaper->escapeHtml($_SESSION['user'] ?? 'unknown') . "\".";
    write_log($risk_id, (int)($_SESSION['uid'] ?? 0), $message);

    // Capture risk owner for workflow context before closing the connection
    $stmt = $db->prepare("SELECT `owner` FROM `risks` WHERE `id` = :id LIMIT 1");
    $stmt->bindParam(':id', $id, PDO::PARAM_INT);
    $stmt->execute();
    $_wf_owner = (int)(($stmt->fetch(PDO::FETCH_ASSOC))['owner'] ?? 0);

    // Close the database connection
    db_close($db);

    // Fire the risk.reopened workflow trigger
    trigger_workflow_event('risk.reopened', [
        'trigger_type'    => 'risk.reopened',
        'risk_id'         => $id,
        'display_risk_id' => $id + 1000,
        'owner'           => $_wf_owner,
    ]);

    return true;
}

/*************************
 * FUNCTION: ADD COMMENT *
 *************************/
function add_comment($risk_id, $user_id, $comment)
{
    global $escaper;
    // Subtract 1000 from id
    $id = (int)$risk_id - 1000;

    $try_encrypt_comments = try_encrypt($comment);

    // Open the database connection
    $db = db_open();

     // Get current datetime for last_update
    $current_datetime = date('Y-m-d H:i:s');

    // Add the closure
    $stmt = $db->prepare("INSERT INTO comments (`risk_id`, `user`, `comment`, `date`) VALUES (:risk_id, :user, :comment, :date)");

    $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
    $stmt->bindParam(":user", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":comment", $try_encrypt_comments, PDO::PARAM_STR);
    $stmt->bindParam(":date", $current_datetime, PDO::PARAM_STR);

    $stmt->execute();

    // Update the risk
    $stmt = $db->prepare("UPDATE risks SET last_update=:date WHERE id = :id");

    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->bindParam(":date", $current_datetime, PDO::PARAM_STR);
    $stmt->execute();

    // Send the notification (no-op if notification extra is disabled)
    call_extra_function(
        'notification_extra',
        __DIR__ . '/../extras/notification/index.php',
        'notify_risk_comment',
        [$id, $comment]
    );

    // Audit log
    $message = "A comment was added to risk ID \"" . $risk_id . "\" by username \"" . $escaper->escapeHtml($_SESSION['user'] ?? 'unknown') . "\".";
    write_log($risk_id, (int)($_SESSION['uid'] ?? 0), $message);

        // Close the database connection
        db_close($db);

        return true;
}

/**************************
 * FUNCTION: GET COMMENTS *
 **************************/
function get_comments($id, $html = true) {

    global $escaper;

    // Subtract 1000 from id
    $id = (int)$id - 1000;

    // Open the database connection
    $db = db_open();

    // Get the comments
    $stmt = $db->prepare("SELECT a.date, a.comment, b.name FROM comments a LEFT JOIN user b ON a.user = b.value WHERE risk_id=:risk_id ORDER BY date DESC");

    $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);

    $stmt->execute();

    // Store the list in the array
    $comments = $stmt->fetchAll();

    // Close the database connection
    db_close($db);

    if($html == true) {
        foreach ($comments as $comment) {
            $text = try_decrypt($comment['comment']);
            $date = date(get_default_datetime_format("g:i A T"), strtotime($comment['date']));
            $user = $comment['name'];
            if($text != null) {
                echo "
                    <p class='comment-block'>
                        <b>" . $escaper->escapeHtml($date) . " by " . $escaper->escapeHtml($user) . "</b><br />" .
                        $escaper->escapeHtml($text) . "
                    </p>
                ";
            }
        }
        return true;
    } else {
        return $comments;
    }
}

/*****************************
 * FUNCTION: GET AUDIT TRAIL *
 *****************************/
function get_audit_trail($id = NULL, $days = 7, $log_type=NULL)
{
    $logs = [];

    // If the ID is greater than 1000 or NULL
    if ($id > 1000 || $id === NULL)
    {
        // Open the database connection
        $db = db_open();

        $stmt = null;

        $query = "
            SELECT t1.timestamp, t1.message, t1.log_type, t1.user_id, t2.name user_fullname 
            FROM audit_log t1
                LEFT JOIN user t2 ON t1.user_id=t2.value
        ";

        // If the ID is greater than 1000
        if ($id > 1000)
        {
            // Subtract 1000 from id
            $id = (int)$id - 1000;

            // If log_type is NULL, shows all logs
            if($log_type === NULL){
                $query .= " WHERE risk_id=:risk_id AND (`timestamp` > CURDATE()-INTERVAL :days DAY) ORDER BY timestamp DESC;";
                // Get the full audit trail
                $stmt = $db->prepare($query);
            }
            else
            {
                if(is_array($log_type))
                {
                    $log_type_array = $log_type;
                }
                else
                {
                    $log_type_array = array($log_type);
                }

                $query .= " WHERE risk_id=:risk_id AND (`timestamp` > CURDATE()-INTERVAL :days DAY) AND FIND_IN_SET(log_type, :log_type)  ORDER BY timestamp DESC;";
                $stmt = $db->prepare($query);
                $log_type_str = implode(",", $log_type_array);
                $stmt->bindParam(":log_type", $log_type_str, PDO::PARAM_STR);
            }

            $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
            $stmt->bindParam(":days", $days, PDO::PARAM_INT);
        }
        // If the ID is NULL
        else if ($id === NULL)
        {
            // If log_type is NULL, shows all logs
            if($log_type === NULL){
                $query .= " WHERE (`timestamp` > CURDATE()-INTERVAL :days DAY) ORDER BY timestamp DESC; ";
                // Get the full audit trail
                $stmt = $db->prepare($query);
                $stmt->bindParam(":days", $days, PDO::PARAM_INT);
            }
            else
            {
                if(is_array($log_type))
                {
                    $log_type_array = $log_type;
                }
                else
                {
                    $log_type_array = array($log_type);
                }
                $query .= " WHERE (`timestamp` > CURDATE()-INTERVAL :days DAY) AND FIND_IN_SET(log_type, :log_type) ORDER BY timestamp DESC; ";

                $stmt = $db->prepare($query);
                $log_type_str = implode(",", $log_type_array);
                $stmt->bindParam(":log_type", $log_type_str, PDO::PARAM_STR);
                $stmt->bindParam(":days", $days, PDO::PARAM_INT);
            }
        }

        $stmt->execute();
       // Store the list in the array
        $logs = $stmt->fetchAll(PDO::FETCH_ASSOC);

        // Close the database connection
        db_close($db);
        
        foreach ($logs as &$log)
        {
            $log['message'] = try_decrypt($log['message']);
        }

        // Return true
        return $logs;
    }
    // Otherwise this is not a valid ID
    else
    {
        // Return false
        return [];
    }

}

/**
 * Classifies a decrypted risk audit_log message into a short activity key
 * for get_risk_audit_log_api()'s Activity column/pill -- same purpose and
 * shape as classify_exception_audit_activity()/classify_document_audit_
 * activity() (includes/governance.php). One pattern per message template a
 * risk-lifecycle write_log() call site actually writes (add_risk(),
 * update_risk_subject(), close_risk(), reopen_risk(), edit_mitigation_
 * details()/save_mitigation(), delete_mitigation(), the management review
 * submit/delete pair, add_comment(), the Accept/Reject Mitigation bulk
 * actions, and the supporting-documentation upload/delete handlers -- all
 * in this file). 'other' is the safe fallback for every message shape this
 * doesn't recognize (Jira sync messages, scoring-method-change messages,
 * risk-formula-change messages, etc.) -- the same acceptable-imprecision
 * level the exception/document classifiers already ship with.
 *
 * @param string $message decrypted, not-yet-escaped audit_log.message
 * @return string one of: create/update/close/reopen/review/delete/comment/
 *                upload/mitigation_accept/mitigation_reject/other
 */
function classify_risk_audit_activity($message) {
    if (preg_match('/^A new risk ID "/', $message)) {
        return 'create';
    }
    if (preg_match('/^Risk ID ".*" was DELETED by/', $message)) {
        return 'delete';
    }
    if (preg_match('/^A management review was deleted for risk ID "/', $message)) {
        return 'delete';
    }
    if (preg_match('/^A mitigation was deleted for risk ID "/', $message)) {
        return 'delete';
    }
    if (preg_match('/^File ".*" was deleted by/', $message)) {
        return 'delete';
    }
    if (preg_match('/^Risk ID ".*" was marked as closed by/', $message)) {
        return 'close';
    }
    if (preg_match('/^Risk ID ".*" was reopened by/', $message)) {
        return 'reopen';
    }
    if (preg_match('/^A management review was submitted for risk ID "/', $message)) {
        return 'review';
    }
    if (preg_match('/^Mitigation for risk ID .* accepted by/', $message)) {
        return 'mitigation_accept';
    }
    if (preg_match('/^Mitigation for risk ID .* rejected by/', $message)) {
        return 'mitigation_reject';
    }
    if (preg_match('/^A comment was added to risk ID "/', $message)) {
        return 'comment';
    }
    if (preg_match('/^File ".*" was uploaded by/', $message)) {
        return 'upload';
    }
    if (preg_match('/^Risk subject was updated for risk ID "/', $message)) {
        return 'update';
    }
    if (preg_match('/^Risk details were updated for risk ID "/', $message)) {
        return 'update';
    }
    if (preg_match('/^Risk mitigation details were updated for risk ID "/', $message)) {
        return 'update';
    }
    if (preg_match('/^A mitigation was submitted for risk ID "/', $message)) {
        return 'update';
    }
    if (preg_match('/^A risk status for subject ".*" was changed by/', $message)) {
        return 'update';
    }
    if (preg_match('/^Scoring method has been updated for risk ID "/', $message)) {
        return 'update';
    }
    if (preg_match('/^Risk score has been updated for risk ID "/', $message)) {
        return 'update';
    }
    return 'other';
}

/*******************************
 * FUNCTION: UPDATE MITIGATION *
 *******************************/
/**
 * Update a risk's mitigation.
 *
 * @param int   $risk_id Display risk id (internal id + 1000).
 * @param array $post    The submitted field values.
 * @param bool  $is_api  When true, apply PARTIAL-update semantics: only the
 *                       columns and junctions actually present in $post are
 *                       written, and everything the caller did not name keeps
 *                       its stored value.
 *
 *                       This exists because every field here defaults to a zero
 *                       value (0 / "" / []) and, before the guard below, all of
 *                       them were bound into the UPDATE unconditionally. A
 *                       PATCH naming one field therefore reset the planning
 *                       strategy, effort, cost and owner to "none" and blanked
 *                       all three free-text fields -- full-replace semantics
 *                       behind a verb that means partial update.
 *
 *                       Callers that submit a complete payload -- the risk
 *                       page's mitigation form (saveMitigationForm() passes
 *                       $_POST) and the import-export Extra (which builds every
 *                       key explicitly) -- leave this false and are entirely
 *                       unaffected: for them every key is present either way.
 */
function update_mitigation($risk_id, $post, $is_api = false)
{
    global $escaper;
    // Subtract 1000 from risk_id
    $id = (int)$risk_id - 1000;

    // Save custom fields (no-op if customization extra is disabled)
    call_extra_function(
        'customization_extra',
        __DIR__ . '/../extras/customization/index.php',
        'save_risk_custom_field_values',
        [$risk_id]
    );

    $planning_strategy  = isset($post['planning_strategy']) ? (int)$post['planning_strategy'] : 0;
    $mitigation_effort  = isset($post['mitigation_effort']) ? (int)$post['mitigation_effort'] : 0;
    $mitigation_cost    = isset($post['mitigation_cost']) ?(int)$post['mitigation_cost'] : 0;
    $mitigation_owner   = isset($post['mitigation_owner']) ? (int)$post['mitigation_owner'] : 0;
    $mitigation_team   = isset($post['mitigation_team']) ? $post['mitigation_team'] : [];

    // Sanitizing input that comes from the WYSIWYG editor or outside sources
    $current_solution           = isset($post['current_solution']) ? $post['current_solution'] : "";
    $current_solution  = try_encrypt(purify_html($current_solution));

    $security_requirements      = isset($post['security_requirements']) ? $post['security_requirements'] : "";
    $security_requirements  = try_encrypt(purify_html($security_requirements));

    $security_recommendations   = isset($post['security_recommendations']) ? $post['security_recommendations'] : "";
    $security_recommendations   = try_encrypt(purify_html($security_recommendations));

    $planning_date      = isset($post['planning_date']) ? $post['planning_date'] : "";
    $mitigation_percent = (isset($post['mitigation_percent']) && $post['mitigation_percent'] >= 0 && $post['mitigation_percent'] <= 100) ? $post['mitigation_percent'] : 0;
    $mitigation_controls = empty($post['mitigation_controls']) ? [] : $post['mitigation_controls'];
//    $mitigation_controls = is_array($mitigation_controls) ? implode(",", $mitigation_controls) : $mitigation_controls;

    // if planning_date is empty, the current date should be planning_date
    if (!$planning_date) {
        $planning_date = date("Y-m-d");
    }

    if (!validate_date($planning_date, get_default_date_format()))
    {
        $planning_date = "0000-00-00";
    }
    // Otherwise, set the proper format for submitting to the database
    else
    {
        $planning_date = get_standard_date_from_default_format($planning_date);
    }

    // To be able to import submission date
    $submission_date = isset($post['mitigation_date']) && validate_date($post['mitigation_date'], get_default_datetime_format()) ? get_standard_date_from_default_format($post['mitigation_date'], true) : false;

    // get current mitigation
    $mitigation = get_mitigation_by_id($risk_id);
    $data = array(
        "planning_strategy" => $planning_strategy,
        "mitigation_effort" => $mitigation_effort,
        "mitigation_cost" => $mitigation_cost,
        "mitigation_owner" => $mitigation_owner,
        "current_solution" => $current_solution,
        "security_requirements" => $security_requirements,
        "security_recommendations" => $security_recommendations,
        "planning_date" => $planning_date,
        "mitigation_percent" => $mitigation_percent
    );

    // PARTIAL-update filter (API callers only -- see the docblock). Keyed off
    // presence, not emptiness, so an explicitly-submitted '' still clears the
    // field while an absent one is left alone.
    if ($is_api) {
        $data = array_intersect_key($data, $post);
    }

    $updated_fields = [];
    foreach($data as $key => $value){
        if($key=="current_solution" || $key=="security_requirements" || $key=="security_recommendations") {
            if(try_decrypt($value) != try_decrypt($mitigation[0][$key])) {
                $updated_fields[$key]["original"] = try_decrypt($mitigation[0][$key]);
                $updated_fields[$key]["updated"] = try_decrypt($value);
            }
        } else if($value != $mitigation[0][$key]) {
            switch($key)
            {
                default:
                    $original_value = $mitigation[0][$key];
                    $updated_value = $value;
                break;
                case "planning_strategy":
                    $original_value = get_table_value_by_id("planning_strategy", $mitigation[0][$key]);
                    $updated_value = get_table_value_by_id("planning_strategy", $value);
                break;
                case "mitigation_effort":
                    $original_value = get_table_value_by_id("mitigation_effort", $mitigation[0][$key]);
                    $updated_value = get_table_value_by_id("mitigation_effort", $value);
                break;
                case "mitigation_cost":
                    $original_value = get_asset_value_by_id($mitigation[0][$key]);
                    $updated_value = get_asset_value_by_id($value);
                break;
                case "mitigation_owner":
                    $owner_original = get_user_by_id($mitigation[0][$key]);
                    $owner_updated = get_user_by_id($value);
                    // @phan-suppress-next-line PhanTypeInvalidDimOffset -- get_user_by_id() returns the row including 'name' when truthy
                    $original_value = $owner_original ? $owner_original["name"] : '';
                    // @phan-suppress-next-line PhanTypeInvalidDimOffset
                    $updated_value = $owner_updated ? $owner_updated["name"] : '';
                break;
            }
            $updated_fields[$key]["original"] = $original_value;
            $updated_fields[$key]["updated"] = $updated_value;
        }
    }

    // Open the database connection
    $db = db_open();

    // Get current datetime for last_update
    $current_datetime = date("Y-m-d H:i:s");

    // Update the risk status to "Mitigation Planned"
    $stmt = $db->prepare("
        UPDATE 
            risks 
        SET 
            status='Mitigation Planned' 
        WHERE 
            id = :id;
    ");
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->execute();

    // Build the SET clause from $data, which the partial-update filter above has
    // already reduced to the columns this caller actually named. The column
    // names are our own literals from the $data keys, never caller input, and
    // every value is still bound. `last_update` is always written, which also
    // guarantees the SET clause can never be empty -- an all-filtered-out $data
    // would otherwise produce `UPDATE mitigations SET WHERE risk_id=...` and a
    // SQL syntax error.
    $column_types = array(
        "planning_strategy"        => PDO::PARAM_INT,
        "mitigation_effort"        => PDO::PARAM_INT,
        "mitigation_cost"          => PDO::PARAM_INT,
        "mitigation_owner"         => PDO::PARAM_INT,
        "current_solution"         => PDO::PARAM_STR,
        "security_requirements"    => PDO::PARAM_STR,
        "security_recommendations" => PDO::PARAM_STR,
        "planning_date"            => PDO::PARAM_STR,
        "mitigation_percent"       => PDO::PARAM_INT,
    );

    // Iterate $column_types, not $data: the interpolated column name is then
    // provably one of the nine literals above rather than a key carried in from
    // a caller-supplied array, and the clause order is deterministic.
    $set_clauses = array("last_update=:date");
    if ($submission_date) {
        $set_clauses[] = "submission_date=:submission_date";
    }
    foreach ($column_types as $key => $type) {
        if (array_key_exists($key, $data)) {
            $set_clauses[] = "{$key}=:{$key}";
        }
    }

    // Update the risk
    $stmt = $db->prepare("
        UPDATE
            mitigations
        SET " . implode(", ", $set_clauses) . "
        WHERE
            risk_id=:id;
    ");

    $stmt->bindParam(":id", $id, PDO::PARAM_INT);

    if ($submission_date)
        $stmt->bindParam(":submission_date", $submission_date, PDO::PARAM_STR);

    $stmt->bindParam(":date", $current_datetime, PDO::PARAM_STR);
    foreach ($column_types as $key => $type) {
        if (array_key_exists($key, $data)) {
            $stmt->bindValue(":{$key}", $type === PDO::PARAM_INT ? (int)$data[$key] : $data[$key], $type);
        }
    }
    $stmt->execute();

    $mitigation_id = get_mitigation_id($id);

    // Both of these sync a junction against the incoming id list, so passing
    // the [] default for a field the caller never named would still clear
    // it down to empty. Same partial-update rule as the columns: absent
    // preserves, explicit clears.
    // Save mitigation controls
    if (!$is_api || array_key_exists('mitigation_controls', $post)) {
        save_mitigation_controls($mitigation_id, $mitigation_controls);
    }

    // Save mitigation teams
    if (!$is_api || array_key_exists('mitigation_team', $post)) {
        save_junction_values("mitigation_to_team", "mitigation_id", $mitigation_id, "team_id", $mitigation_team);
    }

        
    // Send the notification (no-op if notification extra is disabled)
    call_extra_function(
        'notification_extra',
        __DIR__ . '/../extras/notification/index.php',
        'notify_mitigation_update',
        [$id]
    );

    // Audit log
    if(count($updated_fields)) {
        $detail_updated = [];
        foreach ($updated_fields as $key => $value) {
            // Rich-text (WYSIWYG) fields emit as plain text; escapeHtml would
            // leave a literal "&lt;p&gt;" (the message is HTML-escaped again on
            // display).
            if (in_array($key, ['current_solution', 'security_requirements', 'security_recommendations'], true)) {
                $original = html_to_plain_text($value["original"]);
                $updated = html_to_plain_text($value["updated"]);
            } else {
                $original = $escaper->escapeHtml($value["original"]);
                $updated = $escaper->escapeHtml($value["updated"]);
            }
            $detail_updated[] = "Field name : `".$key. "` (`".$original."`=>`".$updated."`)";
        }
        $updated_string = implode(", ", $detail_updated);
        $message = "Risk mitigation details were updated for risk ID \"" . $risk_id . "\" by username \"" . $escaper->escapeHtml($_SESSION['user'] ?? 'unknown') . "\".\n".$updated_string;
        write_log($risk_id, (int)($_SESSION['uid'] ?? 0), $message);
    }

    // Close the database connection
    db_close($db);


    /***** upload files ******/
    // If the delete value exists
    if (!empty($post['delete']))
    {
        // For each file selected
        foreach ($post['delete'] as $file)
        {
            // Delete the file
            delete_db_file($file);
        }
    }
    // Same partial-update gate as mitigation_controls/mitigation_team just
    // above -- 'unique_names' is how the LEGACY urlencoded form says "here
    // is the complete kept-file list, delete anything else" (an unchecked
    // multi-select submits no key at all, so absent genuinely means "the
    // user removed them all" there, same reasoning update_risk()'s own
    // identical guard documents). The Cards Mitigation form
    // (saveSupportingDocumentation()/saveMitigationSupportingDocumentation(),
    // includes/api.php) manages files through its OWN dedicated multipart
    // endpoint entirely, so its PATCH body never carries 'unique_names' at
    // all -- unconditionally calling refresh_files_for_risk() with an
    // absent field silently deleted every Mitigation Supporting
    // Documentation file on every single Cards save (confirmed live: two
    // uploaded files vanished from both read and edit view immediately
    // after clicking the main form's Save).
    if (!$is_api || array_key_exists('unique_names', $post)) {
        $unique_names = empty($post['unique_names']) ? "" : $post['unique_names'];
        refresh_files_for_risk($unique_names, $id, 2);
    }

    $error = 1;
    // If a file was submitted
    if (!empty($_FILES))
    {
        // Upload any file that is submitted
        for($i=0; $i<count($_FILES['file']['name']); $i++){
            if($_FILES['file']['error'][$i] || $i==0){
                continue;
            }
            $file = array(
                'name' => $_FILES['file']['name'][$i],
                'type' => $_FILES['file']['type'][$i],
                'tmp_name' => $_FILES['file']['tmp_name'][$i],
                'size' => $_FILES['file']['size'][$i],
                'error' => $_FILES['file']['error'][$i],
            );
        // Upload any file that is submitted
            $error = upload_file($id, $file, 2);
            if($error != 1){
                /**
                * If error, stop uploading files;
                */
                break;
            }
        }

    }
    // Otherwise, success
    else $error = 1;
    /****** end uploading files *******/

    // Add residual risk score
    $residual_risk = get_residual_risk((int)$id + 1000);
    add_residual_risk_scoring_history($id, $residual_risk);

    // A mitigation's controls are part of the risk's AI context. $id is
    // already the raw risks.id here — the caller passes the display id and
    // this function subtracted 1000 from it at the top.
    ai_invalidate_risk_analysis([(int)$id]);

    return $error;
}

/**************************
 * FUNCTION: GET REVIEWS *
 **************************/
function get_reviews($risk_id, $template_group_id="")
{
    global $lang;
    global $escaper;

    // Subtract 1000 from id
    $id = (int)$risk_id - 1000;

    // Open the database connection
    $db = db_open();

    // Get the comments
    $stmt = $db->prepare("SELECT * FROM mgmt_reviews WHERE risk_id=:risk_id ORDER BY submission_date DESC");

    $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);

    $stmt->execute();

    // Store the list in the array
    $reviews = $stmt->fetchAll();

    // Close the database connection
    db_close($db);

    $active_fields = [];

    // If customization extra is enabled
    if(customization_extra()) {

        // Include the extra
        require_once(realpath(__DIR__ . '/../extras/customization/index.php'));

        if(!$template_group_id) {
            $group = get_default_template_group("risk");
            $template_group_id = $group["id"];
        }

        $active_fields = get_active_fields("risk", $template_group_id);
        foreach($active_fields as $key => $field) {
            if($field['name'] == 'NextReviewDate') {
                unset($active_fields[$key]);
            }
        }
    }

    foreach ($reviews as $review) {

        $review_date = date(get_default_datetime_format("g:i A T"), strtotime($review['submission_date']));
        $comment = try_decrypt($review['comments']);

        // If customization extra is enabled
        if(customization_extra()) {

            echo "
                <div class='row card-body my-2 border'>
            ";
            // Left Panel
            echo "
                    <div class='col-6 left-panel'>
            ";
                        display_main_review_fields_by_panel_view('left', $active_fields, $risk_id, $review['id'], $review_date, $review['reviewer'], $review['review'], $review['next_step'], "", $comment);
            echo "
                    </div>
            ";
            // Right Panel
            echo "
                    <div class='col-6 right-panel'>
            ";
                        display_main_review_fields_by_panel_view('right', $active_fields, $risk_id, $review['id'], $review_date, $review['reviewer'], $review['review'], $review['next_step'], "", $comment);
            echo "
                    </div>
                </div>
            ";
            // Bottom panel
            echo "
                <div class='row'>
                    <div class='col-12 bottom-panel'>
            ";
                        display_main_review_fields_by_panel_view('bottom', $active_fields, $risk_id, $review['id'], $review_date, $review['reviewer'], $review['review'], $review['next_step'], "", $comment);
            echo "
                    </div>
                </div>
            ";

        } else {
            
            echo "
                <div class='row card-body my-2 border'>
                    <div class='col-6 left-panel'>
            ";
                        display_review_date_view($review_date);

                        display_reviewer_view($review['reviewer']);

                        display_review_view($review['review']);

                        display_next_step_view($review['next_step'], $risk_id);

                        display_comments_view($comment);
            echo "
                    </div>
                </div>
            ";
            
        }
    }

    return true;
}

/****************************************************************************
 * FUNCTION: PARSE RELEASES FEED                                            *
 * Parse the releases XML body returned by the version-check endpoint into  *
 * the decoded releases array, or null when the body is unusable. Pure      *
 * helper so the degrade-vs-parse decision is unit-testable.                *
 *                                                                          *
 * Guards three failure modes that must NOT fatal the caller:               *
 *  - non-string / empty body. A mid-transfer timeout yields return_code    *
 *    200 with an empty-array body (connectivity.php resets a failed        *
 *    curl_exec to []), so a 200 is not a guarantee of a string body.       *
 *  - body that fails to parse as XML (partial / garbled response).         *
 *  - parsed structure that isn't a non-empty array.                        *
 ****************************************************************************/
function parse_releases_feed($version_page): ?array {
    if (!is_string($version_page) || $version_page === '') {
        return null;
    }
    $releases = @simplexml_load_string($version_page);
    if ($releases === false) {
        return null;
    }
    $releases_array = json_decode(json_encode($releases), true);
    if (!is_array($releases_array) || empty($releases_array)) {
        return null;
    }
    return $releases_array;
}

/****************************
 * FUNCTION: LATEST VERSION *
 ****************************/
function latest_version($param, $force_refresh = true) {
    $latest_versions = latest_versions($force_refresh);

    if (isset($latest_versions[$param]))
        return $latest_versions[$param];
    else
        return "";
}

/****************************************************************************
 * FUNCTION: LATEST VERSIONS                                                *
 * Gets the list of the latest versions and caches it, so if it's needed    *
 * multiple times in the same request it will still only be loaded once     * 
 ****************************************************************************/
function latest_versions($force_refresh = true) {

    if(!$force_refresh && isset($GLOBALS['latest_versions_cached'])){
        return $GLOBALS['latest_versions_cached'];
    }

    // Check if the version check job has stored fresh data in the database
    if (!$force_refresh)
    {
        $cached_data = get_setting('latest_version_data', false, false);
        if ($cached_data)
        {
            $latest_versions = json_decode($cached_data, true);
            if (!empty($latest_versions))
            {
                $GLOBALS['latest_versions_cached'] = $latest_versions;
                return $GLOBALS['latest_versions_cached'];
            }
        }
    }

    // Url for SimpleRisk current versions
    require_once(realpath(__DIR__ . '/licensing.php'));
    $url = updates_url('/releases.xml');
    write_debug_log("Checking latest versions at " . $url, 'info');

    // Set the HTTP options
    $http_options = [
        'method' => 'GET',
        'header' => [
            "Content-Type: application/x-www-form-urlencoded",
        ],
        'timeout' => 5,
    ];

    // If SSL certificate checks are enabled for external requests
    if (ssl_external_verify_enabled())
    {
        // Verify the SSL host and peer
        $validate_ssl = true;
    }
    else $validate_ssl = false;

    // Get the response
    $response = fetch_url_content("curl", $http_options, $validate_ssl, $url);
    if (!is_array($response))
    {
        write_debug_log("SimpleRisk was unable to connect to " . $url, 'warning');
        $GLOBALS['latest_versions_cached'] = 0;
        return $GLOBALS['latest_versions_cached'];
    }
    $return_code = $response['return_code'];

    // If we were unable to connect to the URL
    if($return_code !== 200)
    {
        write_debug_log("SimpleRisk was unable to connect to " . $url, 'warning');

        // Return 0 for the latest versions
        $GLOBALS['latest_versions_cached'] = 0;
        return $GLOBALS['latest_versions_cached'];
    }
    // We were able to connect to the URL
    else
    {
        write_debug_log("SimpleRisk connected to " . $url, 'info');

        // Parse the body defensively. A 200 status does NOT guarantee a usable
        // string body — a mid-transfer timeout can leave return_code 200 with an
        // empty-array body — so degrade gracefully (matching the non-200 path)
        // instead of fataling in simplexml_load_string() / reset().
        $releases_array = parse_releases_feed($response['response']);
        if ($releases_array === null) {
            write_debug_log("SimpleRisk received an empty or unparseable version response from " . $url, 'warning');
            $GLOBALS['latest_versions_cached'] = 0;
            return $GLOBALS['latest_versions_cached'];
        }
        $latest_release = reset($releases_array);
        $latest_versions['version'] = $latest_release[0]['@attributes']['version'];
        $latest_versions['appversion'] = $latest_release[0]['@attributes']['version'];
        $latest_versions['app'] = $latest_release[0]['@attributes']['version'];
        $latest_versions['dbversion'] = $latest_release[0]['@attributes']['version'];
        $latest_versions['db'] = $latest_release[0]['@attributes']['version'];
        $latest_versions['release_date'] = $latest_release[0]['release_date'];
        $latest_versions['release_number'] = $latest_release[0]['release_number'];
        $latest_versions['next_release'] = $latest_release[0]['next_release'];
        $latest_versions['bundle_md5'] = $latest_release[0]['bundle_md5'];
        $latest_versions['installer_md5'] = $latest_release[0]['installer_md5'];
        $latest_versions['database_schema'] = $latest_release[0]['database_schema'];
        $latest_versions['release_notes'] = $latest_release[0]['release_notes'];
        $latest_versions['release_update'] = $latest_release[0]['release_update'];

        // Get the list of available extras
        $available_extras = available_extras();

        // For each available extra
        foreach($available_extras as $extra)
        {
            // Get the short name of the extra
            $short_name = $extra['short_name'];

            // Get the latest version of the extra
            $extra_versions = $latest_release[0]['extras'][$short_name] ?? null;

            // Skip extras not yet listed in the remote releases feed
            if (empty($extra_versions))
            {
                $latest_versions[$short_name] = null;
                continue;
            }

            // If theres multiple versions of the extra for this release
            if (count($extra_versions) > 1)
            {
                // Set the latest version to null
                $latest_versions[$short_name] = null;

                // For each of the different versions
                foreach ($extra_versions as $key => $value)
                {
                    $version = $latest_release[0]['extras'][$short_name][$key]['@attributes']['version'];

                    // If this version is the most recent
                    if ($version > $latest_versions[$short_name])
                    {
                        // Set it to the latest version
                        $latest_versions[$short_name] = $version;
                    }
                }
            }
            else $latest_versions[$short_name] = $latest_release[0]['extras'][$short_name]['@attributes']['version'];
        }

        // Return the latest versions
        $GLOBALS['latest_versions_cached'] = $latest_versions;
        return $GLOBALS['latest_versions_cached'];
    }
}

/*****************************************************************
 * FUNCTION: EXTRA COMPATIBILITY VERSIONS                        *
 * Which Extra versions the updates service says work with which *
 * application release. Cache-first; see extra_compatibility.xml. *
 *****************************************************************/
/**
 * Returns [extra_short_name => [extra_version => [app version, ...]]], or null
 * when no compatibility data can be obtained at all.
 *
 * Cache-first by design, in three tiers, because the Extra install path calls
 * this on an operator's click and must not pay a network round-trip per click:
 *
 *   1. an in-request memo (including a memoized failure, so one broken fetch
 *      does not retry on every call in the same request),
 *   2. the extra_compatibility_data setting, written by the core_version_check
 *      job every 24h,
 *   3. the network.
 *
 * Tier 2 is what makes "the feed is unreachable" mean *stale* rather than
 * *absent* for the callers that fail closed on absent data. Without it, one
 * outage would refuse every Extra install.
 *
 * @param bool          $force_refresh Skip tiers 1 and 2 and fetch. The version-check
 *                                     job passes true; install-path callers must not.
 * @param callable|null $fetcher       Test seam: fn(string $url): mixed standing in for
 *                                     the HTTP call. Production passes null.
 *
 * @return array<string, array<string, list<string>>>|null
 */
function extra_compatibility_versions($force_refresh = false, ?callable $fetcher = null) {

    require_once(realpath(__DIR__ . '/licensing.php'));

    // Tier 1: in-request memo. array_key_exists, not isset, so a memoized null
    // (failed fetch) is honoured instead of re-fetching on every call.
    if (!$force_refresh && array_key_exists('extra_compatibility_cached', $GLOBALS)) {
        return $GLOBALS['extra_compatibility_cached'];
    }

    // Tier 2: the setting written by the core_version_check job.
    if (!$force_refresh)
    {
        $cached_data = get_setting('extra_compatibility_data', false, false);
        if ($cached_data)
        {
            $decoded = json_decode($cached_data, true);
            if (is_array($decoded) && !empty($decoded))
            {
                $GLOBALS['extra_compatibility_cached'] = $decoded;
                return $GLOBALS['extra_compatibility_cached'];
            }
        }
    }

    // Tier 3: the network.
    //
    // UPDATES_URL is an OVERRIDE, not the normal source: it is defined only by
    // scripts/bundles-test-installation.sh, so a production instance never has
    // it and always falls through to the default. The default is therefore the
    // live production path and must be the service we operate --
    // updates.simplerisk.com -- not raw.githubusercontent.com, which is rate
    // limited and returns 429/503 under load.
    $url = updates_url('/extra_compatibility.xml');

    $http_options = [
        'method' => 'GET',
        'header' => [
            "Content-Type: application/x-www-form-urlencoded",
        ],
        'timeout' => 5,
    ];

    $validate_ssl = ssl_external_verify_enabled();

    // Test seam: without it, any tier-2 miss falls through to a live request, so a
    // test of the tier-2 guard silently depended on reaching updates.simplerisk.com.
    $response = ($fetcher !== null)
        ? $fetcher($url)
        : fetch_url_content("curl", $http_options, $validate_ssl, $url);

    if (!is_array($response) || (int)($response['return_code'] ?? 0) !== 200)
    {
        write_debug_log("SimpleRisk was unable to fetch Extra compatibility data from " . $url, 'warning');
        $GLOBALS['extra_compatibility_cached'] = null;
        return null;
    }

    // parse_extra_compatibility_feed() returns null for every unusable body,
    // including a 200 with an empty or truncated payload.
    $compatibility = parse_extra_compatibility_feed($response['response']);

    if ($compatibility === null)
    {
        write_debug_log("SimpleRisk received an empty or unparseable Extra compatibility response from " . $url, 'warning');
        $GLOBALS['extra_compatibility_cached'] = null;
        return null;
    }

    $GLOBALS['extra_compatibility_cached'] = $compatibility;
    return $GLOBALS['extra_compatibility_cached'];
}

/*********************************************************
 * FUNCTION: RUN VERSION CHECK FETCHES                   *
 * The body of the core_version_check queue job's work.  *
 *********************************************************/
/**
 * Fetch both feeds, persist each one that succeeded, and report whether BOTH
 * landed.
 *
 * Lifted out of the job's queue_check closure so the combining rule is
 * reachable by a test. Inside the closure it could only be exercised by making
 * two real outbound requests, which is why it previously had no behavioural
 * coverage at all — and the rule matters: if the AND collapsed to an OR, a
 * half-fetched cache would report success, the worker would stop retrying, and
 * extra_compatibility_data would stay permanently stale while the post-extract
 * compatibility check fails closed against it.
 *
 * The compatibility fetch is deliberately UNCONDITIONAL — a release-feed failure
 * must not skip it, or a stale compatibility cache never refreshes.
 *
 * Returning false is the whole of this function's failure handling: the
 * run_timestamped_queue_check() wrapper has already stamped the cadence gate, so
 * there is no requeue storm, and the worker owns the backoff retries and the
 * final 'failed' status. Never set a task status here.
 *
 * @param PDO           $db
 * Both feeds are injectable rather than reached through their own functions'
 * seams, and that is deliberate: latest_versions() has no seam at all, and going
 * through extra_compatibility_versions()'s $fetcher would mean asserting this
 * function's AND rule through another function's cache tiers and XML parsing.
 * Injecting here lets the four success/failure combinations be expressed as plain
 * return values, which is the rule actually under test.
 *
 * @param callable|null $versions_provider Test seam: fn(): mixed, defaults to latest_versions(true).
 * @param callable|null $compat_provider   Test seam: fn(): ?array, defaults to extra_compatibility_versions(true).
 *
 * @return bool True only when both feeds were fetched and persisted.
 */
function run_version_check_fetches($db, ?callable $versions_provider = null, ?callable $compat_provider = null) {

    write_debug_log("Version Check: Fetching latest version data...", "info");

    $latest_versions = ($versions_provider !== null)
        ? $versions_provider()
        : latest_versions(true);

    // latest_versions() answers 0 (not null, not []) when it cannot connect.
    $versions_ok = ($latest_versions !== 0 && !empty($latest_versions));

    if ($versions_ok) {
        update_or_insert_setting('latest_version_data', json_encode($latest_versions), db: $db);
        write_debug_log("Version Check: Successfully updated latest version data.", "info");
    } else {
        write_debug_log("Version Check: Failed to fetch latest version data from remote.", "error");
    }

    write_debug_log("Version Check: Fetching Extra compatibility data...", "info");

    $compatibility = ($compat_provider !== null)
        ? $compat_provider()
        : extra_compatibility_versions(true);

    $compatibility_ok = !empty($compatibility);

    if ($compatibility_ok) {
        update_or_insert_setting('extra_compatibility_data', json_encode($compatibility), db: $db);
        write_debug_log("Version Check: Successfully updated Extra compatibility data.", "info");
    } else {
        write_debug_log("Version Check: Failed to fetch Extra compatibility data from remote.", "error");
    }

    return $versions_ok && $compatibility_ok;
}

/*****************************
 * FUNCTION: CURRENT VERSION *
 *****************************/
function current_version($param)
{
    if ($param == "app")
    {
        require_once(realpath(__DIR__ . '/version.php'));

        return APP_VERSION;
    }
    else if ($param == "db")
    {
        // Open the database connection
        $db = db_open();

        $stmt = $db->prepare("SELECT * FROM settings WHERE name=\"db_version\"");

        // Execute the statement
        $stmt->execute();

        // Get the current version
        $array = $stmt->fetchAll();

        // Close the database connection
        db_close($db);

        // Return the current version
        return $array[0]['value'];
    }
}

/****************************************
 * FUNCTION: VERSION UPDATE STATUS      *
 ****************************************/
/**
 * Display decision for a version row: compare an installed version to the
 * latest-known version. Pure — no DB, no network.
 *
 * @return string 'unknown' when $latest is '' (e.g. the latest-version cache
 *                has not been populated yet), 'up_to_date' when the two match,
 *                otherwise 'update_available'.
 */
function version_update_status(string $current, string $latest): string
{
    if ($latest === '') {
        return 'unknown';
    }
    return ($current === $latest) ? 'up_to_date' : 'update_available';
}

/***********************
 * FUNCTION: WRITE LOG *
 ***********************/
function write_log($risk_id, $user_id, $message, $log_type="risk")
{
    // Subtract 1000 from id
    $risk_id = (int)$risk_id - 1000;

    // If the user_id value is not set
    if (!isset($user_id))
    {
        $user_id = 0;
    }
    
    $user_id = (int)$user_id;

    // Open the database connection
    $db = db_open();

    $current_time = date("Y-m-d H:i:s");

    // Get the comments
    $stmt = $db->prepare("INSERT INTO audit_log (timestamp, risk_id, user_id, message, log_type) VALUES (:timestamp, :risk_id, :user_id, :message, :log_type)");

    $stmt->bindParam(":timestamp", $current_time, PDO::PARAM_STR, 20);
    $stmt->bindParam(":risk_id", $risk_id, PDO::PARAM_INT);
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":log_type", $log_type, PDO::PARAM_STR, 100);

    $encrypted_message = try_encrypt($message);
    $stmt->bindParam(":message", $encrypted_message, PDO::PARAM_STR);

    $stmt->execute();

    // Close the database connection
    db_close($db);
}

/*******************************
 * FUNCTION: UPDATE LAST LOGIN *
 *******************************/
function update_last_login($user_id)
{
    // Get current datetime for last_update
    $current_datetime = date('Y-m-d H:i:s');

    // Open the database connection
    $db = db_open();

    // Update the last login
    $stmt = $db->prepare("UPDATE user SET `last_login`=:last_login WHERE `value`=:user_id");
    $stmt->bindParam(":last_login", $current_datetime, PDO::PARAM_STR, 20);
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->execute();

    // Get the total number of users
    $stmt = $db->prepare("SELECT COUNT(value) FROM user");
    $stmt->execute();
    $array = $stmt->fetchAll();
    $users = $array[0][0];

    // Get the total number of risks
    $stmt = $db->prepare("SELECT COUNT(id) FROM risks");
    $stmt->execute();
    $array = $stmt->fetchAll();
    $risks = $array[0][0];

    // Add an entry to the user login history table
    $stmt = $db->prepare("INSERT INTO `user_login_history` (`user_id`, `users`, `risks`) VALUES (:user_id, :users, :risks);");
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":users", $users, PDO::PARAM_INT);
    $stmt->bindParam(":risks", $risks, PDO::PARAM_INT);
    $stmt->execute();

    // Close the database connection
    db_close($db);

    return true;
}

/*******************************
 * FUNCTION: GET ANNOUNCEMENTS *
 *******************************/
function get_announcements()
{
    global $escaper;

    // Configure the proxy server if one exists
    set_proxy_stream_context();

    $announcements = "<ul>\n";

    require_once(realpath(__DIR__ . '/licensing.php'));
    $announcement_file = file(updates_url('/announcements.xml'));

    $regex_pattern = "/<announcement>(.*)<\/announcement>/";

    foreach ($announcement_file as $line)
    {
        if (preg_match($regex_pattern, $line, $matches))
        {
            $announcements .= "<li>" . $escaper->escapeHtml($matches[1]) . "</li>\n";
        }
    }

    $announcements .= "</ul>";

    // Return the announcement
    return $announcements;
}

/*********************************************
 * FUNCTION: RESOLVE USER LANG PREFERENCE     *
 * Decides what to store in $_SESSION['lang'] given a user's raw stored     *
 * `lang` column value. NULL and '' both mean "no preference" -- add_user() *
 * used to hardcode '' for every newly created user, and a historical       *
 * migration (upgrade_from_20221013001(), target version 20230106-001)      *
 * normalized every pre-existing NULL row to '' fleet-wide, so both         *
 * sentinels occur in the wild. Checking only is_null() missed the ''       *
 * case, shipping an empty <html lang=""> and triggering spurious browser  *
 * translate prompts (SD-854).                                             *
 *                                                                          *
 * Shared by set_user_permissions() (authenticate.php) and                 *
 * authenticate_key() (extras/api/index.php) so the two session-bootstrap  *
 * paths cannot drift apart the way they had before this fix -- and so the *
 * decision is unit-testable without a live session or API-key request.    *
 *********************************************/
function resolve_user_lang_preference(?string $stored_lang): string
{
    if (!empty($stored_lang)) {
        return $stored_lang;
    }

    // LANG_DEFAULT is a legacy config.php constant that predates the
    // default_language setting; only authenticate_key()'s call site ever
    // checked it before this fix unified the two. Nothing in this repo
    // defines it today, but an old customer config.php might still, so the
    // check is preserved rather than dropped.
    if (defined('LANG_DEFAULT')) {
        return LANG_DEFAULT;
    }

    $default_language = get_setting("default_language");
    return $default_language ?: "en";
}

/***************************
 * FUNCTION: LANGUAGE FILE *
 ***************************/
function language_file($force_default=false)
{
    // Define allowed languages (WHITELIST)
    $allowed_languages = ['af', 'ar', 'bg', 'bp', 'ca', 'cs', 'cu', 'da', 'de', 'el', 'en', 'es', 'fi', 'fr', 'he', 'hi', 'hu', 'it', 'ja', 'ko', 'mn', 'nl', 'no', 'pl', 'pt', 'ro', 'ru', 'si', 'sk', 'sr', 'sv', 'tr', 'th', 'uk', 'vi', 'zh-CN', 'zh-TW'];

    // If the session hasn't been defined yet
    if (!isset($_SESSION) && PHP_SAPI !== 'cli' && !$force_default)
    {
        return realpath(__DIR__ . '/../languages/empty.php');
    }
    // If the language is set for the user
    elseif (isset($_SESSION['lang']) && $_SESSION['lang'] != "")
    {
        $safe_lang = validate_language($_SESSION['lang'], $allowed_languages);

        // If validation fails, fall through to default
        if ($safe_lang !== null) {
            $lang_file = realpath(__DIR__ . '/../languages/' . $safe_lang . '/lang.' . $safe_lang . '.php');

            // Verify the file exists and is in the correct directory
            $languages_dir = realpath(__DIR__ . '/../languages');
            if ($lang_file !== false && strpos($lang_file, $languages_dir) === 0 && file_exists($lang_file)) {
                return $lang_file;
            }
        }
        // If validation or file check fails, fall through to default
    }

    // Default language logic
    $default_language = null;

    try
    {
        $db = new PDO("mysql:charset=UTF8;dbname=".DB_DATABASE.";host=".DB_HOSTNAME.";port=".DB_PORT,DB_USERNAME,DB_PASSWORD, array(PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION));
    }
    catch (PDOException $e)
    {
        $default_language = "en";
    }

    if (is_null($default_language))
    {
        $default_language = get_setting("default_language");
        if (!$default_language) $default_language = "en";
    }

    // Validate default language
    $safe_default = validate_language($default_language, $allowed_languages);
    if ($safe_default === null) {
        $safe_default = "en"; // Ultimate fallback
    }

    $lang_file = realpath(__DIR__ . '/../languages/' . $safe_default . '/lang.' . $safe_default . '.php');

    // Final verification
    $languages_dir = realpath(__DIR__ . '/../languages');
    if ($lang_file !== false && strpos($lang_file, $languages_dir) === 0 && file_exists($lang_file)) {
        return $lang_file;
    }

    // Ultimate fallback
    return realpath(__DIR__ . '/../languages/en/lang.en.php');
}

/*******************************
 * FUNCTION: VALIDATE LANGUAGE *
 *******************************/
// Helper function to validate and sanitize language code
function validate_language($lang, $allowed_languages) {
    if (empty($lang)) {
        return null;
    }

    // Remove any path traversal attempts
    $lang = basename($lang);
    $lang = str_replace(['..', '/', '\\', "\0"], '', $lang);

    // Check against whitelist
    if (!in_array($lang, $allowed_languages, true)) {
        return null;
    }

    return $lang;
}

/*****************************************
 * FUNCTION: CUSTOM AUTHENTICATION EXTRA *
 *****************************************/
function custom_authentication_extra() {

    if (isset($GLOBALS['authentication_extra'])) {
        return $GLOBALS['authentication_extra'];
    }

    $setting = get_setting('custom_auth');

    // If the setting is not empty
    if (!empty($setting)) {

        // If the setting is true or "true" or 1
        if ($setting === true || $setting === "true" || $setting === 1 || $setting === "1") {
            // The extra is enabled
            $GLOBALS['authentication_extra'] = true;
        } else {
            $GLOBALS['authentication_extra'] = false;
        }
    } else {
        $GLOBALS['authentication_extra'] = false;
    }

    return $GLOBALS['authentication_extra'];

}

