/*************************
 * FUNCTION: UPLOAD FILE *
 *************************/
function upload_file($risk_id, $file, $view_type = 1) {

    global $escaper, $lang;

    // If a file was submitted and the name isn't blank
    if (isset($file) && $file['name'] != "") {

        // A shared demo instance takes the upload and stores nothing.
        // Attachments live in the `files` table as BLOBs, so an unattended
        // public demo is a ready-made place for a visitor to park arbitrary
        // bytes — it bloats the database and every backup taken of it. Tell
        // the visitor plainly rather than dropping the file in silence.
        //
        // The return value is deliberate. 1 is the success code, and it is the
        // only correct answer here rather than a "silently pretend"
        // convenience: every caller treats a non-1 return as a fatal upload
        // error, and two of them (management/index.php and
        // api/v2/includes/risks.php) respond by deleting the risk the visitor
        // just submitted. Returning an error string would turn "your
        // attachment wasn't saved" into "your risk was thrown away" — a much
        // worse demo than a missing attachment. The alert carries the
        // explanation that the return value can't.
        if (demo_mode()) {

            set_alert(true, "bad", $lang['ActionDisabledOnDemoInstance']);

            return 1;

        }

        $finfo = new finfo(FILEINFO_MIME_TYPE);

        $file_type_name = $finfo->file($file['tmp_name']);
        $file_type_extension_name = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));

        // Check if the file type and extension are allowed
        $file_type_extension_mapping_exists = check_file_type_and_extension_exists($file_type_name, $file_type_extension_name);

        // If the file type and extension combination is appropriate
        if ($file_type_extension_mapping_exists) {

            // Get the maximum upload file size
            $max_upload_size = get_setting("max_upload_size");

            // If the file size is less than 5MB
            if ($file['size'] < $max_upload_size) {

                // If there was no error with the upload
                if ($file['error'] == 0) {

                    // Read the file
                    $content = fopen($file['tmp_name'], 'rb');

                    // Create a unique file name
                    $unique_name = generate_token(30);

                    // Open the database connection
                    $db = db_open();

                    // Store the file in the database
                    $stmt = $db->prepare("INSERT INTO files (risk_id, view_type, name, unique_name, type, size, user, content) VALUES (:risk_id, :view_type, :name, :unique_name, :type, :size, :user, :content)");
                    $stmt->bindParam(":risk_id", $risk_id, PDO::PARAM_INT);
                    $stmt->bindParam(":view_type", $view_type, PDO::PARAM_INT);
                    $stmt->bindParam(":name", $file['name'], PDO::PARAM_STR, 30);
                    $stmt->bindParam(":unique_name", $unique_name, PDO::PARAM_STR, 30);
                    $stmt->bindParam(":type", $file['type'], PDO::PARAM_STR, 30);
                    $stmt->bindParam(":size", $file['size'], PDO::PARAM_INT);
                    $stmt->bindParam(":user", $_SESSION['uid'], PDO::PARAM_INT);
                    $stmt->bindParam(":content", $content, PDO::PARAM_LOB);
                    $stmt->execute();

                    // Close the database connection
                    db_close($db);

                    // Audit log entry for uploading a file
                    $message = "File \"" . $file['name'] . "\" was uploaded by username \"" . $escaper->escapeHtml($_SESSION['user']) . "\".";
                    write_log($risk_id + 1000, $_SESSION['uid'] ?? 0, $message, 'risk');

                    // Return a success
                    return 1;

                // Otherwise
                } else {

                    switch ($file['error']) {
                        case 1:
                            return "The uploaded file exceeds the upload_max_filesize directive in php.ini.";
                            break;
                        case 2:
                            return "The uploaded file exceeds the MAX_FILE_SIZE directive that was specified in the HTML form.";
                            break;
                        case 3:
                            return "The uploaded file was only partially uploaded.";
                            break;
                        case 4:
                            return "No file was uploaded.";
                            break;
                        case 6:
                            return "Missing a temporary folder.";
                            break;
                        case 7:
                            return "Failed to write file to disk.";
                            break;
                        case 8:
                            return "A PHP extension stopped the file upload.";
                            break;
                        default:
                            return "There was an error with the file upload.";
                    }
                }
            } else {

                return "The uploaded file was too big to store in the database.  A SimpleRisk administrator can modify the maximum file upload size under \"File Upload Settings\" under the \"Configure\" menu.  You may also need to modify the 'upload_max_filesize' and 'post_max_size' values in your php.ini file.";

            }
        } else {
            
            return "The file type and extension combination ('{$escaper->escapeHtml($file_type_name)}', '{$escaper->escapeHtml($file_type_extension_name)}') is not supported. A SimpleRisk administrator can add it under 'File Upload Settings' under the 'Configure' menu.";

        }
    } else {
        return 1;
    }
}

/*************************
 * FUNCTION: DELETE FILE *
 *************************/
function delete_db_file($unique_name)
{
    global $escaper;
    // Open the database connection
    $db = db_open();

    // Get the file from the database
    $stmt = $db->prepare("SELECT * FROM files WHERE unique_name=:unique_name");
    $stmt->bindParam(":unique_name", $unique_name, PDO::PARAM_STR, 30);
    $stmt->execute();
    // Store the results in an array
    $file = $stmt->fetch();
    // If the array is empty
    if (empty($file))
    {
        // Do nothing
        return 0;
    }
    else
    {
        // Audit log entry for deleting a file
        $message = "File \"" . $file['name'] . "\" was deleted by username \"" . $escaper->escapeHtml($_SESSION['user']) . "\".";
        write_log($file['risk_id'] + 1000, $_SESSION['uid'] ?? 0, $message, 'risk');
    }

    // Delete the file from the database
    $stmt = $db->prepare("DELETE FROM files WHERE unique_name=:unique_name");
    $stmt->bindParam(":unique_name", $unique_name, PDO::PARAM_STR, 30);
    $stmt->execute();

    // Close the database connection
    db_close($db);

    return 1;
}

/*************************
 * FUNCTION: Delete some files except current unique names *
 *************************/
function refresh_files_for_risk($unique_names, $risk_id, $view_type = 1)
{
    global $escaper;
    if(!$unique_names){
        $unique_names = array();
    }
    // Open the database connection
    $db = db_open();

    $stmt = $db->prepare("SELECT * FROM files WHERE risk_id=:risk_id and view_type=:view_type");
    $stmt->bindParam(":risk_id", $risk_id, PDO::PARAM_INT);
    $stmt->bindParam(":view_type", $view_type, PDO::PARAM_INT);
    $stmt->execute();
    $array = $stmt->fetchAll();
    $deleteIds = array();
    $delete_files = [];
    foreach($array as $row){
        if(!in_array($row['unique_name'], $unique_names)){
            $deleteIds[] = $row['id'];
            $delete_files[] = $row;
        }
    }
    foreach($deleteIds as $key => $deleteId){

        // Audit log entry for deleting a file
        $message = "File \"" . $delete_files[$key]['name'] . "\" was deleted by username \"" . $escaper->escapeHtml($_SESSION['user']) . "\".";
        write_log($delete_files[$key]['risk_id'] + 1000, $_SESSION['uid'] ?? 0, $message, 'risk');

        // Delete the file from the database
        $stmt = $db->prepare("DELETE FROM files WHERE id=:id");
        $stmt->bindParam(":id", $deleteId, PDO::PARAM_INT);
        $stmt->execute();
    }

    // Close the database connection
    db_close($db);

    return 1;
}

/***************************
 * FUNCTION: DOWNLOAD FILE *
 ***************************/
function download_file($unique_name, $file_type = "file")
{
    global $escaper;

    // Open the database connection
    $db = db_open();

    $stmt = null;

    // Get the file from the database
    if($file_type == "file") {
        $stmt = $db->prepare("SELECT * FROM files WHERE BINARY unique_name=:unique_name");
        $stmt->bindParam(":unique_name", $unique_name, PDO::PARAM_STR, 30);
    } else if ($file_type == "validation_file") {
        $stmt = $db->prepare("SELECT * FROM validation_files WHERE id=:unique_name");
        $stmt->bindParam(":unique_name", $unique_name, PDO::PARAM_INT);
    }

    if (!$stmt) {
        write_debug_log("download_file: invalid file_type '{$file_type}' — expected 'file' or 'validation_file'", "warning");
        db_close($db);
        exit;
    }

    $stmt->execute();
    // Store the results in an array
    $array = $stmt->fetch();

    // For validation_files we need the parent risk to authorize against.
    // validation_files links to a risk indirectly:
    //   validation_files.mitigation_id → mitigations.id → mitigations.risk_id
    // get_risk_id_for_mitigation() resolves this (db_open()/db_close() share
    // the process-global connection, so nesting it here is safe) so the
    // team-separation branch below can call extra_grant_access() against the
    // right risk.
    $validation_file_risk_id = null;
    if ($file_type === "validation_file" && !empty($array['mitigation_id'])) {
        $validation_file_risk_id = get_risk_id_for_mitigation($array['mitigation_id']);
    }

    // Close the database connection
    db_close($db);

    // If the array is empty
    if (empty($array))
    {
        // Do nothing
        exit;
    }
    else
    {
        // If team separation is enabled
        if (team_separation_extra())
        {
            //Include the team separation extra
            require_once(realpath(__DIR__ . '/../extras/separation/index.php'));

            // Authorize against the parent risk. The previous expression
            // (file && check) || (validation_file) was an operator-precedence
            // trap — the right side short-circuited the OR to true for every
            // validation_file request, bypassing the team check entirely.
            // Validation files now resolve their risk via the mitigation
            // lookup above and run the same extra_grant_access() the regular
            // file branch does.
            $has_access = false;
            if ($file_type === "file") {
                $has_access = extra_grant_access($_SESSION['uid'], (int)$array['risk_id'] + 1000);
            } elseif ($file_type === "validation_file" && $validation_file_risk_id !== null) {
                $has_access = extra_grant_access($_SESSION['uid'], $validation_file_risk_id + 1000);
            }

            if (!$has_access) {
                redirect_permission_denied('NoPermissionForThisAction', "download_file id={$unique_name} type={$file_type}");
            }
        }

        // Display the file (no team separation, or team separation passed)
        header("Content-length: " . $array['size']);
        header("Content-type: " . $array['type']);
        header("Content-Disposition: attachment; filename=" . $escaper->escapeUrl($array['name']));
        echo $array['content'];
        exit;
    }
}

/**************************************
 * FUNCTION: SUPPORTING DOCUMENTATION *
 * TYPE 1 = Risk File                 *
 * TYPE 2 = Mitigation File           *
 **************************************/
function supporting_documentation($id, $mode = "view", $view_type = 1)
{
    
    global $lang, $escaper;

    // Convert the ID to a database risk id
    $id = $id-1000;

    // Open the database connection
    $db = db_open();

    // Get the file from the database
    $stmt = $db->prepare("SELECT name, unique_name FROM files WHERE risk_id=:id AND view_type=:view_type");
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->bindParam(":view_type", $view_type, PDO::PARAM_INT);
    $stmt->execute();

    // Store the results in an array
    $array = $stmt->fetchAll();

    // Close the database connection
    db_close($db);

    // If the mode is view
    if ($mode == "view") {

        // If the array is empty
        if (empty($array)) {
            echo $escaper->escapeHtml($lang['None']);
        } else {
            // For each entry in the array
            foreach ($array as $file) {
                echo "
                    <div class ='doc-link edit-mode'>
                        <a class='link-success' href='download.php?id=" . $escaper->escapeHtml($file['unique_name']) . "' ><i class='fa fa-download' aria-hidden='true'></i> " . $escaper->escapeHtml($file['name']) . "</a>
                    </div>
                ";
            }
        }

    // If the mode is edit
    } else if ($mode == "edit") {
        // If the array is empty
        if (empty($array)) {

            // echo "<input type=\"file\" name=\"file\" />\n";
            echo "
                <div class='file-uploader'>
                    <script>
                        var max_upload_size = " . $escaper->escapeJs(get_setting('max_upload_size', 0)) . ";
                        var fileTooBigMessage = '" . $escaper->escapeJs($lang['FileIsTooBigToUpload']) . "';
                    </script>
                    <label for='file-upload' class='btn btn-primary active-textfield'>" . $escaper->escapeHtml($lang['ChooseFile']) . "</label> 
                    <span class='file-count-html'><span class='file-count'>0</span> " . $escaper->escapeHtml($lang['FileAdded']) . "</span>
                    <p><font size='2'><strong>Max ". $escaper->escapeHtml(round(get_setting('max_upload_size')/1024/1024)) . " Mb</strong></font></p>
                    <ul class='file-list'>
                    </ul>
                    <input type='file' name='file[]' id='file-upload' class='hidden-file-upload active d-none' />
                </div>
            ";

        } else {

            $documentHtml = "";
            // For each entry in the array
            foreach ($array as $file) {
//                $documentHtml .= "<div class =\"doc-link\">
//                    <a href=\"download.php?id=" . $escaper->escapeHtml($file['unique_name']) . "\" target=\"_blank\" />" . $escaper->escapeHtml($file['name']) . "</a>&nbsp;&nbsp;--&nbsp;" . $escaper->escapeHtml($lang['Delete']) . "?<input class=\"delete-link-check active-textfield\" type=\"checkbox\" name=\"delete[]\" value=\"" . $escaper->escapeHtml($file['unique_name']) . "\" /></div>\n";
                $documentHtml .= "
                    <li>
                        <div class='file-name float-start me-2'>
                            <a href='download.php?id=" . $escaper->escapeHtml($file['unique_name']) . "' target='_blank' />" . $escaper->escapeHtml($file['name']) . "</a>
                        </div>
                        <a href='#' class='remove-file' ><i class='fa fa-times'></i></a>
                        <input type='hidden' name='unique_names[]' value='" . $escaper->escapeHtml($file['unique_name']) . "'>
                    </li>
                ";
            }

            // echo "<input type=\"file\" name=\"file\" />\n";
            if(count($array)>1) {
                $count = '<span class="file-count">' . count($array) . "</span> Files";
            } else {
                $count = '<span class="file-count">' . count($array) . "</span> File";
            }

            echo "
                <div class='file-uploader'>
                <script>
                    var max_upload_size = " . $escaper->escapeJs(get_setting('max_upload_size', 0)) . ";
                    var fileTooBigMessage = '" . $escaper->escapeJs($lang['FileIsTooBigToUpload']) . "'; 
                </script>
                    <label for='file-upload' class='btn btn-primary active-textfield'>Choose File</label> 
                    <span class='file-count-html'>" . $count . " Added</span>
                    <ul class='exist-files m-b-0'>" . 
                        $documentHtml . "
                    </ul>
                    <ul class='file-list'>
                    </ul>
                    <input type='file' name='file[]' id='file-upload' class='hidden-file-upload active d-none' />
                </div>
            ";
        }
    }
}

/*************************************
 * FUNCTION: GET SCORING METHOD NAME *
 *************************************/
function get_scoring_method_name($scoring_method)
{
    switch ($scoring_method)
    {
        case 1:
            return "Classic";
        case 2:
            return "CVSS";
        case 3:
            return "DREAD";
        case 4:
            return "OWASP";
        case 5:
            return "Custom";
        case 6:
            return "Contributing Risk";
    }
}

/***************************
 * FUNCTION: VALIDATE DATE *
 ***************************/
function validate_date($date, $format = 'Y-m-d H:i:s')
{
    $d = DateTime::createFromFormat($format, $date);
    return $d && $d->format($format) == $date;
}

/**************************
 * FUNCTION: DELETE RISKS *
 **************************/
function delete_risks($risks)
{
        // Return true by default
        $return = true;

        // For each risk
        foreach ($risks as $risk)
        {
            $risk_id = (int) $risk;

            // Delete the asset
            $success = delete_risk($risk_id);

            // If it was not a success return false
            if (!$success) $return = false;
        }

        // Return success or failure
        return $return;
}

/*************************
 * FUNCTION: DELETE RISK *
 *************************/
function delete_risk($risk_id)
{
    global $escaper;
    // Open the database connection
    $db = db_open();

    // Remove closures for the risk
    $stmt = $db->prepare("DELETE FROM `closures` WHERE `risk_id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
        $return = $stmt->execute();

    // Remove comments for the risk
    $stmt = $db->prepare("DELETE FROM `comments` WHERE `risk_id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();

    // Remove files for the risk
    $stmt = $db->prepare("DELETE FROM `files` WHERE `risk_id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();

    // Remove management reviews for the risk
    $stmt = $db->prepare("DELETE FROM `mgmt_reviews` WHERE `risk_id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();

    // Remove mitigations for the risk
    $stmt = $db->prepare("DELETE FROM `mitigations` WHERE `risk_id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();

    // Remove the risk scoring for the risk
    $stmt = $db->prepare("DELETE FROM `risk_scoring` WHERE `id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();

    // Remove the risk
    $stmt = $db->prepare("DELETE FROM `risks` WHERE `id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();
        
    // Remove the risk scoring history
    $stmt = $db->prepare("DELETE FROM `risk_scoring_history` WHERE `risk_id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();

    // Remove the residual risk scoring history
    $stmt = $db->prepare("DELETE FROM `residual_risk_scoring_history` WHERE `risk_id`=:id;");
    $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
    $return = $stmt->execute();

    // Remove any AI analysis held for this risk. Core/Extra boundary:
    // ai_recommendations_risk is created by the AI Extra, so the table_exists()
    // guard keeps this a no-op on a Core-only install. Note the id translation
    // — that table keys on the 1000-offset display id, not risks.id. Without
    // this the row outlives the risk and the AI job keeps re-queueing analysis
    // for an id that no longer resolves, spending an AI call each time.
    if (table_exists('ai_recommendations_risk')) {
        $stmt = $db->prepare("DELETE FROM `ai_recommendations_risk` WHERE `risk_id`=:display_id;");
        $stmt->bindValue(":display_id", (int)$risk_id + 1000, PDO::PARAM_INT);
        $stmt->execute();
    }

    cleanup_after_delete("risks");
    cleanup_after_delete("mitigations");

    // Delete custom_risk_data related with risk ID (no-op if customization extra is disabled)
    call_extra_function(
        'customization_extra',
        __DIR__ . '/../extras/customization/index.php',
        'delete_custom_data_by_row_id',
        [$risk_id, "risk"]
    );

    // Close the database connection
    db_close($db);

    // Audit log
    $risk_id = (int)$risk_id + 1000;
    $message = "Risk ID \"" . $risk_id . "\" was DELETED by username \"" . $escaper->escapeHtml($_SESSION['user'] ?? 'unknown') . "\".";
    write_log($risk_id, (int)($_SESSION['uid'] ?? 0), $message);

    // Return success or failure
    return $return;
}

/*******************************
 * FUNCTION: GET RISKS BY TEAM *
 *******************************/
function get_risks_by_team($team)
{
    // Open the database connection
    $db = db_open();

    // Query the database
    $stmt = $db->prepare("SELECT a.id FROM `risks` a INNER JOIN `risk_to_team` rtt ON a.id=rtt.risk_id WHERE rtt.team_id = :team; ");
    $stmt->bindParam(":team", $team, PDO::PARAM_INT);
    $stmt->execute();

    // Store the list in the array
    $array = $stmt->fetch(PDO::FETCH_ASSOC);

    // Close the database connection
    db_close($db);

    return $array;
}

/*******************************
 * FUNCTION: COMPLETED PROJECT *
 *******************************/
function completed_project($project_id)
{
    // Check if the user has access to close risks
    if (isset($_SESSION["close_risks"]) && $_SESSION["close_risks"] == 1)
    {
        // Get the risks for the project
        $risks = get_project_risks($project_id);

        // Scope the bulk close to risks the caller is authorized to see
        // (no-op if team separation extra is disabled). Without this, a
        // project manager who cannot see a hidden cross-team risk could
        // still close it just by marking the shared project Completed.
        $risks = call_extra_function(
            'team_separation_extra',
            __DIR__ . '/../extras/separation/index.php',
            'strip_no_access_risks',
            [$risks],
            $risks
        );

        // For each risk in the project
        foreach ($risks as $risk)
        {
            // If the risks status is not Closed
            if ($risk['status'] != "Closed")
            {
                $id = (int)$risk['id'] + 1000;
                $status = "Closed";
                $close_reason = 1;
                $project = get_name_by_value("projects", $project_id);
                $note = "Risk was closed when the \"" . $project_id . "\" project was marked as Completed.";

                // Close the risk
                close_risk($id, $_SESSION['uid'], $status, $close_reason, $note);
            }
                }

        return 1;
        }
    else return 0;
}

/********************************
 * FUNCTION: INCOMPLETE PROJECT *
 ********************************/
function incomplete_project($project_id)
{
    // Reopening a project's risks is a risk modification. Mirror the
    // close_risks gate that completed_project() applies, so that callers such
    // as update_project_status_api() (gated only on manage_projects) can't
    // bypass the modify_risks check that reopenForm() enforces directly.
    if (!isset($_SESSION["modify_risks"]) || $_SESSION["modify_risks"] != 1)
    {
        return 0;
    }

    // Get the risks for the project
    $risks = get_project_risks($project_id);

    // Scope the bulk reopen to risks the caller is authorized to see
    // (no-op if team separation extra is disabled). Without this, a
    // project manager who cannot see a hidden cross-team risk could still
    // reopen it just by marking the shared project Incomplete.
    $risks = call_extra_function(
        'team_separation_extra',
        __DIR__ . '/../extras/separation/index.php',
        'strip_no_access_risks',
        [$risks],
        $risks
    );

    // For each risk in the project
    foreach ($risks as $risk)
    {
        // If the risk status is Closed
        if ($risk['status'] == "Closed")
        {
            $id = (int)$risk['id'] + 1000;

            // Reopen the risk
            reopen_risk($id);
        }
    }

    return 1;
}

/*****************************************************************************
 * FUNCTION: NORMALIZE LOG VALUE                                             *
 * Coerce any value into a string Monolog will accept (its level methods    *
 * require Stringable|string). null, bools, ints, floats, arrays, and       *
 * objects must all be normalized — passing a raw null or bool to a Monolog  *
 * level method throws a TypeError. Extracted as a pure helper so the        *
 * coercion logic is unit-testable with no DB and no writable log file.      *
 *****************************************************************************/
function normalize_log_value($value): string {
    if (is_string($value)) {
        return $value;
    }
    if (is_array($value) || is_object($value)) {
        return print_r($value, true);
    }
    if (is_bool($value)) {
        return $value ? 'true' : 'false';
    }
    if ($value === null) {
        return 'null';
    }
    return (string)$value;
}

/*****************************************************************************
 * FUNCTION: WRITE DEBUG LOG                                                 *
 * LOG LEVELS                                                                *
 * 1. debug: Detailed diagnostic information for developers.                 *
 * 2. info: General informational messages that highlight normal operations. *
 * 3. notice: Normal but significant events that deserve attention.          *
 * 4. warning: Something unexpected happened, but the app is still running.  *
 * 5. error: Runtime errors that require attention but don’t crash the app.  *
 * 6. critical: Critical conditions that may require immediate action.       *
 *****************************************************************************/
function write_debug_log($value, $level = 'info') {
    static $log_settings = null;
    static $log = null;
    $logFile = '/var/log/simplerisk/simplerisk.log';

    // Load logging settings once
    if ($log_settings === null) {
        $log_settings = [
            'critical' => get_setting('logging_critical'),
            'error'    => get_setting('logging_error'),
            'warning'  => get_setting('logging_warning'),
            'notice'   => get_setting('logging_notice'),
            'info'     => get_setting('logging_info'),
            'debug'    => get_setting('logging_debug'),
        ];
    }

    // Normalize level name (e.g. uppercase or lowercase input)
    $level = strtolower($level);

    // Exit early if this level is not enabled
    if (empty($log_settings[$level])) {
        return;
    }

    // Initialize logger once
    if ($log === null) {
        $log = new Logger('simplerisk');

        try {
            // Ensure the log file exists and is writable
            if (!file_exists($logFile)) {
                @touch($logFile);
                @chmod($logFile, 0664);
            }

            // StreamHandler with append mode and file lock
            $handler = new StreamHandler($logFile, Level::Debug, true, null, true);

            // Custom format: includes SAPI for Apache vs CLI
            $formatter = new LineFormatter(
                "[%datetime%] %level_name% (" . php_sapi_name() . "): %message%\n",
                "Y-m-d H:i:s",
                true,
                true
            );
            $handler->setFormatter($formatter);
            $log->pushHandler($handler);
        } catch (Exception $e) {
            // Failsafe: log to PHP error_log
            error_log("[SimpleRisk:LOGGING FAILSAFE] Could not initialize logger: " . $e->getMessage());
            $log = null;
            return;
        }
    }

    // Coerce the value to a string Monolog will accept (see normalize_log_value).
    // write_debug_log is a logging failsafe and must never throw back into its
    // caller; a null message reached here via the licensing path's
    // fetch_url_content($parameters = null) call and 500'd the app.
    $value = normalize_log_value($value);

    // Write the log safely. Catch \Throwable, not just Exception, so a
    // TypeError from the logging backend can never escalate to a fatal.
    try {
        if ($log && method_exists($log, $level)) {
            $log->$level($value);
        } elseif ($log) {
            $log->info($value);
        } else {
            error_log("[SimpleRisk:LOGGING FAILSAFE] " . $value);
        }
    } catch (\Throwable $e) {
        error_log("[SimpleRisk:LOGGING FAILSAFE] Log write failed: " . $e->getMessage() . " | Original: " . $value);
    }
}

/******************************
 * FUNCTION: ADD REGISTRATION *
 ******************************/
function add_registration($name="", $company="", $title="", $phone="", $email="", $fname="", $lname="", $download_upgrade_extra = true)
{
    global $lang;
    require_once(realpath(__DIR__ . '/licensing.php'));

    // Backward-compat: legacy callers passed a single $name string.
    // If $fname/$lname weren't provided, split $name conservatively.
    if ($fname === '' && $lname === '' && $name !== '') {
        $trimmed_name = trim($name);
        $parts = preg_split('/\s+/', $trimmed_name, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        $fname = $parts ? implode(' ', array_slice($parts, 0, -1)) : '';
        $lname = $parts ? (string)end($parts) : '';
        if (!$fname && $lname) {
            $fname = $lname;
            $lname = '';
        }
    }

    $result = licensing_register_with_retry([
        'fname'        => $fname,
        'lname'        => $lname,
        'company'      => $company,
        'title'        => $title,
        'phone'        => $phone,
        'email'        => $email,
        'mailing_list' => false,
    ]);

    if (!$result['ok']) {
        write_debug_log("add_registration: licensing service registration failed: {$result['error']}", 'warning');
        set_alert(true, "bad", $lang['FailedToRegisterInstance']);
        return 0;
    }

    // Persist the new identity and credentials
    update_or_insert_setting('instance_id',      $result['instance_id']);
    update_or_insert_setting('services_api_key', $result['services_api_key']);
    update_or_insert_setting('registration_name',    $name);
    update_or_insert_setting('registration_company', $company);
    update_or_insert_setting('registration_title',   $title);
    update_or_insert_setting('registration_phone',   $phone);
    update_or_insert_setting('registration_email',   $email);
    update_or_insert_setting('registration_fname',   $fname);
    update_or_insert_setting('registration_lname',   $lname);
    update_or_insert_setting('registration_registered', 1);

    write_debug_log("add_registration: instance_id={$result['instance_id']} registered via Management Extra path", 'notice');

    // Optionally download the Upgrade Extra so the caller can proceed to upgrade
    if ($download_upgrade_extra) {
        $dl = download_extra("upgrade");
        if (!is_string($dl)) {
            $err_message = $dl['reason'] ?? $dl['error'] ?? 'unknown error';
            write_debug_log("add_registration: download_extra failed for 'upgrade': {$err_message}", 'warning');
            return 0;
        }
        return $dl;
    }

    return true;
}

/*********************************
 * FUNCTION: UPDATE REGISTRATION *
 *********************************/
function update_registration($name="", $company="", $title="", $phone="", $email="", $fname="", $lname="")
{
    global $lang;
    require_once(realpath(__DIR__ . '/licensing.php'));

    // Backward-compat: legacy callers passed a single $name string.
    // If $fname/$lname weren't provided, split $name conservatively.
    if ($fname === '' && $lname === '' && $name !== '') {
        $trimmed_name = trim($name);
        $parts = preg_split('/\s+/', $trimmed_name, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        $fname = $parts ? implode(' ', array_slice($parts, 0, -1)) : '';
        $lname = $parts ? (string)end($parts) : '';
        if (!$fname && $lname) {
            $fname = $lname;
            $lname = '';
        }
    }

    $instance_id      = get_setting('instance_id');
    $services_api_key = get_setting('services_api_key');

    if (!$instance_id || !$services_api_key) {
        write_debug_log("update_registration: instance not registered; nothing to update", 'notice');
        return 0;
    }

    $result = licensing_instance_update([
        'instance_id'      => $instance_id,
        'services_api_key' => $services_api_key,
        'fname'            => $fname,
        'lname'            => $lname,
        'company'          => $company,
        'title'            => $title,
        'phone'            => $phone,
        'email'            => $email,
    ]);

    if (!$result['ok']) {
        write_debug_log("update_registration: licensing service update failed: {$result['error']}", 'warning');
        set_alert(true, "bad", $lang['FailedToUpdateInstance']);
        return 0;
    }

    // Persist the updated contact details locally
    update_or_insert_setting('registration_name',    $name);
    update_or_insert_setting('registration_company', $company);
    update_or_insert_setting('registration_title',   $title);
    update_or_insert_setting('registration_phone',   $phone);
    update_or_insert_setting('registration_email',   $email);
    update_or_insert_setting('registration_fname',   $fname);
    update_or_insert_setting('registration_lname',   $lname);

    return true;
}

/********************************
 * FUNCTION: UPDATE RISK STATUS *
 ********************************/
function update_risk_status($risk_id, $status)
{
    global $escaper;
    // Adjust the risk id
    $id = (int)$risk_id - 1000;

    // Fetch the current status BEFORE overwriting it, for the audit log's
    // before/after diff -- same "Field name : `x` (`old`=>`new`)" format
    // update_risk_subject()'s own audit message uses for a Subject-only
    // edit, so a Status change reads with the same level of detail instead
    // of a bare "was changed by X" with no indication of what changed.
    $current_risk = get_risk_by_id($risk_id);
    $original_status = $current_risk ? $current_risk[0]['status'] : '';

    // Open the database connection
    $db = db_open();

    // Update the status
    if( $status == "Closed" && check_risk_by_id($risk_id)){

        if (isset($_SESSION["close_risks"]) && $_SESSION["close_risks"] == 1) {
            // Get current datetime for last_update
            $current_datetime = date('Y-m-d H:i:s');
            $reviewer   = $_SESSION['uid'];
            $review     = 0;
            $next_step  = 0;
            $next_review = "0000-00-00";
            $try_encrypt = try_encrypt("--");

            $stmt = $db->prepare("INSERT INTO mgmt_reviews (`risk_id`, `review`, `reviewer`, `next_step`, `comments`, `next_review`, `submission_date`) VALUES (:risk_id, :review, :reviewer, :next_step, :comments, :next_review, :submission_date)");

            $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
            $stmt->bindParam(":review", $review, PDO::PARAM_INT);
            $stmt->bindParam(":reviewer", $reviewer, PDO::PARAM_INT);
            $stmt->bindParam(":next_step", $next_step, PDO::PARAM_INT);
            $stmt->bindParam(":comments", $try_encrypt, PDO::PARAM_STR);
            $stmt->bindParam(":next_review", $next_review, PDO::PARAM_STR, 10);
            $stmt->bindParam(":submission_date", $current_datetime, PDO::PARAM_STR, 20);

            $stmt->execute();

            // Get the new mitigation id
            $review_id = get_review_id($id);

            // Save custom fields (no-op if customization extra is disabled)
            call_extra_function(
                'customization_extra',
                __DIR__ . '/../extras/customization/index.php',
                'save_risk_custom_field_values',
                [$risk_id, $review_id]
            );

            // Update the risk status and last_update
            $stmt = $db->prepare("UPDATE risks SET status=:status, last_update=:last_update, review_date=:review_date, mgmt_review=:mgmt_review WHERE id = :risk_id");
            $stmt->bindParam(":status", $status, PDO::PARAM_STR, 20);
            $stmt->bindParam(":last_update", $current_datetime, PDO::PARAM_STR, 20);
            $stmt->bindParam(":review_date", $current_datetime, PDO::PARAM_STR, 20);
            $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
            $stmt->bindParam(":mgmt_review", $review_id, PDO::PARAM_INT);

            $stmt->execute();
            $close_reason = 2; // default vaule is 2: System Retired.
            $note = "--";
            // Close the risk
            close_risk($risk_id, $reviewer, $status, $close_reason, $note);
        } else {
            global $lang;

            // Close the database connection
            db_close($db);

            set_alert(true, "bad", $lang['NoPermissionForClosingRisks']);
            return;
        }
    } else if ($status == "New" && check_risk_by_id($risk_id)) { 
        
        // Delete related mitigation_to_controls
        $stmt = $db->prepare("
            DELETE 
                m2c 
            FROM 
                mitigation_to_controls m2c 
            JOIN
                    mitigations m
                ON
                    m2c.mitigation_id = m.id
            WHERE 
                m.risk_id = :risk_id;
        ");
        $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
        $stmt->execute();

        // Delete related mitigation_to_team
        $stmt = $db->prepare("
            DELETE 
                m2t 
            FROM 
                mitigation_to_team m2t 
            JOIN
                    mitigations m
                ON
                    m2t.mitigation_id = m.id
            WHERE 
                m.risk_id = :risk_id;
        ");
        $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
        $stmt->execute();

        // Delete existing mitigation by risk ID
        $stmt = $db->prepare("DELETE FROM mitigations WHERE risk_id = :risk_id");
        $stmt->bindParam(":risk_id", $id, PDO::PARAM_INT);
        $stmt->execute();

        // Update the risk status to New and reset mitigation_id
        $stmt = $db->prepare("UPDATE risks SET `status`=:status, `mitigation_id`=0 WHERE `id`=:id");
        $stmt->bindParam(":status", $status, PDO::PARAM_STR, 50);
        $stmt->bindParam(":id", $id, PDO::PARAM_INT);
        $stmt->execute();

    } else {
        $stmt = $db->prepare("UPDATE risks SET `status`=:status WHERE `id`=:id");
        $stmt->bindParam(":status", $status, PDO::PARAM_STR, 50);
        $stmt->bindParam(":id", $id, PDO::PARAM_INT);
        $stmt->execute();
    }

    // Close the database connection
    db_close($db);

    $risk = get_risk_by_id($risk_id);
    // Check if the risk exists
    if(!empty($risk[0])){
        $subject = try_decrypt($risk[0]["subject"]);
        $message = "A risk status for subject \"{$subject}\" was changed by the \"" . $escaper->escapeHtml($_SESSION['user']) . "\" user.\nField name : `status` (`" . $escaper->escapeHtml($original_status) . "`=>`" . $escaper->escapeHtml($status) . "`)";
        write_log($risk_id, $_SESSION['uid'] ?? 0, $message);
    }

    return true;
}

/*****************************************************************
 * FUNCTION: TRY DECRYPT FIELDS                                  *
 * Returns $row with each of $fields that is present passed      *
 * through $decrypt (try_decrypt() by default). Used by the API  *
 * read handlers that hand stored encrypted-at-rest columns      *
 * (Encrypted Database Extra) straight to the client: without    *
 * it GET /risks/{id}/mitigations and GET /risks/{id}/reviews    *
 * returned ciphertext whenever that Extra was active.           *
 * try_decrypt() is a passthrough when it is not, so this is     *
 * safe either way. $decrypt is a parameter so the field         *
 * selection is testable without an encryption key. NOTE: the    *
 * shared getters (get_mitigation_by_id(), get_review_by_id())   *
 * return the STORED value; a new API handler that exposes these *
 * columns must decrypt them, and the getters must not (display  *
 * code already calls try_decrypt on their result).              *
 *****************************************************************/
function try_decrypt_fields(array $row, array $fields, ?callable $decrypt = null): array
{
    $decrypt = $decrypt ?? 'try_decrypt';
    foreach ($fields as $field) {
        if (array_key_exists($field, $row)) {
            $row[$field] = $decrypt($row[$field]);
        }
    }
    return $row;
}

/*************************
 * FUNCTION: TRY DECRYPT *
 *************************/
function try_decrypt($value) {

    $decrypted_value = try_decrypt_or_null($value);

    // decrypt_with_openssl returns null on HMAC failure or openssl_decrypt
    // failure. Convert to "" so the 540+ callers (most of which feed the
    // result into escapeHtml / purifyHtml / array assignments / string ops)
    // see a predictable empty string instead of null — null would trigger
    // PHP 8.1+ deprecation warnings in stripos/strcmp/trim sites and could
    // surface as Leaf ErrorExceptions.
    //
    // Also fire a user-facing toast once per request so operators see the
    // failure without having to grep logs. Guard with a $GLOBALS flag so a
    // page with 50 broken rows produces 1 toast, not 50.
    if ($decrypted_value === null) {
        // try_decrypt_or_null() returns null in two distinct situations:
        //   1. a genuine decryption failure — decrypt was attempted on a
        //      non-empty value and openssl/HMAC failed; or
        //   2. a null input — there was nothing to decrypt (a NULL DB column),
        //      which try_decrypt_or_null() passes straight through unchanged.
        // Only (1) is an error worth alerting on. A NULL column is ordinary
        // data (e.g. a risk with no regulation/project/comments), so firing
        // the "could not decrypt" toast for it is a false alarm. Gate the
        // alert on whether there was actually something to decrypt.
        if (!empty($value) && empty($GLOBALS['encryption_extra_decrypt_alert_fired'])) {
            $GLOBALS['encryption_extra_decrypt_alert_fired'] = true;
            global $lang;
            $message = $lang['DecryptionFailureToast']
                ?? 'One or more encrypted fields could not be decrypted. They are shown as empty. Check the system logs for details.';
            set_alert(true, "bad", $message);
        }
        return "";
    }

    return $decrypted_value;
}

/******************************
 * FUNCTION: TRY DECRYPT OR NULL *
 ******************************/
/**
 * Same lookup chain as try_decrypt() but returns null on decryption failure
 * (HMAC mismatch, openssl_decrypt failure, or missing key) without firing
 * the user-facing toast. Use this from code paths that explicitly want to
 * detect failure — e.g. upgrade scripts that need to skip rows they can't
 * decrypt. The toast suppression matters because those callers handle the
 * failure themselves and a UI toast would be noise.
 */
function try_decrypt_or_null($value) {

    // If the value is empty string
    if (!$value) {

        return $value;

    // If the encryption extra is enabled OR a per-request password override
    // is set (used by the activation promise during the per-table encrypt
    // stages, which run before the encryption=true flag flips at the
    // keystone stage).
    } else if (encryption_extra() || ($GLOBALS['encryption_pwd_override'] ?? null) !== null) {

        // Only load it once as the realpath function call takes too much time if called a lot in a request
        // and it's totally unnecessary as the extra will only be loaded once anyway
        if (!isset($GLOBALS['encryption_extra_loaded'])) {

            // Load encryption extra
            require_once(realpath(__DIR__ . '/../extras/encryption/index.php'));
            $GLOBALS['encryption_extra_loaded'] = true;

        }

        $override = $GLOBALS['encryption_pwd_override'] ?? null;

        // Pick the password — override wins if set, otherwise the existing
        // session-or-fetch_key chain.
        if ($override !== null) {

            // Use the per-request override (set by activation stage handlers
            // before the encryption flag flip).
            $decrypted_value = decrypt($override, $value);
        } else if (!isset($_SESSION['encrypted_pass']) || !$_SESSION['encrypted_pass']) {

            // If there's no session, try to get the password from the init.php
            $password = fetch_key();

            if ($password) {
                // If we could, then use it
                $decrypted_value = decrypt($password, $value);
            } else {
                $decrypted_value = "XXXX";
            }
        } else {
            // Storing it in the request-level $_GLOBALS allows us to not have to do the same call thousands of times
            if (!isset($GLOBALS['decoded_encrypted_pass'])) {
                $GLOBALS['decoded_encrypted_pass'] = base64_decode($_SESSION['encrypted_pass']);
            }

            // Decrypt the value
            $decrypted_value = decrypt($GLOBALS['decoded_encrypted_pass'], $value);
        }
    }
    // Otherwise return the value
    else $decrypted_value=$value;

    // Return the decrypted value (may be null if decrypt_with_openssl
    // failed — try_decrypt_or_null() is the helper that exposes that
    // signal to its callers).
    return $decrypted_value;
}

/*************************
 * FUNCTION: TRY ENCRYPT *
 *************************/
function try_encrypt($value) {
    // If the encryption extra is enabled OR a per-request password override
    // is set (used by the activation promise during the per-table encrypt
    // stages, which run before the encryption=true flag flips at the
    // keystone stage).
    $override = $GLOBALS['encryption_pwd_override'] ?? null;
    if (encryption_extra() || $override !== null) {

        // Only load it once as the realpath function call takes too much time if called a lot in a request
        // and it's totally unnecessary as the extra will only be loaded once anyway
        if (!isset($GLOBALS['encryption_extra_loaded'])) {
            // Load encryption extra
            require_once(realpath(__DIR__ . '/../extras/encryption/index.php'));
            $GLOBALS['encryption_extra_loaded'] = true;
        }

        // Pick the password — override wins if set, otherwise the existing
        // session-or-fetch_key chain.
        if ($override !== null) {

            // Use the per-request override (set by activation stage handlers
            // before the encryption flag flip).
            $encrypted_value = encrypt($override, $value);
        } else if (!isset($_SESSION['encrypted_pass']) || !$_SESSION['encrypted_pass']) {
            // If there's no session, try to get the password from the init.php
            $password = fetch_key();

            if ($password) {
                // If we could, then use it
                $encrypted_value = encrypt($password, $value);
            } else {
                $encrypted_value = $value;
            }
        } else {
            // Storing it in the request-level $_GLOBALS allows us to not have to do the same call thousands of times
            if (!isset($GLOBALS['decoded_encrypted_pass'])) {
                $GLOBALS['decoded_encrypted_pass'] = base64_decode($_SESSION['encrypted_pass']);
            }

            // Encrypt the value
            $encrypted_value = encrypt($GLOBALS['decoded_encrypted_pass'], $value);
        }

        // encrypt_with_openssl returns false when the underlying openssl_encrypt
        // call fails (bad cipher / key length / algorithm). PDO binds false as
        // "" on a string column, so the caller stores an empty value rather
        // than a broken blob. Fire a user-facing toast once per request so
        // operators see the failure — the next batch of fields that hit the
        // same failure in the same request reuse the flag and suppress.
        if ($encrypted_value === false) {
            if (empty($GLOBALS['encryption_extra_encrypt_alert_fired'])) {
                $GLOBALS['encryption_extra_encrypt_alert_fired'] = true;
                global $lang;
                $message = $lang['EncryptionFailureToast']
                    ?? 'A field could not be encrypted and was not stored. Check the system logs for details.';
                set_alert(true, "bad", $message);
            }
        }

        return $encrypted_value;
    }
    // Otherwise return the value
    else return $value;
}

/*****************************
 * FUNCTION: GET CURRENT URL *
 *****************************/
function get_current_url()
{
    // Get the base url
    $base_url = get_base_url();

    // Set the current url to the base url plus the request uri
    $url = $base_url . get_encoded_request_uri();

    // Return the URL
    return $url;
}

/**************************
 * FUNCTION: GET BASE URL *
 **************************/
function get_base_url() {

    // Get the simplerisk_base_url from the settings table
    $simplerisk_base_url = get_setting("simplerisk_base_url");

    // If the simplerisk_base_url is not set
    if (!$simplerisk_base_url) {

        // If the base_url is set in the session
        if (isset($_SESSION) && array_key_exists('base_url', $_SESSION)) {

            // Use the value set in the session
            $base_url = $_SESSION['base_url'];

            // Add the simplerisk_base_url to the settings table
            add_setting("simplerisk_base_url", $base_url);

        // Otherwise try to create a base url based on the current url
        } else {

            // Check if we are using the HTTPS protocol
            $isHTTPS = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] == "on");

            // Set the port
            $port = (isset($_SERVER['SERVER_PORT']) && ((!$isHTTPS && $_SERVER['SERVER_PORT'] != "80") || ($isHTTPS && $_SERVER['SERVER_PORT'] != "443")));
            $port = ($port) ? ":" . $_SERVER['SERVER_PORT'] : "";

            // Set the current URL
            $base_url = ($isHTTPS ? "https://" : "http://") . $_SERVER['SERVER_NAME'] . $port;

            $dir_path = realpath(dirname(dirname(__FILE__)));
            $document_root = realpath($_SERVER["DOCUMENT_ROOT"]);
            $app_root = str_replace($document_root,"",$dir_path);
            $app_root = str_replace(DIRECTORY_SEPARATOR ,"/",$app_root);
            $base_url .= $app_root;


            // Append the script name
            //$base_url = $base_url . $_SERVER['SCRIPT_NAME'];

            // HTML Encode the base url
            //$base_url = htmlspecialchars( $base_url, ENT_QUOTES, 'UTF-8' );

            // Get the directory name part of the path
            //$base_url = pathinfo($base_url)['dirname'];

            // Filter out authentication extra from the base url
            //$base_url = str_replace("/extras/authentication", "", $base_url);

            // Add the simplerisk_base_url to the settings table
            add_setting("simplerisk_base_url", $base_url);

        }
        
    // Otherwise
    } else {
        $base_url = $simplerisk_base_url;
    }

    // Return the base_url value
    return rtrim($base_url, '/');
    
}

/*****************************
 * FUNCTION: SELECT REDIRECT *
 *****************************/
function select_redirect()
{
    // If we need to verify the mfa secret
    if (isset($_SESSION['mfa_verify_secret']))
    {
        // Redirect to the verify secret page
        header("Location: account/mfa.php");
    }
    // If a maximum age for the password is set
    else if(get_setting("pass_policy_max_age") != 0)
    {
        // If the user needs to reset their password
        if(check_password_max_time($_SESSION['uid']) === "CHANGE")
        {
            // Use the password max age redirect
            password_max_age_redirect();
        }
        // Otherwise use the registration redirect
        else registration_redirect();
    }
    // Otherwise use the registration redirect
    else registration_redirect();
}

/***************************************
 * FUNCTION: PASSWORD MAX AGE REDIRECT *
 ***************************************/
function password_max_age_redirect()
{
    // Send an alert
    set_alert(true, "bad", "Your password is too old and needs to be changed.");

    // Redirect to change_password page
    header("Location: account/change_password.php");
}

/***************************************
 * FUNCTION: GET DEFAULT LANDING PAGE  *
 ***************************************/
/**
 * Choose a sensible post-login landing page based on the calling user's
 * permissions. Home (reports/home.php) is the default for any user with a
 * core-GRC permission (riskmanagement, compliance, or governance) — its
 * layout is itself permission-adaptive, so it only serves the KPI tiles the
 * user is allowed to see. Users with none of those permissions fall through
 * to their working area (incidents, vulnerabilities, assets, assessments),
 * and failing that, to the profile page.
 *
 * Returns a path relative to the application root (e.g. "reports/home.php").
 */
function get_default_landing_page()
{
    // Home is the curated default for any user with a core-GRC permission.
    if (!empty($_SESSION['riskmanagement']) || !empty($_SESSION['compliance']) || !empty($_SESSION['governance'])) {
        return "reports/home.php";
    }
    // Users with no core-GRC permission fall through to their working area.
    if (incident_management_extra() && !empty($_SESSION['im_incidents']))    return "incidents/index.php";
    if (vulnmgmt_extra()            && !empty($_SESSION['vm_vulnerabilities'])) return "vulnerabilities/index.php";
    if (!empty($_SESSION['asset']))       return "assets/manage_assets.php";
    if (!empty($_SESSION['assessments'])) return "assessments/index.php";
    return "account/profile.php";
}

/***********************************
 * FUNCTION: REGISTRATION REDIRECT *
 ***********************************/
function registration_redirect()
{
    // If the SimpleRisk instance is not registered
    if (get_setting('registration_registered') == 0)
    {
        // If the user is an admin user
        if (isset($_SESSION["admin"]) && $_SESSION["admin"] == "1")
        {
            // The Getting Started widget's "Register your instance" card now
            // prompts admins to register, so we no longer force-redirect an
            // unregistered admin to admin/register.php. Send them to the page
            // they asked for, or their default landing page (home), where the
            // Register card takes over.
            if (isset($_SESSION['requested_url']))
            {
                // Set the requested URL
                $requested_url = $_SESSION['requested_url'];

                // Clear the session variable
                unset($_SESSION['requested_url']);

                // Redirect to the requested location
                header("Location: " . $requested_url);
                exit(0);
            }
            // Otherwise
            else
            {
                // Redirect to the user's default landing page
                header("Location: " . get_default_landing_page());
            }
        }
        // Otherwise
        else
        {
            // If a specific url was requested before authentication
            if (isset($_SESSION['requested_url']))
            {
                // Set the requested URL
                $requested_url = $_SESSION['requested_url'];

                // Clear the session variable
                unset($_SESSION['requested_url']);

                // Redirect to the requested location
                header("Location: " . $requested_url);
                exit(0);
            }
            // Otherwise
            else
            {
                // Redirect to the user's default landing page
                header("Location: " . get_default_landing_page());
            }
        }
    }
    // Otherwise
    else
    {
        // If a specific url was requested before authentication
        if (isset($_SESSION['requested_url']))
        {
            // Set the requested URL
            $requested_url = $_SESSION['requested_url'];

            // Clear the session variable
            unset($_SESSION['requested_url']);

            // Redirect to the requested location
            header("Location: " . $requested_url);
            exit(0);
        }
        // Otherwise
        else
        {
            // Redirect to the user's default landing page
            header("Location: " . get_default_landing_page());
        }
    }
}

/******************************
 * FUNCTION: JS STRING ESCAPE *
 ******************************/
function js_string_escape($string)
{
    global $escaper;
    $string = $escaper->escapeHtml($string);
    $string = str_replace("&#039;", "'", $string);
    return $string;
}

/***********************************
 * FUNCTION: CHECK ACCESS FOR RISK *
 * $risk_id: Risk ID to check      *
 ***********************************/
function check_access_for_risk($risk_id)
{
    // If team separation is enabled
    if (team_separation_extra())
    {
        //Include the team separation extra
        require_once(realpath(__DIR__ . '/../extras/separation/index.php'));

        if (!extra_grant_access($_SESSION['uid'], $risk_id))
        {
            // Set the access to disallowed
            $access = false;
        }
        // Otherwise, set the access to allowed
        else $access = true;
    }
    // Otherwise, set the access to allow
    else $access = true;

    return $access;
}

/****************************************************************
 * FUNCTION: GET RISK ID FOR MITIGATION                           *
 * $mitigation_id: Mitigation ID to resolve                       *
 * Returns the mitigation's parent risk as the raw INTERNAL id     *
 * (the mitigations.risk_id column's own storage form), or null    *
 * when no mitigation with that id exists.                         *
 ****************************************************************/
function get_risk_id_for_mitigation($mitigation_id)
{
    $db = db_open();
    $stmt = $db->prepare("SELECT risk_id FROM mitigations WHERE id = :mitigation_id");
    $stmt->bindParam(":mitigation_id", $mitigation_id, PDO::PARAM_INT);
    $stmt->execute();
    $mitigation = $stmt->fetch();
    db_close($db);

    return $mitigation ? (int)$mitigation['risk_id'] : null;
}

/****************************************************************
 * FUNCTION: CHECK ACCESS FOR MITIGATION                          *
 * $mitigation_id: Mitigation ID to check                         *
 * Resolves the mitigation's parent risk and authorizes against   *
 * it via check_access_for_risk() -- a no-op when Team Separation *
 * is disabled. Returns false when the mitigation does not exist. *
 ****************************************************************/
function check_access_for_mitigation($mitigation_id)
{
    $risk_id = get_risk_id_for_mitigation($mitigation_id);
    if ($risk_id === null) {
        return false;
    }
    // check_access_for_risk() expects the +1000 DISPLAY id.
    return check_access_for_risk($risk_id + 1000);
}

/******************************************************************
 * FUNCTION: FILTER ACCESSIBLE RISK IDS                            *
 * $risk_ids: array of raw (internal) risk ids, or risk-id-like     *
 *            strings (e.g. entries from a caller-supplied CSV list) *
 * Returns the deduplicated, validated risk ids (as ints) the        *
 * current user is authorized to see, via check_access_for_risk() -- *
 * a no-op when Team Separation is disabled. $risk_ids and           *
 * check_access_for_risk() disagree on id convention: the former is  *
 * the raw internal risks.id value, the latter (like extra_grant_    *
 * access() underneath it) expects the +1000 DISPLAY id, so each     *
 * candidate is converted via convert_to_risk_id() before the check. *
 * Invalid entries (non-numeric, empty) are dropped.                 *
 ******************************************************************/
function filter_accessible_risk_ids(array $risk_ids)
{
    $access_cache = [];
    $is_risk_accessible = function ($risk_id) use (&$access_cache) {
        $risk_id = trim((string)$risk_id);
        if ($risk_id === "" || !ctype_digit($risk_id)) {
            return false;
        }
        $risk_id = (int)$risk_id;
        if (!array_key_exists($risk_id, $access_cache)) {
            $access_cache[$risk_id] = check_access_for_risk(convert_to_risk_id($risk_id));
        }
        return $access_cache[$risk_id];
    };

    return array_values(array_unique(array_map(
        'intval',
        array_filter($risk_ids, $is_risk_accessible)
    )));
}

