 **********************************************/
function get_salt_and_password_by_user_id($user_id){
    $db = db_open();
    $stmt = $db->prepare("SELECT salt, password FROM user WHERE value=:user_id;");
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->execute();
    $result = $stmt->fetchAll(PDO::FETCH_ASSOC);
    $res = array("salt" => $result[0]["salt"], "password" => $result[0]["password"]);
    db_close($db);
    return $res;
}

/****************************************
 * FUNCTION: CHECK CURRENT PASSWORD AGE *
 ****************************************/
function check_current_password_age($user_id = false)
{
    if ($user_id === false) {
        return true;
    }

    if (password_meets_min_age($user_id)) {
        return true;
    }

    // Display an alert
    set_alert(true, "bad", "Unable to update the password because the minimum age of ". get_setting("pass_policy_min_age") . " days has not elapsed.");

    return false;
}

/*****************************************************************************
 * FUNCTION: PASSWORD MEETS MIN AGE                                        *
 * Side-effect-free minimum-password-age check, split out of               *
 * check_current_password_age() so callers that already surface their own  *
 * error response (e.g. the v2 API) don't also trigger that function's     *
 * set_alert() -- a caller behind a closed session (session_write_close()  *
 * already ran) would otherwise still leak a stale toast onto the next     *
 * page load via with_alert_session().                                    *
 * $user_id: the user to check                                             *
 *****************************************************************************/
function password_meets_min_age($user_id)
{
    // Get the minimum password age
    $min_password_age = get_setting("pass_policy_min_age");

    // If the minimum age policy is disabled, there's nothing to check
    if ($min_password_age == 0) {
        return true;
    }

    // Open the database connection
    $db = db_open();

    // Get the last time the password for this user was updated
    $stmt = $db->prepare("SELECT last_password_change_date FROM user WHERE value=:user_id;");
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->execute();
    $value = $stmt->fetch();
    $last_password_change_date = strtotime($value['last_password_change_date']);

    // Close the database connection
    db_close($db);

    // Get the min password age date by subtracting today from the number of days x 86400
    $min_password_age_date = time() - ($min_password_age * 86400);

    // The password may be changed once the last change predates the minimum age window
    return $last_password_change_date < $min_password_age_date;
}

/************************************************************************************************
 * FUNCTION: GET LANGUAGES WITH VARIABLES                                                       *
 * $key: Key of the localization                                                                *
 * $params: Parameters that should be replaced into the localization string                     *
 *                                                                                              *
 * Escapes every parameter before substituting it. This is the form to use unless the caller     *
 * has ALREADY escaped the values it is passing in -- in that case use _lang_raw() instead, or   *
 * the values get escaped twice.                                                                *
 *                                                                                              *
 ************************************************************************************************/
/**
 * The taint annotations here are load-bearing, not decoration. Phan's taint-check cannot infer
 * through the substitution helper that the params were escaped, so without them it reports the
 * assembled string as unescaped and every caller that echoes it lights up as a false XSS.
 * They state the contract explicitly: this function escapes its params and returns safe HTML.
 *
 * NOTE: these must live in a plain docblock like this one. In the banner-style comment above,
 * every line is padded with a trailing '*', which taint-check reads as part of the annotation
 * value and silently ignores the whole line.
 *
 * @param-taint $__params escapes_html
 * @return-taint escaped
 */
function _lang(string $__key, array $__params=array()): string {
    global $lang, $escaper;

    // The reverse of the version skew backwards_compatibility.php guards against:
    // an OLDER Extra, built before the split, still calling _lang($key, $params,
    // false). PHP silently discards extra positional arguments to a userland
    // function, so that call does NOT fail -- it just escapes params the old
    // contract said to leave raw, and the caller's own escaping then renders
    // them as "&amp;amp;". Silent wrong output with no error signal, which is
    // worse to diagnose than a fatal. Log it so the mismatch is greppable.
    if (func_num_args() > 2) {
        write_debug_log(
            "_lang('{$__key}') was called with " . func_num_args() . " arguments. The third "
            . "(\$escape) argument was removed: _lang() always escapes, _lang_raw() never does. "
            . "The extra argument is being ignored and these params ARE being escaped -- if the "
            . "caller escapes the result too, its output is double-encoded. This usually means an "
            . "Extra predating the split is running against this Core.",
            'warning'
        );
    }

    $__escaped_params = array();
    foreach($__params as $__param_key => $__param_value){
        $__escaped_params[$__param_key] = $escaper->escapeHtml((string)($__param_value ?? ''));
    }

    return _lang_interpolate((string)($lang[$__key] ?? ''), $__escaped_params);
}

/************************************************************************************************
 * FUNCTION: GET LANGUAGES WITH VARIABLES (UNESCAPED PARAMS)                                    *
 * $key: Key of the localization                                                                *
 * $params: Parameters that should be replaced into the localization string, AS-IS              *
 *                                                                                              *
 * Substitutes the parameters WITHOUT escaping them. Only for callers whose values are already   *
 * escaped, or that escape the returned string when they display it -- using this with an        *
 * unescaped, attacker-controlled value is an XSS hole. When in doubt, use _lang().             *
 ************************************************************************************************/
function _lang_raw(string $__key, array $__params=array()): string {
    global $lang;

    $__raw_params = array();
    foreach($__params as $__param_key => $__param_value){
        // making sure it's not null as the str_replace() function doesn't accept null
        // as the second parameter anymore
        $__raw_params[$__param_key] = (string)($__param_value ?? '');
    }

    return _lang_interpolate((string)($lang[$__key] ?? ''), $__raw_params);
}

/************************************************************************************************
 * FUNCTION: INTERPOLATE LANGUAGE STRING                                                        *
 * $template: The localization string to substitute into                                        *
 * $params: Parameters to substitute, ALREADY in their final (escaped or raw) form              *
 *                                                                                              *
 * Internal helper shared by _lang() and _lang_raw(). It performs no escaping of its own --      *
 * whether the values are safe is decided by whichever of those two the caller went through.    *
 ************************************************************************************************/
function _lang_interpolate(string $__return, array $__params): string {

    // Have to sort the keys from longest to shortest to make sure not replacing
    // $user instead of $username when encountering the pattern of {$username}
    uksort($__params, function ($b, $a) {
        return (strlen($a) == strlen($b) ? strcmp($a, $b) : strlen($a) - strlen($b));
    });

    foreach($__params as $key => $value) {

        // It has to work for all the variable types found in the language files
        $__return = str_replace('{$' . $key .'}', $value, $__return);
        $__return = str_replace('${' . $key .'}', $value, $__return);
        $__return = str_replace('$' . $key, $value, $__return);
    }

    return $__return;
}

/****************************************
 * FUNCTION: GET PASSWORD REQUEST MESSAGES *
 ****************************************/
function getPasswordReqeustMessages($user_id = false) {

    global $lang;

    $messages = array();

    if (get_setting('pass_policy_enabled') == 1) {
        // Get condition for min chars
        $min_chars = get_setting('pass_policy_min_chars');
        $params = array(
            'min_chars' => $min_chars
        );
        $messages[] = _lang('ConditionMessageForMinChar', $params);

        // Get condition for alpa string
        if (get_setting('pass_policy_alpha_required') == 1) {
            $messages[] = _lang('ConditionMessageForAlpha');
        }

        // Get condition for uppercase
        if (get_setting('pass_policy_upper_required') == 1) {
            $messages[] = _lang('ConditionMessageForUppercase');
        }

        // Get condition for lowercase
        if (get_setting('pass_policy_lower_required') == 1) {
            $messages[] = _lang('ConditionMessageForLowercase');
        }

        // Get condition for digits
        if (get_setting('pass_policy_digits_required') == 1) {
            $messages[] = _lang('ConditionMessageForDigit');
        }

        // Get condition for special chars
        if (get_setting('pass_policy_special_required') == 1) {
            $messages[] = _lang('ConditionMessageForSpecialchar');
        }

        // Get condition for password age
        $min_password_age = get_setting("pass_policy_min_age");
        if ($min_password_age != 0) {
            $params = array(
                'min_password_age' => $min_password_age
            );
            $messages[] = _lang('ConditionMessageForMinPasswordAge', $params);
        }
    }

    return $messages;

}

/****************************************
 * FUNCTION: GET USER ID BY PARAM *
 * MATCH UID, USERNAME, NAME
 ****************************************/
function get_user_value_from_name_or_id($name_or_id){
    if(empty($GLOBALS['users'])){
        // Open the database connection
        $db = db_open();

        // Query the database
        $stmt = $db->prepare("select * from `user`");
        $stmt->execute();

        // Store the list in the array
        $users = $stmt->fetchAll(PDO::FETCH_ASSOC);
        $GLOBALS['users'] = $users;

        // Close the database connection
        db_close($db);
    }else{
        $users = $GLOBALS['users'];
    }

    $value = 0;

    // Check if the param is uid
    foreach($users as $user){
        if($user['value'] == $name_or_id){
            $value = $user['value'];
            return $value;
        }
    }

    // Check if the param is username
    foreach($users as $user){
        if($user['username'] == $name_or_id){
            $value = $user['value'];
            return $value;
        }
    }

    // Check if the param is name
    foreach($users as $user){
        if($user['name'] == $name_or_id){
            $value = $user['value'];
            return $value;
        }
    }

    return $value;

}

/***********************************
 * FUNCTION: GET SCORING HISTORIES *
 ***********************************/
function get_scoring_histories($risk_id = null)
{
    // Open the database connection
    $db = db_open();
    // If the risk id is not null
    if ($risk_id != null)
    {
        // Convert the risk id to the internal format
        $risk_id = (int)$risk_id - 1000;

        // Get risk scoring histories by risk id
        if (!team_separation_extra())
        {
            $sql = "SELECT risk_id+1000 as risk_id,calculated_risk,last_update FROM `risk_scoring_history` WHERE risk_id=:risk_id ORDER BY last_update";
        }
        else
        {
            // Include the team separation extra
            require_once(realpath(__DIR__ . '/../extras/separation/index.php'));

            // Get the separation query string
            $separation_query = get_user_teams_query("b");
            
            $sql = "SELECT a.risk_id+1000 as risk_id, a.calculated_risk, a.last_update FROM `risk_scoring_history` a JOIN risks b ON a.risk_id=b.id LEFT JOIN risk_to_team rtt on b.id=rtt.risk_id LEFT JOIN risk_to_additional_stakeholder rtas ON b.id=rtas.risk_id WHERE a.risk_id=:risk_id AND {$separation_query} GROUP BY a.id ORDER BY a.last_update";
        }
        

        $stmt = $db->prepare($sql);
        $stmt->bindParam(":risk_id", $risk_id, PDO::PARAM_INT);
        $stmt->execute();
        $histories = $stmt->fetchAll(PDO::FETCH_ASSOC);
    }
    // If the risk id is null
    else
    {
        // Get risk scoring histories for all risks
        if (!team_separation_extra()){
            $sql = "SELECT risk_id+1000 as risk_id,calculated_risk,last_update FROM `risk_scoring_history` ORDER BY risk_id,last_update";
        }else{
            // If enabled team seperation.

            // Include the team separation extra
            require_once(realpath(__DIR__ . '/../extras/separation/index.php'));

            // Get the separation query string
            $separation_query = get_user_teams_query("t2", true, false);

            $sql = "
                SELECT t1.risk_id+1000 as risk_id, t1.calculated_risk, t1.last_update
                FROM `risk_scoring_history` t1
                    LEFT JOIN `risks` t2 on t1.risk_id=t2.id
                    LEFT JOIN `risk_to_team` rtt on t2.id=rtt.risk_id
                    LEFT JOIN `risk_to_additional_stakeholder` rtas on t2.id=rtas.risk_id
                ". $separation_query ."
                GROUP BY
                    t1.id
                ORDER BY
                    t1.risk_id, t1.last_update";
        }

        $stmt = $db->prepare($sql);
        $stmt->execute();
        $histories = $stmt->fetchAll(PDO::FETCH_ASSOC);
    }

    // Close the database connection
    db_close($db);

    // Return the scoring history
    return $histories;
}

