/*******************************************
 * FUNCTION: STRIP LINE BREAKS FROM STRING *
 *******************************************/
function remove_line_breaks($string){
    $string = trim(preg_replace("/\s\s+|\r|\n/", ' ', $string));
    return $string;
}

/*******************************************************
 * FUNCTION: GET_PARAM - GET VALUE GET OR POST REQUEST *
 ******************************************************/
function get_param($method, $name, $default=""){
    $value = false;
    switch(strtoupper($method)){
        case "POST":
            $value = isset($_POST[$name]) ? $_POST[$name] : false;
        break;

        case "GET":
            $value = isset($_GET[$name]) ? $_GET[$name] : false;
        break;

        case "REQUEST":
            $value = isset($_REQUEST[$name]) ? $_GET[$name] : false;
        break;
    }

    if($value === false){
        $data = json_decode(file_get_contents('php://input'), true);
        if(is_array($data)){
            $value = isset($data[$name]) ? $data[$name] : false;
        }
    }

    if($value === false){
        $value = $default;
    }

    return $value;
}

/*******************************************************************
 * FUNCTION: PARAM WAS SENT                                        *
 * Returns true when the caller actually named $name in the request*
 * body, as opposed to get_param() having silently fallen back to  *
 * its default.                                                    *
 *                                                                 *
 * This is what makes PATCH mean *partial* update. get_param()      *
 * cannot express the difference: it returns the default both for   *
 * "the caller sent nothing" and for "the caller sent an empty      *
 * value", so a handler built on it alone has no way to honour the  *
 * convention this codebase settled on --                           *
 *                                                                  *
 *     an explicit '' (or []) from the caller CLEARS the field;      *
 *     an ABSENT field PRESERVES whatever is stored.                 *
 *                                                                  *
 * It deliberately mirrors get_param("post", ...)'s own lookup       *
 * order and its isset() semantics, so the two never disagree about  *
 * where a value came from: $_POST first (which                      *
 * parse_non_post_body_into_post() has already populated for PATCH   *
 * and PUT), then a JSON php://input body for callers that POST raw  *
 * JSON without form encoding.                                       *
 *******************************************************************/
function param_was_sent($name)
{
    if (isset($_POST[$name])) {
        return true;
    }

    $data = json_decode(file_get_contents('php://input'), true);

    return is_array($data) && isset($data[$name]);
}

/*******************************************************************
 * FUNCTION: NORMALIZE ID LIST PARAM                                *
 * Accepts a request value that is either an array (the legacy       *
 * name[]=1&name[]=2 shape) or a single comma-separated string (a    *
 * caller collapsing many values into one field so the POST field    *
 * count doesn't scale with the selection size -- a <select multiple>*
 * with hundreds of selected options can otherwise push the request  *
 * past PHP's max_input_vars ceiling, silently truncating the body). *
 * Returns a plain array either way, with blank/whitespace-only      *
 * string entries dropped. null/false/non-array/non-string input     *
 * returns an empty array.                                           *
 *******************************************************************/
function normalize_id_list_param($value): array
{
    if (is_array($value)) {
        return $value;
    }

    if (!is_string($value) || trim($value) === '') {
        return [];
    }

    return array_values(array_filter(
        array_map('trim', explode(',', $value)),
        fn($v) => $v !== ''
    ));
}

/************************************
 * FUNCTION: IS SIMPLERISK DB TABLE *
 ************************************/
function is_simplerisk_db_table($table_name)
{
    // Initialize a tables array
    $tables = array();

    // Open the database connection
    $db = db_open();

    // Get list of tables
    $stmt = $db->prepare("SHOW TABLES;");
    $stmt->execute();
    $array = $stmt->fetchAll();

    foreach ($array as $value)
    {
        // Add the value to an array
        $table = $value[0];
        $tables[] = $table;
    }

    // Close the database connection
    db_close($db);

    // Return whether the table name is in the list of tables
    return in_array($table_name, $tables);
}

/**********************************
