/**
 * Returns the admin status of the current user(or the user with the specified id).
 * 
 * @param boolean $id [Optional] If no user id provided then the function will return whether the current user is an admin user.
 * @return boolean admin status of the user(current or the one with the specified id)
 */
function is_admin($id = false) {

    // If there's no user id provided OR we're checking the logged in user then it will work the way it did before
    if ($id === false || (isset($_SESSION['uid']) && (int)$id === (int)$_SESSION['uid'])) {

        // If the user is not logged in as an administrator
        if (!isset($_SESSION["admin"]) || $_SESSION["admin"] != "1") {
            return false;
        } else {
            return true;
        }

    } else {

        $db = db_open();

        $stmt = $db->prepare("
            SELECT 
                `admin`
            FROM
                `user`
            WHERE
                `value` = :user_id;
        ");
        $stmt->bindParam(":user_id", $id, PDO::PARAM_INT);
        $stmt->execute();

        $admin = $stmt->fetchColumn();

        db_close($db);
        
        return $admin !== null && $admin === '1';

    }
}

/*************************************
 * FUNCTION: UPLOAD COMPLIANCE FILES *
 *************************************/
function upload_compliance_files($test_audit_id, $ref_type, $files, $version=1, $user=null, $entity_name=null)
{
    global $escaper, $lang;

    // Same refusal as upload_file(), for the same reason: this is the widest of
    // the BLOB-write routes a demo visitor can reach — control test evidence
    // (compliance.php), governance documents and exception evidence
    // (governance.php), and three v2 API endpoints (api.php) all land here, and
    // none of them requires admin.
    //
    // Unlike upload_file()/upload_validation_file(), $files is the raw
    // $_FILES['file'][...] multi-file shape, so "was a file actually submitted"
    // isn't a single isset() check — a <input type=file name="file[]"> with
    // nothing chosen still arrives as ['name' => [''], ...], a non-empty array
    // with a blank filename. Only refuse when at least one entry has a real
    // name; otherwise this is just a plain save with no attachment and the
    // demo restriction has nothing to refuse.
    //
    // Returns the shape a successful call returns with nothing uploaded:
    // [true, [], []]. Callers destructure this as [$status, $file_ids, $errors]
    // and branch on a non-empty $errors, so an empty error list lets the
    // surrounding save (the test result, the document, the exception) complete
    // normally with no attachment — the same "record saves, file doesn't"
    // trade-off upload_file() makes.
    $has_submitted_file = false;
    foreach (($files['name'] ?? []) as $name) {
        if ($name !== '' && $name !== null) {
            $has_submitted_file = true;
            break;
        }
    }

    if ($has_submitted_file && demo_mode()) {
        set_alert(true, "bad", $lang['ActionDisabledOnDemoInstance']);

        return [true, [], []];
    }

    // If no user was specified, try the session uid, otherwise default to 0
    if (!$user) {
        $user = $_SESSION['uid'] ?? 0;
    }

    // Open the database connection
    $db = db_open();
    
    $errors = array();

    $file_ids = [];

    foreach($files['name'] as $key => $name){
        if(!$name)
            continue;
            
        $file = array(
            'name' => $files['name'][$key],
            'type' => $files['type'][$key],
            'tmp_name' => $files['tmp_name'][$key],
            'size' => $files['size'][$key],
            'error' => $files['error'][$key],
        );
        
        if (strlen($file['name']) <= 100) {

            $finfo = new finfo(FILEINFO_MIME_TYPE);

            $file_type_name = $finfo->file($file['tmp_name']);
            $file_type_extension_name = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
    
            // Check if the file type and extension are allowed
            $file_type_extension_mapping_exists = check_file_type_and_extension_exists($file_type_name, $file_type_extension_name);
    
            // If the file type and extension combination is appropriate
            if ($file_type_extension_mapping_exists) {

                // Get the maximum upload file size
                $max_upload_size = get_setting("max_upload_size");
    
                // If the file size is less than max size
                if ($file['size'] < $max_upload_size)
                {
                    // If there was no error with the upload
                    if ($file['error'] == 0)
                    {
                        // Read the file
                        $content = fopen($file['tmp_name'], 'rb');
    
                        // Create a unique file name
                        $unique_name = generate_token(30);
    
                        // Store the file in the database
                        $stmt = $db->prepare("INSERT compliance_files (ref_id, ref_type, name, unique_name, type, size, user, content, version) VALUES (:ref_id, :ref_type, :name, :unique_name, :type, :size, :user, :content, :version)");
                        $stmt->bindParam(":ref_id", $test_audit_id, PDO::PARAM_INT);
                        $stmt->bindParam(":ref_type", $ref_type, PDO::PARAM_STR);
                        $stmt->bindParam(":name", $file['name'], PDO::PARAM_STR, 30);
                        $stmt->bindParam(":unique_name", $unique_name, PDO::PARAM_STR, 30);
                        $stmt->bindParam(":type", $file['type'], PDO::PARAM_STR, 30);
                        $stmt->bindParam(":size", $file['size'], PDO::PARAM_INT);
                        $stmt->bindParam(":user", $user, PDO::PARAM_INT);
                        $stmt->bindParam(":content", $content, PDO::PARAM_LOB);
                        $stmt->bindParam(":version", $version, PDO::PARAM_INT);
                        $stmt->execute();
                        
                        $file_ids[] = $db->lastInsertId();

                        $log_type = $ref_type;
                        if ($ref_type == 'documents') {
                            $log_type = 'document';
                        } else if ($ref_type == 'exceptions') {
                            $log_type = 'exception';
                        }

                        // Audit log entry for uploading a file. $entity_name (when the
                        // caller has it -- documents does, exceptions/test_audit don't
                        // pass one today) names the record the file was attached to, not
                        // just the raw uploaded filename -- otherwise this is the one
                        // document audit message with no document name anywhere in its
                        // own text, so get_documents_audit_log()'s live JOIN against
                        // `documents` is the ONLY way to resolve it, and that JOIN
                        // returns null once the document is deleted (classify_document_
                        // audit_activity()/extract_document_name_from_audit_message(),
                        // includes/governance.php, parse both shapes of this message).
                        $message = $entity_name !== null
                            ? "File \"" . $file['name'] . "\" was uploaded to document \"" . $entity_name . "\" (ID: \"" . $test_audit_id . "\") by username \"" . $escaper->escapeHtml($_SESSION['user']) . "\"."
                            : "File \"" . $file['name'] . "\" was uploaded by username \"" . $escaper->escapeHtml($_SESSION['user']) . "\".";
                        write_log($test_audit_id + 1000, $_SESSION['uid'] ?? 0, $message, $log_type);

                    }
                    // Otherwise
                    else
                    {
                        switch ($file['error'])
                        {
                            case 1:
                                $errors[] = "The uploaded file exceeds the upload_max_filesize directive in php.ini.";
                                break;
                            case 2:
                                $errors[] = "The uploaded file exceeds the MAX_FILE_SIZE directive that was specified in the HTML form.";
                                break;
                            case 3:
                                $errors[] = "The uploaded file was only partially uploaded.";
                                break;
                            case 4:
//                                $errors[] = "No file was uploaded.";
                                break;
                            case 6:
                                $errors[] = "Missing a temporary folder.";
                                break;
                            case 7:
                                $errors[] = "Failed to write file to disk.";
                                break;
                            case 8:
                                $errors[] = "A PHP extension stopped the file upload.";
                                break;
                            default:
                                $errors[] = "There was an error with the file upload.";
                        }
                    }
                }
                else $errors[] = "The uploaded file was too big to store in the database.  A SimpleRisk administrator can modify the maximum file upload size under \"File Upload Settings\" under the \"Configure\" menu.  You may also need to modify the 'upload_max_filesize' and 'post_max_size' values in your php.ini file.";
            } else {

                $errors[] = "The file type and extension combination ('{$escaper->escapeHtml($file_type_name)}', '{$escaper->escapeHtml($file_type_extension_name)}') is not supported. A SimpleRisk administrator can add it under 'File Upload Settings' under the 'Configure' menu.";

            }
        } else $errors[] = "The uploaded file name is longer than the allowed maximum (100 characters).";
    }

    // Close the database connection
    db_close($db);
    
    if($errors){
        return [false, [], $errors];
    }else{
        return [true, $file_ids, []];
    }
}

