    }
}

/*********************************************
 * FUNCTION: CHECK UPLOADED FILE SIZE ERRORS *
 ********************************************/
function checkUploadedFileSizeErrors() {
    global $lang, $escaper;

    // This check is here because if the user uploads a file that's size exceeds the `post_max_size` defined in the
    // php.ini then it'll wipe out the contents of the $_POST and cause a CSRF validation failure.
    // In this case we'll just simply refresh the page and display an error message.
    if (isset($_SERVER['REQUEST_METHOD'])&& $_SERVER['REQUEST_METHOD'] === 'POST'
        && isset($_SERVER['CONTENT_LENGTH']) && empty($_POST)) {

        $maxPostSize = trim(ini_get('post_max_size'));
        if ($maxPostSize != '') {
            $last = strtolower(
                $maxPostSize[strlen($maxPostSize) - 1]
            );
        } else {
            $last = '';
        }

        $maxPostSize = (int)$maxPostSize;
        switch ($last) {
            // The 'G' modifier is available since PHP 5.1.0
            case 'g':
                $maxPostSize *= 1024;
                // fall through
            case 'm':
                $maxPostSize *= 1024;
                // fall through
            case 'k':
                $maxPostSize *= 1024;
                // fall through
        }

        if ($_SERVER['CONTENT_LENGTH'] > $maxPostSize) {
            set_alert(true, "bad", $lang['UploadingFileTooBig']);
            refresh();
        }
    }
}

/******************************************
 * FUNCTION: GET PHP EXECUTABLE FROM PATH *
 * Only works if the executable is on the *
 * path.                                  *
 ******************************************/
function getPHPExecutableFromPath() {
  $paths = explode(PATH_SEPARATOR, getenv('PATH'));
  foreach ($paths as $path) {
    // we need this for XAMPP (Windows)
    if (strstr($path, 'php.exe') && isset($_SERVER["WINDIR"]) && file_exists($path) && is_file($path)) {
        return $path;
    }
    else {
        $php_executable = $path . DIRECTORY_SEPARATOR . "php" . (isset($_SERVER["WINDIR"]) ? ".exe" : "");
        if (file_exists($php_executable) && is_file($php_executable)) {
           return $php_executable;
        }
    }
  }
  return FALSE; // not found
}

/*************************
 * FUNCTION: HASH EQUALS *
 *************************/
// This function does not exist in PHP < 5.6 so we define it here
if (!function_exists('hash_equals')) {

    /**
     * Timing attack safe string comparison
     * 
     * Compares two strings using the same time whether they're equal or not.
     * This function should be used to mitigate timing attacks; for instance, when testing crypt() password hashes.
     * 
     * @param string $known_string The string of known length to compare against
     * @param string $user_string The user-supplied string
     * @return boolean Returns TRUE when the two strings are equal, FALSE otherwise.
     * @phan-suppress PhanRedefineFunctionInternal -- polyfill guarded by function_exists() for PHP < 5.6
     */
    function hash_equals($known_string, $user_string)
    {
        if (func_num_args() !== 2) {
            // handle wrong parameter count as the native implentation
            trigger_error('hash_equals() expects exactly 2 parameters, ' . func_num_args() . ' given', E_USER_WARNING);
            return null;
        }
        if (is_string($known_string) !== true) {
            trigger_error('hash_equals(): Expected known_string to be a string, ' . gettype($known_string) . ' given', E_USER_WARNING);
            return false;
        }
        $known_string_len = strlen($known_string);
        $user_string_type_error = 'hash_equals(): Expected user_string to be a string, ' . gettype($user_string) . ' given'; // prepare wrong type error message now to reduce the impact of string concatenation and the gettype call
        if (is_string($user_string) !== true) {
            trigger_error($user_string_type_error, E_USER_WARNING);
            // prevention of timing attacks might be still possible if we handle $user_string as a string of diffent length (the trigger_error() call increases the execution time a bit)
            $user_string_len = strlen($user_string);
            $user_string_len = $known_string_len + 1;
        } else {
            $user_string_len = $known_string_len + 1;
            $user_string_len = strlen($user_string);
        }
        if ($known_string_len !== $user_string_len) {
            $res = $known_string ^ $known_string; // use $known_string instead of $user_string to handle strings of diffrent length.
            $ret = 1; // set $ret to 1 to make sure false is returned
        } else {
            $res = $known_string ^ $user_string;
            $ret = 0;
        }
        for ($i = strlen($res) - 1; $i >= 0; $i--) {
            $ret |= ord($res[$i]);
        }
        return $ret === 0;
    }

}

/*****************************************************************************
 * FUNCTION: PREVENT EXTRA DOUBLE SUBMIT                                     *
 * This function won't let the enable logic of the extra run                 *
 * when it's already enabled or the disable logic when it's already disabled *
 * $extra       = The name of the extra                                      *
 * $is_enable   = Whether the function is called from the extra's enable     *
 *****************************************************************************/
function prevent_extra_double_submit($extra, $is_enable) {

    global $lang;

    /*
        The encryption_extra() == $is_enable part might need some explanation:
        We only have to interrupt if
            - the extra is turned on and it's the enable function
            - the extra is turned off and it's the disable function
        thus it makes sense to compare the two and interrupt when they're equal.

        extra | enable | interrupt
        --------------------------
          1   |    1   |    1
          1   |    0   |    0
          0   |    1   |    0
          0   |    0   |    1
    */
    $interrupt =
        ($extra == "encryption" && (encryption_extra() == $is_enable)) ||
        ($extra == "custom_authentication" && (custom_authentication_extra() == $is_enable)) ||
        ($extra == "customization" && (customization_extra() == $is_enable)) ||
        ($extra == "team_separation" && (team_separation_extra() == $is_enable)) ||
        ($extra == "notification" && (notification_extra() == $is_enable)) ||
        ($extra == "import_export" && (import_export_extra() == $is_enable)) ||
        ($extra == "incident_management" && (incident_management_extra() == $is_enable)) ||
        ($extra == "api" && (api_extra() == $is_enable)) ||
        ($extra == "assessments" && (assessments_extra() == $is_enable)) ||
        ($extra == "complianceforge_scf" && (complianceforge_scf_extra() == $is_enable)) ||
        ($extra == "advanced_search" && (advanced_search_extra() == $is_enable)) ||
        ($extra == "jira" && (jira_extra() == $is_enable)) ||
        ($extra == "organizational_hierarchy" && (organizational_hierarchy_extra() == $is_enable)) ||
        ($extra == "ucf" && (ucf_extra() == $is_enable)) ||
        ($extra == "extra_vulnmgmt" && (vulnmgmt_extra() == $is_enable)) ||
        ($extra == "workflows" && (workflows_extra() == $is_enable));

    if ($interrupt) {
        set_alert(true, "bad", $lang['ExtraIsAlready' . ($is_enable ? 'Enabled': 'Disabled')]);
        refresh();
    }
}

/********************************************************************
 * FUNCTION: PREVENT FORM DOUBLE SUBMIT SCRIPT                      *
 * When the $forms is set, only the forms of the provided ids       *
 * will trigger the page-wide disablement of form submit buttons.   *
 ********************************************************************/
function prevent_form_double_submit_script($forms = false) {
        if ($forms) {
        echo "
            $(document).ready(function(){";
        foreach ($forms as $form) {
            echo "
                $('#{$form}').submit(function(evt) {
                    setTimeout(function(){ $(\"input[type='submit']\").prop('disabled', true); }, 1);
                    setTimeout(function(){ $(\"button[type='submit']\").prop('disabled', true); }, 1);
                    return true;
                });
            ";
        }
        echo "
            });";
    } else {
        echo "
            $(document).ready(function(){
                $('form').submit(function(evt) {
                    setTimeout(function(){ $(\"input[type='submit']\").prop('disabled', true); }, 1);
                    setTimeout(function(){ $(\"button[type='submit']\").prop('disabled', true); }, 1);
                    return true;
                });
            });\n";
    }
}

/*********************************
 * FUNCTION: GET RISK BY SUBJECT *
 *
 * The return_multiple parameter allows it to return all of the matches' ids
 * When it's true the function will return an array even when there's only one match
 *********************************/
function get_risk_by_subject($subject, $return_multiple = false)
{
    // If the encrypted db extra is enabled
    if (encryption_extra())
    {
        // Load the extra
        require_once(realpath(__DIR__ . '/../extras/encryption/index.php'));
        return encryption_get_risk_by_subject($subject, $return_multiple);
    }
    // If the encrypted db extra is not enabled
    else
    {
        // Open the database connection
        $db = db_open();

        // Search for a risk with this subject
        $stmt = $db->prepare("SELECT `id` FROM `risks` WHERE `subject` = :subject;");
        $stmt->bindParam(":subject", $subject, PDO::PARAM_STR);
        $stmt->execute();

        // Fetch the result
        $result = $stmt->fetchAll(PDO::FETCH_COLUMN);

        // Close the database connection
        db_close($db);

        // If we have at least one result
        if (count($result) > 0) {
            // Return either all matches or just the first risk id
            return $return_multiple ? $result : $result[0];
        }
        else return false;
    }

    // Return false
    return false;
}

/*******************************************
 * FUNCTION: GET TYPE OF COLUMN            *
 * Please note, that this function only    *
 * returns 'varchar' of type 'varchar(10)' *
 *******************************************/
function getTypeOfColumn($table, $column) {
    $db = db_open();

    $stmt = $db->prepare("SELECT `DATA_TYPE` FROM `information_schema`.`COLUMNS` WHERE `TABLE_SCHEMA` = '" . DB_DATABASE . "' AND `TABLE_NAME` = :table AND `COLUMN_NAME` = :column;");
    $stmt->bindParam(":table", $table, PDO::PARAM_STR);
    $stmt->bindParam(":column", $column, PDO::PARAM_STR);
    $stmt->execute();

    $result = $stmt->fetch(pdo::FETCH_COLUMN, 0);

    db_close($db);

    return $result ? strtolower($result) : "";
}

/********************************
 * FUNCTION: GET TAGS OF TAGGEE *
 ********************************/
function getTagsOfTaggee($taggee_id, $type) {

    global $tag_types;

    if (!$taggee_id || !in_array($type, $tag_types))
        return;

    $db = db_open();

    //Load tags currently assigned to the taggee
    $stmt = $db->prepare("
        SELECT
            `t`.`tag`
        FROM
            `tags` t
            INNER JOIN `tags_taggees` tt ON `tt`.`tag_id` = `t`.`id`
        WHERE
            `tt`.`taggee_id` = :taggee_id and `tt`.`type` = :type;
    ");
    $stmt->bindParam(":taggee_id", $taggee_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();
    $result = $stmt->fetchAll();

    db_close($db);

    //Get the actual tag values(the $result array contains other info as well)
    return array_column($result, 'tag');
}

/**********************
 * FUNCTION: HAS TAGS *
 **********************/
function hasTags($taggee_id, $type) {

    global $tag_types;

    if (!$taggee_id || !in_array($type, $tag_types))
        return;

    $db = db_open();

    //Check if there're tags currently assigned to the taggee
    $stmt = $db->prepare("
        SELECT
            distinct(5)
        FROM
            `tags_taggees` tt
        WHERE
            `tt`.`taggee_id` = :taggee_id and `tt`.`type` = :type;
    ");
    $stmt->bindParam(":taggee_id", $taggee_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();
    $result = $stmt->fetch();

    db_close($db);

    return !empty($result);
}

/****************************************************************************
 * FUNCTION: UPDATE TAGS OF TYPE                                            *
 * Gets an id and a type to decide what the tag is assigned to(referenced   *
 * as `taggee`) and updates its tags. Type can be either `risk` or `asset`. *
 * Third parameter is an array. If the array is empty, all the tags will be *
 * removed from the taggee                                                  *
 ****************************************************************************/
function updateTagsOfType($taggee_id, $type, $tags) {

    global $tag_types;

    if (!$taggee_id || !in_array($type, $tag_types) || !is_array($tags)) {
        return false;
    }

    // Remove empty values
    $tags = array_values(
        array_filter(
            array_map('trim', $tags),
            fn($value) => !is_null($value) && $value !== ''
        )
    );

    // Remove duplicates (case insensitive)
    $tags = array_intersect_key($tags, array_unique(array_map('strtolower', $tags)));

    //Get the actual tag values(the $result array contains other info as well)
    $tags_current = getTagsOfTaggee($taggee_id, $type);

    $db = db_open();

    // Clever usage of array_diffs to calculate what tags are removed from the taggee
    // and what tags are added
    $tags_to_remove = array_diff($tags_current, $tags);
    $tags_to_add = array_diff($tags, $tags_current);

    // If there're tags to remove
    if ($tags_to_remove) {

        //building an array of parameters to bind
        $params = array(":taggee_id" => $taggee_id, ":type" => $type);

        // building the list of strings to be used in the `in` part of the sql
        // to be able to bind the params
        // We need this to be able to delete all the connections to the removed
        // tags in one go, instead of using a loop
        $tags_to_remove_in = [];
        foreach ($tags_to_remove as $i => $tag)
        {
            $key = ":id".$i;
            $tags_to_remove_in[] = $key;
            $params[$key] = $tag;
        }

        // making the comma separated list to be included in the sql
        $tags_to_remove_in = implode(", ", $tags_to_remove_in);

        // Remove the entries from the junction table that connected the deleted tags to the taggee
        $stmt = $db->prepare("
            delete
                `tt`
            from
                `tags` t
                inner join `tags_taggees` tt on `tt`.`tag_id` = `t`.`id`
            where
                `tt`.`taggee_id` = :taggee_id and
                `tt`.`type` = :type and
                `t`.`tag` in ({$tags_to_remove_in});
        ");
        $stmt->execute($params);

        // Clean up every tags that aren't referenced by the junction table
        $stmt = $db->prepare("
            delete
                `t`
            from
                `tags` `t`
                left join `tags_taggees` `tt` on `tt`.`tag_id` = `t`.`id`
            where
                `tt`.`taggee_id` is null;
        ");
        $stmt->execute();
    }

    //If there're tags to add
    if ($tags_to_add) {
        //Sadly we can't do this in a single sql so we have to resort to looping
        foreach ($tags_to_add as $tag) {
            if(!$tag) continue;
            // Get the id of the tag (to either use it or to know that it's not
            // in the database yet)
            $stmt = $db->prepare("
                SELECT
                    `id`
                FROM
                    `tags` `t`
                WHERE `t`.`tag` = :tag;
            ");
            $stmt->bindParam(":tag", $tag, PDO::PARAM_STR);
            $stmt->execute();

            $tag_id = $stmt->fetchAll();

            if ($tag_id) {
                $tag_id = $tag_id[0];
                // If the tag is already in the database we just use the id to create
                // the connection between the taggee and the tag in the junction table
                $stmt = $db->prepare("
                    INSERT INTO
                        `tags_taggees` (`tag_id`, `taggee_id`, `type`)
                    VALUES
                        (:tag_id, :taggee_id, :type);
                ");
                $stmt->bindParam(":tag_id", $tag_id[0], PDO::PARAM_STR);
                $stmt->bindParam(":taggee_id", $taggee_id, PDO::PARAM_STR);
                $stmt->bindParam(":type", $type, PDO::PARAM_STR);
                $stmt->execute();
            } else {
                // If the tag isn't in the database yet, we have to create it and
                // using its id to create the connection to the taggee
                $stmt = $db->prepare("
                    INSERT INTO
                        `tags`(`tag`)
                    VALUES(:tag);
                    INSERT INTO
                        `tags_taggees` (`tag_id`, `taggee_id`, `type`)
                    VALUES
                        (LAST_INSERT_ID(), :taggee_id, :type);
                ");
                $stmt->bindParam(":tag", $tag, PDO::PARAM_STR);
                $stmt->bindParam(":taggee_id", $taggee_id, PDO::PARAM_STR);
                $stmt->bindParam(":type", $type, PDO::PARAM_STR);
                $stmt->execute();
                // We have to use it because of the LAST_INSERT_ID() in the previous query
                $stmt->closeCursor();
            }
        }
    }

    db_close($db);

    // No audit logging is needed if nothing changed
    // Also no audit logging is done when there's no session(like when a questionnaire is filled without a user actually logging in)
    if (isset($_SESSION) && isset($_SESSION['user']) && isset($_SESSION['uid']) && ($tags_to_add || $tags_to_remove)) {
        global $lang;

        $tag_changes = [];
        if ($tags_to_add) {
            $tag_changes[] = _lang_raw('TagUpdateAuditLogAdded', array('tags_added' => implode(", ", $tags_to_add)));
        }

        if ($tags_to_remove) {
            $tag_changes[] = _lang_raw('TagUpdateAuditLogRemoved', array('tags_removed' => implode(", ", $tags_to_remove)));
        }

        $message = _lang_raw('TagUpdateAuditLog', array(
                'user' => $_SESSION['user'],
                'type' => $lang['TagType_' . $type],
                'id' => $taggee_id + ($type == 'risk' ? 1000 : 0),
                'tags_from' => implode(", ", $tags_current),
                'tags_to' => implode(", ", $tags),
                'tag_changes' => implode(", ", $tag_changes)
            ));

        write_log($taggee_id + 1000, $_SESSION['uid'] ?? 0, $message, $type);
    }

    return true;
}

/*******************************************************************************
 * FUNCTION: TAG TYPE PERMISSION REQUIREMENT                                    *
 * Fail-closed authorization map for tag types (SR-1794 / SR-751). Returns the  *
 * permission requirement for reading tags of $type, or null when the type is   *
 * not recognized — in which case the caller MUST deny. No tag type may be      *
 * served without an explicit entry here. Pure (no session/DB access) so the    *
 * map is unit-testable, and any type added to $tag_types without a matching    *
 * case here fails closed by default.                                           *
 *                                                                              *
 * Returns ['permissions' => string[], 'extra' => ?string, 'deny_lang' => str]: *
 *   permissions — the session must hold AT LEAST ONE of these.                  *
 *   extra       — required Extra name (e.g. 'assessments'); null if none.       *
 *   deny_lang   — lang key for the denial message.                             *
 *******************************************************************************/
function tag_type_permission_requirement($type) {
    switch ($type) {
        case 'risk':
            return ['permissions' => ['riskmanagement'], 'extra' => null, 'deny_lang' => 'NoPermissionForRiskManagement'];
        case 'asset':
            return ['permissions' => ['asset'], 'extra' => null, 'deny_lang' => 'NoPermissionForAsset'];
        case 'test':
        case 'test_audit':
            return ['permissions' => ['compliance'], 'extra' => null, 'deny_lang' => 'NoPermissionForCompliance'];
        case 'questionnaire_risk':
        case 'questionnaire_answer':
        case 'questionnaire_pending_risk':
            return ['permissions' => ['assessments'], 'extra' => 'assessments', 'deny_lang' => 'NoPermissionForAssessments'];
        case 'incident_management_source':
        case 'incident_management_destination':
            return ['permissions' => ['im_submit_incidents', 'im_edit_incidents'], 'extra' => 'incident_management', 'deny_lang' => 'NoPermissionForIncidentManagement'];
        default:
            return null; // fail-closed: an unmapped tag type is never served
    }
}

/*******************************************************************************
 * FUNCTION: CHECK TAG TYPE PERMISSION                                          *
 * Session-aware check: may the current user read tags of $type? Fail-closed    *
 * (unknown type → false). Grants access iff the session holds at least one of  *
 * the mapped permissions AND the mapped Extra (if any) is active.              *
 *******************************************************************************/
function check_tag_type_permission($type) {
    $requirement = tag_type_permission_requirement($type);
    if ($requirement === null) {
        return false;
    }
    if ($requirement['extra'] !== null) {
        $extra_function = $requirement['extra'] . '_extra';
        if (!function_exists($extra_function) || !$extra_function()) {
            return false;
        }
    }
    foreach ($requirement['permissions'] as $permission) {
        if (check_permission($permission)) {
            return true;
        }
    }
    return false;
}

/*******************************************************************************
 * FUNCTION: COMPLIANCE FILE REQUIRED EXCEPTION PERMISSION                      *
 * SR-1694: the granular exception-permission that a compliance_files download  *
 * must enforce for a given ref_type at the sink (download_compliance_file()),  *
 * or null when the ref_type has no exception-module permission of its own.     *
 * Exception attachments (ref_type 'exceptions') require view_exception —       *
 * mirroring the exception display API, which already gates on                  *
 * check_permission_exception('view'). `documents` and `test_audit` are not     *
 * exception-module resources, so they return null here — `documents` has its   *
 * own granular gate instead, see compliance_file_required_documentation_       *
 * permission() below. Pure — no session/DB access — so the mapping is          *
 * unit-testable and the coarse-by-design intent is locked against accidental   *
 * regression.                                                                  *
 *******************************************************************************/
function compliance_file_required_exception_permission($ref_type) {
    return $ref_type === 'exceptions' ? 'view' : null;
}

/*******************************************************************************
 * FUNCTION: COMPLIANCE FILE REQUIRED DOCUMENTATION PERMISSION                  *
 * Completes SR-1694 for the `documents` ref_type. When SR-1694 first gated     *
 * this sink, `documents` had no granular view permission of its own, so the    *
 * owning-module gate (governance) was its whole model — see the historical     *
 * note on compliance_file_required_exception_permission() above. Governance    *
 * Documents now has its own view_documentation permission, so a               *
 * governance-menu user without it must still be denied a document download    *
 * at this sink, the same way an exceptions-module user without view_exception  *
 * is denied an exception attachment. Returns null for every other ref_type —  *
 * this map is documents-specific, not a general allow-map. Pure — no           *
 * session/DB access — so the mapping is unit-testable.                         *
 *******************************************************************************/
function compliance_file_required_documentation_permission($ref_type) {
    return $ref_type === 'documents' ? 'view_documentation' : null;
}

/*******************************************************************************
 * FUNCTION: COMPLIANCE FILE OWNING MODULE PERMISSION                           *
 * The module permission that owns a compliance_files ref_type. The             *
 * `compliance_files` table is shared by two modules — audit evidence           *
 * (test_audit) belongs to Compliance, while documents and exception            *
 * attachments belong to Governance — but BOTH download entry points            *
 * (governance/download.php and compliance/download.php) forward to the same    *
 * sink, each gated only on its own module. That makes the coarse gate          *
 * per-PAGE, never per-FILE: without this map a governance-only user can stream *
 * compliance audit evidence through governance/download.php by unique_name,    *
 * and vice versa.                                                              *
 *                                                                              *
 * Returns null for an unrecognised ref_type — the caller treats "no known      *
 * owner" as deny (see compliance_file_download_denied()). Pure — no session or *
 * DB access — so the ownership map is unit-testable and locked against         *
 * accidental regression when a fourth ref_type is added.                       *
 *******************************************************************************/
function compliance_file_owning_module_permission($ref_type) {
    $map = [
        'test_audit' => 'compliance',
        'documents'  => 'governance',
        'exceptions' => 'governance',
    ];
    return $map[$ref_type] ?? null;
}

/*******************************************************************************
 * FUNCTION: COMPLIANCE FILE DOWNLOAD DENIED                                    *
 * The deny decision enforced at download_compliance_file().                    *
 * Returns true when a compliance_files row of the given ref_type must NOT be   *
 * streamed to the current caller. Three independent reasons to deny:           *
 *                                                                              *
 *  1. MODULE. The caller does not hold the module permission that owns the     *
 *     ref_type (compliance_file_owning_module_permission()). This is what      *
 *     stops a file being pulled through the OTHER module's download page.      *
 *     An unmapped ref_type has no known owner and is denied — fail closed, so  *
 *     a future fourth ref_type cannot stream before someone maps it.           *
 *  2. EXCEPTION-GRANULAR. The ref_type additionally requires an exception      *
 *     permission (compliance_file_required_exception_permission()) that the    *
 *     caller lacks. Exception attachments require view_exception, mirroring    *
 *     the exception display API.                                              *
 *  3. DOCUMENTATION-GRANULAR (completes SR-1694 for `documents`, see           *
 *     compliance_file_required_documentation_permission()). Governance         *
 *     documents require view_documentation at this sink — checked via the      *
 *     same generic $module_permission_checker as the module gate               *
 *     (view_documentation is a plain check_permission() key, not an            *
 *     exception-module permission, so it does not go through the exception     *
 *     checker). This sink is currently the only runtime enforcement point for  *
 *     view_documentation; the documents display endpoints still gate on the    *
 *     coarser `governance` permission only. test_audit still has no granular   *
 *     permission at this sink; the module gate is its whole model.             *
 *                                                                              *
 * Both permission checks are injected as callables so the whole deny decision  *
 * — the mappings AND that the correct permission is the one checked — is       *
 * unit-testable without a session; download_compliance_file() passes the real  *
 * check_permission_exception and check_permission. Keeps the header()/exit()   *
 * sink a thin wrapper over verifiable logic.                                    *
 *                                                                              *
 * Same shape as the other fail-closed download gates:                          *
 * close_risks_by_test_result_denied() below, and                               *
 * questionnaire_file_download_denied() in the Assessments Extra. See the Test  *
 * Coverage section of CLAUDE.md for when to inject a checker rather than set   *
 * $_SESSION.                                                                   *
 *******************************************************************************/
function compliance_file_download_denied($ref_type, callable $exception_permission_checker, callable $module_permission_checker) {
    // The owning module is the first gate. An unmapped ref_type has no
    // known owner, so it is denied outright rather than streamed.
    $module_permission = compliance_file_owning_module_permission($ref_type);
    if ($module_permission === null || !$module_permission_checker($module_permission)) {
        return true;
    }

    $required_exception_permission = compliance_file_required_exception_permission($ref_type);
    if ($required_exception_permission !== null && !$exception_permission_checker($required_exception_permission)) {
        return true;
    }

    $required_documentation_permission = compliance_file_required_documentation_permission($ref_type);
    return $required_documentation_permission !== null && !$module_permission_checker($required_documentation_permission);
}

/*******************************************************************************
 * FUNCTION: COMPLIANCE FILE DOWNLOAD DENIED FOR DOWNLOAD                       *
 * Combines the admin bypass with compliance_file_download_denied()'s granular  *
 * decision -- the exact `!is_admin() && compliance_file_download_denied(...)`  *
 * shape governance/documentation.php's bulk-download branch inlines at its own *
 * call site; download_compliance_file() (includes/compliance.php) calls this   *
 * wrapper instead. Admin bypasses the granular checks the same way is_admin()  *
 * bypasses them for the Document Program row actions (documentation.php's      *
 * $can_edit/$can_delete/$can_approve/$can_view) -- an admin who wasn't          *
 * individually granted these permissions must still be able to download what   *
 * the UI now lets them see.                                                    *
 *                                                                              *
 * is_admin is injected as a callable, same reason the granular permission      *
 * checkers are: the admin-bypass interaction is unit-testable without a        *
 * session. compliance_file_download_denied() itself stays session-free and     *
 * bypass-free per its own docblock; this wrapper is where the two combine.     *
 *******************************************************************************/
function compliance_file_download_denied_for_download($ref_type, callable $is_admin_checker, callable $exception_permission_checker, callable $module_permission_checker) {
    return !$is_admin_checker() && compliance_file_download_denied($ref_type, $exception_permission_checker, $module_permission_checker);
}

/*******************************************************************************
 * FUNCTION: CLOSE RISKS BY TEST RESULT DENIED                                  *
 * The deny decision enforced at close_risks_by_test_result_id(). The           *
 * compliance test-result submission flow closes every risk linked to a test    *
 * result when the request carries remove_associated_risk=1. That flag is a     *
 * client input, and the only gate on the submission itself is modify_audits —  *
 * so without this check a compliance tester holding modify_audits but          *
 * deliberately NOT close_risks could close risks by sending the field the UI   *
 * never offers them. Separating "may record a test result" from "may close a   *
 * risk" is exactly what close_risks exists to do.                              *
 *                                                                              *
 * The permission check is injected as a callable so the decision — and that    *
 * close_risks specifically is the permission checked — is unit-testable        *
 * without a session; the callers pass the real check_permission.               *
 *                                                                              *
 * Same shape as the other fail-closed download gates:                          *
 * compliance_file_download_denied() above, and                                 *
 * questionnaire_file_download_denied() in the Assessments Extra. See the Test  *
 * Coverage section of CLAUDE.md for when to inject a checker rather than set   *
 * $_SESSION.                                                                   *
 *******************************************************************************/
function close_risks_by_test_result_denied(callable $permission_checker) {
    return !$permission_checker('close_risks');
}

/**
 * Pure decision helper for delete_project_api() (includes/api.php): true only
 * if $is_accessible returns true for every risk in $risks, false on the first
 * miss. Extracted so the check-before-mutate ordering guarantee is
 * unit-testable without going through the exit()-driven json_response() sink,
 * and independent of the order get_project_risks() (no ORDER BY) happens to
 * return rows in.
 */
function all_project_risks_accessible(array $risks, callable $is_accessible): bool
{
    foreach ($risks as $risk)
    {
        if (!$is_accessible($risk))
        {
            return false;
        }
    }
    return true;
}

/**
 * Pure decision helper for delete_project_api() (includes/api.php): unassigns
 * every risk in $risks via $unassign_risk (an injected callable), stopping
 * and returning false on the first failure rather than continuing to the
 * rest. Extracted so the stop-immediately ordering guarantee is
 * unit-testable without a real DB connection or a live HTTP request; the
 * caller decides what "stop" means (rolling back the surrounding
 * transaction).
 */
function unassign_all_project_risks(array $risks, callable $unassign_risk): bool
{
    foreach ($risks as $risk)
    {
        if (!$unassign_risk($risk))
        {
            return false;
        }
    }
    return true;
}

/*******************************************
 * FUNCTION: GET TAGS OF TYPE              *
 * Gets tags assigned to a type of taggee. *
 * Type can be either `risk` or `asset`.   *
 *******************************************/
function getTagsOfType($type) {

    global $tag_types;

    if (!in_array($type, $tag_types))
        return [];

    $db = db_open();

    //Load tags currently assigned to a type of taggee
    $stmt = $db->prepare("
        SELECT
            `t`.`tag`, t.id
        FROM
            `tags` t
            INNER JOIN `tags_taggees` tt ON `tt`.`tag_id` = `t`.`id`
        WHERE
            `tt`.`type` = :type
        GROUP BY 
            t.id
        ORDER BY `t`.`tag` ASC;
    ");
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();
    $tags = $stmt->fetchAll(PDO::FETCH_ASSOC);

    db_close($db);

    return $tags;
}

/************************************************
 * FUNCTION: GET TAGS OF TYPES                  *
 * Gets tags assigned to list of taggee types.  *
 ************************************************/
function getTagsOfTypes($types = []) {
    
    global $tag_types;
    
    // Making sure we only accept the types we can work with
    $types = array_intersect($types, $tag_types);
    
    // If there's no type left
    if (empty($types)) {
        return [];
    }
        
    $db = db_open();
    
    //Load tags currently assigned to a type of taggee
    // usage_count is how many taggees of these types carry the tag. Returned
    // as an extra column rather than as a new sort order, so existing callers
    // keep the alphabetical list they expect while a caller that wants to
    // surface the most-reused tags first (the test tag picker) can sort on it.
    $stmt = $db->prepare("
        SELECT
            `t`.`tag`, t.id, COUNT(`tt`.`tag_id`) AS usage_count
        FROM
            `tags` t
            INNER JOIN `tags_taggees` tt ON `tt`.`tag_id` = `t`.`id`
        WHERE
            `tt`.`type` in ('" . implode("','", $types) . "')
        GROUP BY
            t.id
        ORDER BY `t`.`tag` ASC;
    ");
    
    $stmt->execute();
    $tags = $stmt->fetchAll(PDO::FETCH_ASSOC);
    
    db_close($db);
    
    return $tags;
}

/*********************************************
 * FUNCTION: ARE TAGS EQUAL                  *
 * Gets tags assigned to a type of taggee    *
 * and compares them to the $tags parameter. *
 * Type can be either `risk` or `asset`.     *
 *********************************************/
function areTagsEqual($taggee_id, $type, $tags) {

    global $tag_types;

    if (!$taggee_id || !in_array($type, $tag_types) || !is_array($tags))
        return false;

    $db = db_open();

    //Load tags currently assigned to the taggee
    $stmt = $db->prepare("
        SELECT
            `t`.`tag`
        FROM
            `tags` t
            INNER JOIN `tags_taggees` tt ON `tt`.`tag_id` = `t`.`id`
        WHERE
            `tt`.`taggee_id` = :taggee_id and `tt`.`type` = :type;
    ");
    $stmt->bindParam(":taggee_id", $taggee_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();
    $result = $stmt->fetchAll();

    $tags_current = array_column($result, 'tag');

    db_close($db);
    $tags = array_filter($tags, function($value) { return !is_null($value) && $value !== ''; });
    return array_diff($tags_current, $tags) == array_diff($tags, $tags_current);
}

/*********************************
 * FUNCTION: REMOVE TAGS OF TYPE *
 *********************************/
function removeTagsOfTaggee($taggee_id, $type) {

    global $tag_types;

    if (!$taggee_id
        || !in_array($type, $tag_types)
        || !hasTags($taggee_id, $type))
        return;

    $db = db_open();

    // Remove the entries from the junction table that connected to the taggee
    $stmt = $db->prepare("
        delete
            `tt`
        from
            `tags` t
            inner join `tags_taggees` tt on `tt`.`tag_id` = `t`.`id`
        where
            `tt`.`taggee_id` = :taggee_id and
            `tt`.`type` = :type;
    ");
    $stmt->bindParam(":taggee_id", $taggee_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();


    // Clean up every tags that aren't referenced by the junction table
    $stmt = $db->prepare("
        delete
            `t`
        from
            `tags` `t`
            left join `tags_taggees` `tt` on `tt`.`tag_id` = `t`.`id`
        where
            `tt`.`taggee_id` is null;
    ");
    $stmt->execute();

    db_close($db);
}

/*******************************
 * FUNCTION: UPDATE RISK LEVEL *
 *******************************/
function update_risk_level($field, $value, $name) {
    $db = db_open();

    // Update the risk level
    $stmt = $db->prepare("UPDATE `risk_levels` SET {$field}=:{$field} WHERE name=:name");
    $stmt->bindParam(":{$field}", $value, PDO::PARAM_STR);
    $stmt->bindParam(":name", $name, PDO::PARAM_STR);

    $stmt->execute();

    // Close the database connection
    db_close($db);
}

/*********************************
 * FUNCTION: CSRF STARTUP         *
 * Hook called by csrf_init()    *
 * before the token check runs.  *
 *********************************/
// @phan-suppress-next-line PhanRedefineFunction -- alternate definition in vendor csrf-magic js-test fixture is not loaded in production
function csrf_startup() {
    // HTTP header names are case-insensitive (RFC 7230) but PHP-FPM/nginx reconstructs
    // them from HTTP_* server vars with title-case, so 'CSRF-TOKEN' becomes 'Csrf-Token'.
    // Normalise to uppercase before csrf_check() does its exact-case lookup.
    $headers = array_change_key_case(apache_request_headers(), CASE_UPPER);
    $name = $GLOBALS['csrf']['input-name'];
    if (!empty($headers['CSRF-TOKEN']) && !isset($_POST[$name])) {
        $_POST[$name] = $headers['CSRF-TOKEN'];
    }
}

/**
 * Determine whether a request targets the API, based on the URL path.
 *
 * Matches on the path component only — the full REQUEST_URI includes the query
 * string, and matching that would misclassify a normal HTML page reached with
 * "/api/" somewhere in its query parameters. Used by include_csrf_magic() to
 * decide whether to disable csrf-magic's output rewriting (which corrupts JSON
 * API responses that contain stored HTML).
 *
 * Pure: depends only on its argument — no DB, I/O, or session access.
 *
 * @param string|null $request_uri Typically $_SERVER['REQUEST_URI'].
 * @return bool True if the request path contains the "/api/" segment.
 */
function request_path_is_api($request_uri) {
    if (!is_string($request_uri) || $request_uri === '') {
        return false;
    }

    $path = parse_url($request_uri, PHP_URL_PATH);

    return is_string($path) && strpos($path, '/api/') !== false;
}

/****************************************
 * FUNCTION: CSRF RESOLVE AND PERSIST   *
 *           SECRET                     *
 ****************************************/
/**
 * Resolve a stable CSRF secret, persisting one in the database.
 *
 * Precedence: (1) a non-empty `csrf_secret` setting in the DB (the HA-friendly
 * source of truth); (2) the legacy on-disk csrf-magic secret file, migrated in;
 * (3) a freshly generated secret. Whenever the value did not already come from
 * a non-empty DB row, it is persisted with a raw REPLACE (an UPSERT).
 *
 * The UPSERT is the fix for a self-perpetuating CSRF outage: add_setting() is
 * INSERT IGNORE, so if a `csrf_secret` row already existed but was EMPTY (and
 * the legacy file was gone — e.g. an upgrade wiped the vendor directory), every
 * request generated a fresh random secret that never persisted, and every token
 * minted on one request failed validation on the next. The REPLACE overwrites
 * the empty/stale row, so the instance converges on one stable secret after the
 * first request.
 *
 * The persist is a raw REPLACE rather than update_or_insert_setting() on purpose:
 * that helper writes the value into the debug log, and the CSRF secret must never
 * reach the logs.
 *
 * Side effects are limited to the single settings REPLACE, so the
 * resolution/persistence behaviour is testable without driving csrf-magic's
 * global init (see CsrfSecretPersistenceTest).
 *
 * @return string A non-empty CSRF secret.
 */
function csrf_resolve_and_persist_secret(): string {

    // A non-empty DB value is authoritative — use it as-is, nothing to persist.
    $secret = get_setting('csrf_secret');
    if ($secret !== false && $secret !== '') {
        return $secret;
    }

    // Migrate from the legacy on-disk file if it exists.
    $legacy_file = realpath(__DIR__ . '/../vendor/simplerisk/csrf-magic/csrf-secret.php');
    if ($legacy_file !== false && file_exists($legacy_file)) {
        $secret = '';
        include $legacy_file;
    }

    // Generate a cryptographically secure secret if we still don't have one.
    if (!is_string($secret) || $secret === '') {
        $secret = bin2hex(random_bytes(32));
    }

    // Persist with a raw REPLACE (an UPSERT) rather than add_setting()'s INSERT
    // IGNORE — that could not overwrite an existing empty/stale row, so the
    // secret never persisted and every request minted a fresh random one. A raw
    // REPLACE is also deliberately used instead of update_or_insert_setting()
    // because that helper writes the value into the debug log, and the CSRF
    // secret must never reach the logs.
    $db = db_open();
    $stmt = $db->prepare("REPLACE INTO settings (`name`, `value`) VALUES ('csrf_secret', :value)");
    $stmt->bindParam(":value", $secret, PDO::PARAM_STR);
    $stmt->execute();
    db_close($db);

    // Keep get_setting()'s in-memory cache coherent for the rest of the request.
    $GLOBALS['setting_csrf_secret'] = $secret;

    return $secret;
}

/**********************************
 * FUNCTION: INCLUDE CSRF MAGIC  *
 * Make sure to call this after  *
 * the session is properly setup *
 *********************************/
function include_csrf_magic() {

    global $escaper;

    // Resolve a stable CSRF secret (DB-preferred, with legacy-file migration and
    // a persisted fallback) before validation. See csrf_resolve_and_persist_secret().
    $secret = csrf_resolve_and_persist_secret();

    csrf_conf('secret', $secret);
    csrf_conf('rewrite-js', $escaper->escapeHtml(build_url('/vendor/simplerisk/csrf-magic/csrf-magic.js')));

    // csrf_ob_handler() in vendor/simplerisk/csrf-magic decides whether to
    // rewrite the response by scanning the raw buffer for "<html". JSON API
    // responses that include stored HTML (e.g. queue items containing email
    // bodies) trip that check and the handler appends a closing <script> tag,
    // producing invalid JSON that breaks DataTables and any other JSON client.
    // API callers don't need server-side <form> rewriting — disable it here.
    // request_path_is_api() matches on the request path only (not the query
    // string), so an HTML page reached with "/api/" in its query parameters
    // keeps its rewriting.
    if (request_path_is_api($_SERVER['REQUEST_URI'] ?? null)) {
        csrf_conf('rewrite', false);
    }

    csrf_init();
}

function startsWith($haystack, $needle) {
    $length = strlen($needle);
    return (substr($haystack, 0, $length) === $needle);
}

function endsWith($haystack, $needle) {
    $length = strlen($needle);
    if ($length == 0) {
        return true;
    }

    return (substr($haystack, -$length) === $needle);
}

/*********************************
 * FUNCTION: GET SETTING BY NAME *
 *********************************/
function get_setting_by_name($name)
{
    return get_setting($name);
}

/**********************************
 * FUNCTION: GET SETTTING BY NAME *
 **********************************/
function get_settting_by_name($name)
{
    return get_setting($name);
}

/********************************************
 * FUNCTION: CHECK IF THIS IS BASE64 STRING *
 ********************************************/
function check_base64_string($string)
{
    if(trim(base64_encode(base64_decode($string)), "=") == trim($string, "="))
    {
        return true;
    }
    else
    {
        return false;
    }
}

/********************************************
 * FUNCTION: RETURN ALL CHILDS BY PARENT ID *
 ********************************************/
function get_all_childs($rows, $parent_id, &$childs=[], $id_key="id")
{
    foreach($rows as $row)
    {
        if($row['parent'] == $parent_id)
        {
            array_push($childs, $row);
            get_all_childs($rows, $row[$id_key], $childs, $id_key);
        }
    }
}

/****************************************************
 * FUNCTION: GET TEAMS OF ITEM                      *
 * Return the teams assigned to the item.           *
 * If $names is true it returns the values and the  *
 * names, otherwise it'll only return the values    *
 ****************************************************/
function getTeamsOfItem($item_id, $type, $names=false) {

    global $available_item_types;

    if (!$item_id || !in_array($type, $available_item_types))
        return [];

    $db = db_open();

    $sql = "
        SELECT
            `t`." . ($names ? "*" : "`value`") . "
        FROM
            `team` t
            INNER JOIN `items_to_teams` itt ON `itt`.`team_id` = `t`.`value` and `itt`.`type` = :type
        WHERE
            `itt`.`item_id` = :item_id;
    ";

    $stmt = $db->prepare($sql);
    $stmt->bindParam(":item_id", $item_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();

    if ($names)
        $result = $stmt->fetchAll(PDO::FETCH_ASSOC);
    else
        $result = $stmt->fetchAll(PDO::FETCH_COLUMN, 0);
    
    db_close($db);

    return $result;
}

/****************************************************
 * FUNCTION: GET ITEMS OF TEAM                      *
 * Return the items assigned to the team.           *
 * If $full is true it returns every fields of the  *
 * item, otherwise it'll only return the ids        *
 ****************************************************/
function getItemsOfTeam($team_id, $type, $full=false) {

    global $available_item_types;

    if (!$team_id || !in_array($type, $available_item_types))
        return [];

    $db = db_open();

    $item_table_name = '';
    $item_id_field_name = '';
    $teams_query = '';

    switch($type) {
        case 'audit':
            $item_table_name = 'framework_control_test_audits';
            $item_id_field_name = 'id';
            $teams_query = "SELECT GROUP_CONCAT(DISTINCT `team_id`) FROM `items_to_teams` WHERE `type` = :type AND `item_id` = `item`.`{$item_id_field_name}`";
            break;
        case 'test':
            $item_table_name = 'framework_control_tests';
            $item_id_field_name = 'id';
            $teams_query = "SELECT GROUP_CONCAT(DISTINCT `team_id`) FROM `items_to_teams` WHERE `type` = :type AND `item_id` = `item`.`{$item_id_field_name}`";
            break;
    }

    // Assemble the query
    $sql = "
        SELECT
            `item`." .
            ($full ?  "*, ({$teams_query}) as teams" : "`{$item_id_field_name}`") . "
        FROM
            `{$item_table_name}` item
            INNER JOIN `items_to_teams` i2t ON `i2t`.`item_id` = `item`.`{$item_id_field_name}` and `i2t`.`type` = :type
        WHERE
            `i2t`.`team_id` = :team_id;
    ";

    //Load items currently assigned to the team
    $stmt = $db->prepare($sql);
    $stmt->bindParam(":team_id", $team_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();

    if ($full)
        $result = $stmt->fetchAll(PDO::FETCH_ASSOC);
    else
        $result = $stmt->fetchAll(PDO::FETCH_COLUMN, 0);

    db_close($db);

    return $result;
}

/*************************************************
 * FUNCTION: HAS TEAMS                           *
 * Checks if there're teams assigned to the item *
 *************************************************/
function hasTeams($item_id, $type) {

    global $available_item_types;

    if (!$item_id || !in_array($type, $available_item_types))
        return false;

    $db = db_open();

    $stmt = $db->prepare("
        SELECT
            distinct(5)
        FROM
            `items_to_teams` itt
        WHERE
            `itt`.`item_id` = :item_id and `itt`.`type` = :type;
    ");
    $stmt->bindParam(":item_id", $item_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();
    $result = $stmt->fetch();

    db_close($db);

    return !empty($result);
}

/*************************************************
 * FUNCTION: HAS ITEMS                           *
 * Checks if there're items assigned to the team *
 *************************************************/
function hasItems($team_id, $type) {

    global $available_item_types;

    if (!$team_id || !in_array($type, $available_item_types))
        return false;

    $db = db_open();

    $stmt = $db->prepare("
        SELECT
            distinct(5)
        FROM
            `items_to_teams` itt
        WHERE
            `itt`.`team_id` = :team_id and `itt`.`type` = :type;
    ");
    $stmt->bindParam(":team_id", $team_id, PDO::PARAM_STR);
    $stmt->bindParam(":type", $type, PDO::PARAM_STR);
    $stmt->execute();
    $result = $stmt->fetch();

    db_close($db);

    return !empty($result);
}

/********************************************************************
 * FUNCTION: UPDATE TEAMS OF ITEM                                   *
 * Gets an item id and a type to decide what the item is assigned   *
 * to and updates its teams. Available type values are listed in    *
 * the $available_item_types global variable.                       *
 * Third parameter is an array of team ids. If the array is         *
 * empty, all the teams will be removed from the item.              *
 ********************************************************************/
function updateTeamsOfItem($item_id, $type, $teams, $audit_log=true) {

    global $available_item_types;

    if (!$item_id || !in_array($type, $available_item_types) || !is_array($teams))
        return false;

    $teams_current = getTeamsOfItem($item_id, $type);

    $db = db_open();

    // Clever usage of array_diffs to calculate what teams are removed from the item
    // and what teams are added
    $teams_to_remove = array_diff($teams_current, $teams);
    $teams_to_add = array_diff($teams, $teams_current);

    // If there're teams to remove
    if ($teams_to_remove) {

        //building an array of parameters to bind
        $params = array(":item_id" => $item_id, ":type" => $type);

        // building the list of strings to be used in the `in` part of the sql
        // to be able to bind the params
        // We need this to be able to delete all the connections to the removed
        // teams in one go, instead of using a loop
        $teams_to_remove_in = [];
        foreach ($teams_to_remove as $i => $team) {
            $key = ":id".$i;
            $teams_to_remove_in[] = $key;
            $params[$key] = $team;
        }

        // making the comma separated list to be included in the sql
        $teams_to_remove_in = implode(", ", $teams_to_remove_in);

        // Remove the entries from the junction table that connected the teams to the item
        $stmt = $db->prepare("
            DELETE
                `itt`
            FROM
                `team` t
                INNER JOIN `items_to_teams` itt ON
                    `itt`.`team_id` = `t`.`value` AND
                    `itt`.`item_id` = :item_id AND
                    `itt`.`type` = :type
            WHERE
                `t`.`value` in ({$teams_to_remove_in});
        ");
        $stmt->execute($params);
    }

    //If there're teams to add
    if ($teams_to_add) {
        //Sadly we can't do this in a single sql so we have to resort to looping
        foreach ($teams_to_add as $team_id) {
            if(!$team_id) continue;

            // We just use the id to create
            // the connection between the item and the team in the junction table
            $stmt = $db->prepare("
                INSERT INTO
                    `items_to_teams` (`team_id`, `item_id`, `type`)
                VALUES
                    (:team_id, :item_id, :type);
            ");
            $stmt->bindParam(":team_id", $team_id, PDO::PARAM_STR);
            $stmt->bindParam(":item_id", $item_id, PDO::PARAM_STR);
            $stmt->bindParam(":type", $type, PDO::PARAM_STR);
            $stmt->execute();
        }
    }

    db_close($db);

    // No audit logging is needed if nothing changed
    if ($audit_log && ($teams_to_add || $teams_to_remove)) {
        global $lang;

        $team_changes = [];
        if ($teams_to_add)
            $team_changes[] = _lang_raw('TeamUpdateAuditLogAdded', array('teams_added' => implode(", ", get_names_by_multi_values('team', $teams_to_add, true))));
        if ($teams_to_remove)
            $team_changes[] = _lang_raw('TeamUpdateAuditLogRemoved', array('teams_removed' => implode(", ", get_names_by_multi_values('team', $teams_to_remove, true))));

        $message = _lang_raw('TeamUpdateAuditLog', array(
                'user' => $_SESSION['user'],
                'type' => $lang['TeamType_' . $type],
                'id' => $item_id,
                'teams_from' => implode(", ", get_names_by_multi_values('team', $teams_current, true)),
                'teams_to' => implode(", ", get_names_by_multi_values('team', $teams, true)),
                'team_changes' => implode(", ", $team_changes)
            ));

        // In case it has to be something different than the $type
        switch($type) {
            case "audit":
                $audit_type = 'test_audit';
                break;
            default:
                $audit_type = $type;
                break;
        }

        write_log((int)$item_id + 1000, $_SESSION['uid'] ?? 0, $message, $audit_type);
    }

    return true;
}

/********************************************************************
 * FUNCTION: UPDATE ITEMS OF TEAM                                   *
 * Gets a team id and a type to decide what the team is assigned to *
 * and updates its items. Available type values are listed in       *
 * the $available_item_types global variable.                       *
 * Third parameter is an array of item ids. If the array is         *
 * empty, all the items will be removed from the team.              *
 ********************************************************************/
function updateItemsOfTeam($team_id, $type, $items) {

    global $available_item_types;

    if (!$team_id || !in_array($type, $available_item_types) || !is_array($items))
        return false;

    $items_current = getItemsOfTeam($team_id, $type);

    $db = db_open();

    // Clever usage of array_diffs to calculate what items are removed from the team
    // and what items are added
    $items_to_remove = array_diff($items_current, $items);
    $items_to_add = array_diff($items, $items_current);

    // If there're teams to remove
    if ($items_to_remove) {

        //building an array of parameters to bind
        $params = array(":team_id" => $team_id, ":type" => $type);

        // building the list of strings to be used in the `in` part of the sql
        // to be able to bind the params
        // We need this to be able to delete all the connections to the removed
        // items in one go, instead of using a loop
        $items_to_remove_in = [];
        foreach ($items_to_remove as $i => $item) {
            $key = ":id".$i;
            $items_to_remove_in[] = $key;
            $params[$key] = $item;
        }

        // making the comma separated list to be included in the sql
        $items_to_remove_in = implode(", ", $items_to_remove_in);

        // Remove the entries from the junction table that connected the teams to the item
        $stmt = $db->prepare("
            DELETE FROM
                `items_to_teams`
            WHERE
                `team_id` = :team_id AND
                `type` = :type AND
                `item_id` = in ({$items_to_remove_in});
        ");
        $stmt->execute($params);
    }

    //If there're teams to add
    if ($items_to_add) {

        $params = array(":team_id" => $team_id, ":type" => $type);
        $items_to_add_values = [];

        //Sadly we can't do this in a single sql so we have to resort to looping
        foreach ($items_to_add as $i => $item_id) {
            $key = ":item_id".$i;
            $params[$key] = $item_id;
            $items_to_add_values[] = "(:team_id, {$key}, :type)";
        }
        
        $items_to_add_values = implode(", ", $items_to_add_values);
        // We just use the id to create
        // the connection between the item and the team in the junction table
        $stmt = $db->prepare("
            INSERT INTO
                `items_to_teams` (`team_id`, `item_id`, `type`)
            VALUES
                {$items_to_add_values};
        ");
        $stmt->execute($params);
    }

    db_close($db);

    // No audit logging is needed if nothing changed
    if ($items_to_add || $items_to_remove) {
        global $lang;

        //$db = db_open();

        $audit_type = '';
        $item_table_name = '';
        $use_id = true;

        switch($type) {
            case 'audit':
                $audit_type = 'test_audit';
                $item_table_name = 'framework_control_test_audits';
                $use_id = true;
                break;
            case 'test':
                $audit_type = 'test';
                $item_table_name = 'framework_control_tests';
                $use_id = true;
                break;
        }

        $item_changes = [];
        if ($items_to_add)
            $item_changes[] = _lang_raw('ItemUpdateAuditLogAdded', array('items_added' => implode(", ", get_names_by_multi_values($item_table_name, $items_to_add, true, '', $use_id))));
        if ($items_to_remove)
            $item_changes[] = _lang_raw('ItemUpdateAuditLogRemoved', array('items_removed' => implode(", ", get_names_by_multi_values($item_table_name, $items_to_remove, true, '', $use_id))));

        $message = _lang_raw('ItemUpdateAuditLog', array(
                'user' => $_SESSION['user'],
                'type' => $lang['TeamType_' . $type],
                'team' => get_name_by_value('team', $team_id),
                'items_from' => implode(", ", get_names_by_multi_values($item_table_name, $items_current, true, '', $use_id)),
                'items_to' => implode(", ", get_names_by_multi_values($item_table_name, $items, true, '', $use_id)),
                'item_changes' => implode(", ", $item_changes)
            ));

        // updateItemsOfTeam operates on a list of items, so we log against the team-level event with a 0 ref ID
        write_log(1000, $_SESSION['uid'] ?? 0, $message, $audit_type);
    }

    return true;
}

function is_valid_impact_and_likelihood($impact, $likelihood) {
    
    $db = db_open();

    $stmt = $db->prepare("
        SELECT
            1
        FROM
            dual
        WHERE
            :impact BETWEEN 1 AND (SELECT MAX(`value`) FROM `impact`)
            AND
            :likelihood BETWEEN 1 AND (SELECT MAX(`value`) FROM `likelihood`);
    ");
    $stmt->bindParam(":impact", $impact, PDO::PARAM_INT);
    $stmt->bindParam(":likelihood", $likelihood, PDO::PARAM_INT);
    $stmt->execute();
    
    $result = $stmt->fetch(PDO::FETCH_COLUMN, 0);
    
    db_close($db);
    
    return boolval($result);
}

function set_stored_risk_score($impact, $likelihood, $value, $update_risks = false) {

    $db = db_open();

    $stmt = $db->prepare("
        INSERT INTO
            `custom_risk_model_values`
                (`impact`, `likelihood`, `value`)
        VALUES
            (:impact, :likelihood, :value)
        ON DUPLICATE KEY UPDATE
            value=:value;
    ");
    $stmt->bindParam(":impact", $impact, PDO::PARAM_INT);
    $stmt->bindParam(":likelihood", $likelihood, PDO::PARAM_INT);
    $stmt->bindParam(":value", $value, PDO::PARAM_STR);
    $stmt->execute();
    
    if ($update_risks) {
        // Get the list of all risks using the classic formula
        $stmt = $db->prepare("
            SELECT
                id
            FROM
                risk_scoring
            WHERE
                scoring_method = 1
                AND calculated_risk <> :value
                AND CLASSIC_impact = :impact
                AND CLASSIC_likelihood = :likelihood;
        ");
        $stmt->bindParam(":value", $value, PDO::PARAM_STR);
        $stmt->bindParam(":impact", $impact, PDO::PARAM_INT);
        $stmt->bindParam(":likelihood", $likelihood, PDO::PARAM_INT);
        $stmt->execute();

        // Store the list in the risk_ids array
        $risk_ids = $stmt->fetchAll(PDO::FETCH_COLUMN, 0);

        // For each risk using the classic formula
        foreach ($risk_ids as $risk_id)
        {
            // Update the value in the DB
            $stmt = $db->prepare("UPDATE risk_scoring SET calculated_risk = :calculated_risk WHERE id = :id");
            $stmt->bindParam(":calculated_risk", $value, PDO::PARAM_STR);
            $stmt->bindParam(":id", $risk_id, PDO::PARAM_INT);
            $stmt->execute();

            // Add risk scoring history
            add_risk_scoring_history($risk_id, $value);

            // Add residual risk scoring history
            $residual_risk = get_residual_risk($risk_id+1000);
            add_residual_risk_scoring_history($risk_id, $residual_risk);
        }
    }
    db_close($db);
}

function get_stored_risk_score($impact, $likelihood) {

    $db = db_open();

    $stmt = $db->prepare("
        SELECT
            `value`
        FROM
            `custom_risk_model_values`
        WHERE
            `impact` = :impact AND
            `likelihood` = :likelihood;
    ");
    $stmt->bindParam(":impact", $impact, PDO::PARAM_INT);
    $stmt->bindParam(":likelihood", $likelihood, PDO::PARAM_INT);
    $stmt->execute();

    $result = $stmt->fetch(PDO::FETCH_COLUMN, 0);

    db_close($db);

    return $result ? $result : 0;
}

/******************************************
 * FUNCTION: GET DYNAMIC SAVED SELECTIONS *
 ******************************************/
function get_dynamic_saved_selections($user_id)
{
    // Open the database connection
    $db = db_open();

    // If the requesting user is an admin then return all the saved selections
    // When returning other users' saved selections add the users' name to the saved selections' names
    // Results are ordered to have the user's own saved selections first,
    // then they're ordered to display private saved selections first then the publics 
    $stmt = $db->prepare("
        SELECT
        	`dss`.`value`,
            IF(`u`.`value` <> :user_id, CONCAT(`dss`.`name`, ' (', `u`.`name`, ')'), `dss`.`name`) as name,
            `dss`.`type`,
            `dss`.`user_id`,
            `dss`.`custom_display_settings`,
            `dss`.`custom_selection_settings`,
            `dss`.`custom_column_filters`
        FROM
        	`dynamic_saved_selections` dss
            INNER JOIN `user` u ON `u`.`value` = `dss`.`user_id`
        WHERE
        	`dss`.`type`='public'
            OR (`dss`.`type` = 'private' AND `dss`.`user_id` = :user_id)
            OR (SELECT `admin` FROM `user` WHERE `value` = :user_id) = 1
        ORDER BY
            `dss`.`user_id` <> :user_id, `dss`.`type` = 'public';
    ");
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->execute();

    // Get dynamic saved selections
    $array = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Close the database connection
    db_close($db);

    return $array;
}

/**************************************************
 * FUNCTION: GET DYNAMIC SAVED SELECTION BY VALUE *
 **************************************************/
function get_dynamic_saved_selection($value)
{
    // Open the database connection
    $db = db_open();

    $stmt = $db->prepare("SELECT user_id, name, type, custom_display_settings, custom_selection_settings, custom_column_filters FROM `dynamic_saved_selections` WHERE `value`=:value;");
    $stmt->bindParam(":value", $value, PDO::PARAM_INT);
    $stmt->execute();

    // Get dynamic saved selections
    $row = $stmt->fetch(PDO::FETCH_ASSOC);
    
    // Close the database connection
    db_close($db);

    return $row;
}

/********************************************************************************
 * FUNCTION: TRUNCATE TO (LENGTH)                                               *
 * Truncates $string to be $length long(including the ... appended to the end)  *
 ********************************************************************************/
function truncate_to($string, $length, $append='...') {
    return mb_strimwidth($string, 0, $length, $append);
}

/*************************************
 * FUNCTION: CHECK CLOSED RISK BY ID *
 *************************************/
function check_closed_risk_by_id($id)
{
    // Subtract 1000 from the id
    $id = (int)$id - 1000;

    // Open the database connection
    $db = db_open();

    // Query the database
    $stmt = $db->prepare("
    SELECT
        *
    FROM
        `risks`
    WHERE
        `id` = :id AND `status` = 'Closed';
    ");

    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->execute();

    // Store the list in the array
    $result = $stmt->fetch(PDO::FETCH_ASSOC);

    // Close the database connection
    db_close($db);
    
    if($result){
        return true;
    }else{
        return false;
    }
}

/*
    Checking if the extra is already installed
*/
function is_extra_installed($extra) {
    global $available_extras;

    if (!in_array($extra, $available_extras))
        return false;

    return file_exists(realpath(__DIR__ . "/../extras/$extra/index.php"));
}

/*************************************************
 * FUNCTION: CHECK IF THIS APP IS LATEST VERSION *
 *************************************************/
/**
 * True when the application files and the database schema are both on the
 * newest published release.
 *
 * Core has no caller of its own — the Core-version gate on Extra downloads goes
 * through extra_install_core_version_refusal() in services.php, which needs the
 * Extra's name for the Upgrade Extra carve-out. This is kept because published
 * Upgrade Extras call it, and an Extra always runs against a Core that may be
 * older or newer than itself: deleting it would fatal an existing customer's
 * Extra on their next upgrade.
 *
 * It used to call next_version(), which is defined ONLY in
 * simplerisk/extras/upgrade/index.php. Core never defines it, so this function
 * was a "Call to undefined function" from any context that had not already
 * loaded the Upgrade Extra — which is why its one former caller had to
 * file_exists()-and-require the Extra before it could ask the question, and why
 * the check silently did not apply on instances without that Extra. It now uses
 * Core's own latest_version(), so it works everywhere and needs no Extra.
 *
 * next_version() is deliberately NOT reimplemented here: the Extra defines it
 * unguarded, so a Core definition would be a fatal redeclare for every customer
 * whose installed Extra predates a guard.
 */
function check_app_latest_version()
{
    require_once(realpath(__DIR__ . '/licensing.php'));

    $latest = latest_version('app', false);

    // Reuse the single decision helper rather than restating the comparison.
    // The empty name opts out of the Upgrade Extra carve-out, which is correct
    // here: this function answers "is Core current", not "may this Extra be
    // installed".
    return !extra_install_blocked_by_core_version(
        '',
        (string)current_version('app'),
        (string)current_version('db'),
        is_string($latest) ? $latest : ''
    );
}

/*******************************************************************************
 * FUNCTION: SET PROXY STREAM CONTEXT                                          *
 * This function takes the proxy settings from the Security tab in Settings    *
 * and sets the default stream context to use them before making a web request *
 *******************************************************************************/
function set_proxy_stream_context($method=null, $header=null, $content=null, $ssl_verify_off=false, $timeout=null)
{
    // Get the proxy_web_requests value
    $proxy_web_requests = get_setting("proxy_web_requests");

    // If proxy web requests is set
    if ($proxy_web_requests)
    {
	    write_debug_log("Proxy web requests is enabled", 'debug');

        // Get the proxy configuration
        $proxy_verify_ssl_certificate = get_setting("proxy_verify_ssl_certificate");
        $proxy_host = get_setting("proxy_host");
        $proxy_port = get_setting("proxy_port");
        $proxy_authenticated = get_setting("proxy_authenticated");
        $proxy_user = get_setting("proxy_user");
        $proxy_pass = get_setting("proxy_pass");

        // Create the http context array. protocol_version and user_agent
        // are set here so every caller picks them up: PHP's HTTP stream
        // wrapper defaults to HTTP/1.0 and an empty User-Agent, which
        // Cloudflare-fronted services (services.nvd.nist.gov, github.com,
        // etc.) silently reject as bot traffic — get_headers() and
        // file_get_contents() then return false with a generic
        // "HTTP request failed!" message that looks identical to a real
        // network outage. HTTP/1.1 + any non-empty User-Agent gets past
        // that filter. The User-Agent stays generic ('SimpleRisk') so
        // server-side filtering on specific versions is one less moving
        // part. Callers that need a different UA can append a
        // "User-Agent: ..." line via the $header parameter — header-line
        // values override the user_agent context option in PHP's HTTP
        // stream wrapper.
        $http_context = array(
            'proxy' => "tcp://$proxy_host:$proxy_port",
            'ignore_errors' => true,
            'request_fulluri' => true,
            'protocol_version' => 1.1,
            'user_agent' => 'SimpleRisk',
        );

	write_debug_log("HTTP Context - Proxy: " . $http_context['proxy'], 'debug');
	write_debug_log("HTTP Context - Ignore Errors: " . $http_context['ignore_errors'], 'debug');
	write_debug_log("HTTP Context - Request Full URI: " . $http_context['request_fulluri'], 'debug');

    // Create the ssl context array
    $ssl_context = array(
        'SNI_enabled' => true
    );

	write_debug_log("SSL Context - SNI Enabled: " . $ssl_context['SNI_enabled'], 'debug');

        // If this is an authenticated proxy
        if ($proxy_authenticated)
        {
	    write_debug_log("We are using an authenticated proxy", 'debug');

            // Create the BASE64 encoded credentials
            $auth = base64_encode("$proxy_user:$proxy_pass");

            // Add the authenticated header to the http_context
            $http_context['header'] = "Proxy-Authorization: Basic $auth";

	    write_debug_log("HTTP Context - Header: " . $http_context['header'], 'debug');
        }

        // If we want to turn off ssl verification
        if (!$proxy_verify_ssl_certificate || $ssl_verify_off == true)
        {
	    write_debug_log("SSL verification is disabled", 'debug');

            $ssl_context['verify_peer'] = false;
            $ssl_context['verify_peer_name'] = false;
            $ssl_context['allow_self_signed'] = true;

	    write_debug_log("SSL Context - Verify Peer: " . $ssl_context['verify_peer'], 'debug');
	    write_debug_log("SSL Context - Verify Peer Name: " . $ssl_context['verify_peer_name'], 'debug');
	    write_debug_log("SSL Context - Allow Self Signed: " . $ssl_context['allow_self_signed'], 'debug');
        }

        // If the function was provided a method
        if ($method)
        {
	    write_debug_log("A method was provided", 'debug');

            // Set the provided method
            $http_context['method'] = $method;

	    write_debug_log("HTTP Context - Method: " . $http_context['method'], 'debug');
        }

        // If the function was provided a header
        if ($header)
        {
	    write_debug_log("A header was provider", 'debug');

            // If a http header is already set
            if (isset($http_context['header']))
            {
                // Append the provided header
                $http_context['header'] .= "\r\n" . $header;
            }
            // Otherwise
            else
            {
                // Set the provided header
                $http_context['header'] = $header;
            }

	    write_debug_log("HTTP Context - Header: " . $http_context['header'], 'debug');
        }

        // If the function was provided content
        if ($content)
        {
	    write_debug_log("Content was provided", 'debug');

            // Set the provided content
            $http_context['content'] = $content;

	    write_debug_log("HTTP Context - Content: " . $http_context['content'], 'debug');
        }

	// If a timeout was provided
	if ($timeout)
	{
            write_debug_log("Timeout was provided", 'debug');

	    // Set the provided timeout
	    $http_context['timeout'] = $timeout;

	    write_debug_log("HTTP Context - Timeout: " . $http_context['timeout'], 'debug');
	}

        // Set the stream context
        $stream_context = array ('http' => $http_context, 'ssl' => $ssl_context);

	//write_debug_log("Stream Context: ");
	//write_debug_log($stream_context);

        // Return the default stream context resource
        return stream_context_set_default($stream_context);
    }
    // Otherwise, if the proxy is not enabled
    else
    {
        // Create array for the http context. protocol_version and
        // user_agent are set so every caller picks them up — see the
        // matching block in the proxy-enabled branch above for the full
        // rationale (Cloudflare-fronted services reject HTTP/1.0 + empty
        // User-Agent silently, breaking get_headers() / file_get_contents()
        // with what looks like a network outage).
        $http_context = array(
            'protocol_version' => 1.1,
            'user_agent' => 'SimpleRisk',
        );

        // If the function was provided a method
        if ($method)
        {
            write_debug_log("A method was provided", 'debug');

            // Set the provided method
            $http_context['method'] = $method;

            write_debug_log("HTTP Context - Method: " . $http_context['method'], 'debug');
        }

        // If the function was provided a header
        if ($header)
        {
            write_debug_log("A header was provider", 'debug');

            // If a http header is already set
            if (isset($http_context['header']))
            {
                // Append the provided header
                $http_context['header'] .= "\r\n" . $header;
            }
            // Otherwise
            else
            {
                // Set the provided header
                $http_context['header'] = $header;
            }

            write_debug_log("HTTP Context - Header: " . $http_context['header'], 'debug');
        }

        // If the function was provided content
        if ($content)
        {
            write_debug_log("Content was provided", 'debug');

            // Set the provided content
            $http_context['content'] = $content;

            write_debug_log("HTTP Context - Content: " . $http_context['content'], 'debug');
        }

        // If a timeout was provided
        if ($timeout)
        {
            write_debug_log("Timeout was provided", 'debug');

            // Set the provided timeout
            $http_context['timeout'] = $timeout;

            write_debug_log("HTTP Context - Timeout: " . $http_context['timeout'], 'debug');
        }

        // Create the ssl context array
        $ssl_context = array(
            'SNI_enabled' => true
        );
        write_debug_log("SSL Context - SNI Enabled: " . $ssl_context['SNI_enabled'], 'debug');

        // If we want to turn off ssl verification
        if (get_setting("ssl_certificate_check") != 1)
        {
            write_debug_log("SSL verification is disabled", 'debug');

            $ssl_context['verify_peer'] = false;
            $ssl_context['verify_peer_name'] = false;
            $ssl_context['allow_self_signed'] = true;

            write_debug_log("SSL Context - Verify Peer: " . $ssl_context['verify_peer'], 'debug');
            write_debug_log("SSL Context - Verify Peer Name: " . $ssl_context['verify_peer_name'], 'debug');
            write_debug_log("SSL Context - Allow Self Signed: " . $ssl_context['allow_self_signed'], 'debug');
        }

        // Set the stream context
        $stream_context = array ('http' => $http_context, 'ssl' => $ssl_context);

        // Return the default stream context resource
        return stream_context_set_default($stream_context);
    }
}

/**********************************
 * FUNCTION: CONFIGURE CURL PROXY *
 **********************************/
function configure_curl_proxy($curl_handle)
{
	// Get the proxy_web_requests value
	$proxy_web_requests = get_setting("proxy_web_requests");

	// If proxy web requests is set
	if ($proxy_web_requests)
        {
                // Get the proxy configuration
                $proxy_verify_ssl_certificate = get_setting("proxy_verify_ssl_certificate");
                $proxy_host = get_setting("proxy_host");
                $proxy_port = get_setting("proxy_port");
                $proxy_authenticated = get_setting("proxy_authenticated");
                $proxy_user = get_setting("proxy_user");
                $proxy_pass = get_setting("proxy_pass");

                // Configure the proxy
                $proxy = "{$proxy_host}:{$proxy_port}";
                curl_setopt($curl_handle, CURLOPT_PROXY, $proxy);

                // If this is an authenticated proxy
                if ($proxy_authenticated)
                {
                        // Provide the username and password for authentication
                        $proxyauth = "{$proxy_user}:{$proxy_pass}";
                        curl_setopt($curl_handle, CURLOPT_PROXYUSERPWD, $proxyauth);
                }

		        // If we do not want to verify the proxy SSL certificates
		        if (!$proxy_verify_ssl_certificate)
		        {
			        // Do not verify the SSL host and peer
			        curl_setopt($curl_handle, CURLOPT_PROXY_SSL_VERIFYPEER, false);
		        }
        }
        else curl_setopt($curl_handle, CURLOPT_PROXY, null);
}

/********************************************************************************************************
 * FUNCTION: SAVE JUNCTION VALUES                                                                       *
 * Used to update the associations between tables.                                                      *
 * Can be used both ways. In case of junction table `X_to_Y` it can be used to                          *
 * update X's associations to multiple Ys or to update Y's associations to multiple Xs.                 *
 * If the $second_field_name and $second_ids are not set, then the associations are removed             *
 * and no furher action is done. Useful on deletes to clean up the associations of the deleted item.    *
 ********************************************************************************************************/
function save_junction_values($tb_name, $first_field_name, $first_id, $second_field_name=false, $second_ids=[]) {
    // If the id is not set or it's not a number
    if (!$first_id || !is_numeric($first_id)) {
        return false;
    }

    $db = db_open();

    // Delete the current associations
    $stmt = $db->prepare("DELETE FROM `{$tb_name}` WHERE `{$first_field_name}` = :value;");
    $stmt->bindParam(":value", $first_id, PDO::PARAM_INT);
    $stmt->execute();

    // We just needed the existing associations cleaned up.
    if (!$second_ids) {
        db_close($db);
        return true;
    }

    if(!is_array($second_ids)) {
        $second_ids = explode(',', $second_ids);
    }

    // Sanitizing the array's values
    $second_ids = sanitize_int_array($second_ids);

    // If wasn't empty before and it's empty now then the sanitizing caught something
    if (!$second_ids) {
        db_close($db);
        return false;
    }

    $values = [];
    foreach($second_ids as $second_id) {
        $values[] = "('{$first_id}', '{$second_id}')";
    }

    $sql = "
        INSERT IGNORE INTO
            `{$tb_name}`({$first_field_name}, {$second_field_name})
        VALUES
            " . implode(',', $values);

    $stmt = $db->prepare($sql);
    $stmt->execute();

    db_close($db);

    // Audit log
    $username = isset($_SESSION['user']) ? $_SESSION['user'] : 'admin'; // because it can happen that this function is used even before the user logs in, thus there's no session
    $message = "New data \"" . $first_id . "\" inserted to `{$first_field_name}` field of `{$tb_name}` table submitted by username \"" . $username . "\".";
    if(count($second_ids)) {
        $message .= "\nNew datas (" . implode(",",$second_ids) . ") inserted to `{$second_field_name}` field of `{$tb_name}` table submitted by username \"" . $username . "\".";
    }
    write_log(100, isset($_SESSION['uid']) ? $_SESSION['uid'] : 0, $message);

    return true;
}

/************************************************************************************************************
 * FUNCTION: CLEANUP AFTER DELETE                                                                           *
 * It is used to remove junction entries after an item is deleted from the table "$deleted_item_table".     *
 * The query is structured in a way that it can be used after multiple deletes as it's not targeting        *
 * junction entries for a specific id, it's deleting every junction entry that has no matching id           *
 * in the table "$deleted_item_table".                                                                      *
 * Please note, that because of the above you don't have to call this function after each delete in case    *
 * of a batch-delete, it's enough if it's called once the batch-delete is finished.                         *
 ************************************************************************************************************/
function cleanup_after_delete($deleted_item_table) {
    global $junction_config;

    // It's possible that there're tables that are only present when an extra is installed/enabled
    if (!array_key_exists($deleted_item_table, $junction_config) || !table_exists($deleted_item_table)) {
        return;
    }

    $db = db_open();

    // Getting the configuration for the table
    $config = $junction_config[$deleted_item_table];
    // Getting the name of its id field
    $deleted_item_table_id_field = $config['id_field'];
    
    $has_tags = isset($config['tag_type']) && !empty($config['tag_type']);

    // Iterating through the related junction tables
    foreach($config['junctions'] as $junction_table_name => $junction_deleted_item_id_field) {
        
        // It's possible that there're tables that are only present when an extra is installed/enabled
        if (!table_exists($junction_table_name)) {
            continue;
        }

        // Clean up every junction entries that aren't tied to a value in the configued table
        $stmt = $db->prepare("
            DELETE
                `junction`
            FROM
                `{$junction_table_name}` `junction`
                LEFT JOIN `{$deleted_item_table}` `tbl` ON `junction`.`{$junction_deleted_item_id_field}` = `tbl`.`{$deleted_item_table_id_field}`
            WHERE
                `tbl`.`{$deleted_item_table_id_field}` IS NULL;
        ");
        $stmt->execute();
    }

    if ($has_tags) {

        // @phan-suppress-next-line PhanTypePossiblyInvalidDimOffset -- $has_tags above guarantees tag_type is set
        $tag_type = $config['tag_type'];
        // Clean up every tag junction entries that aren't tied to a value in the configued table
        // but make sure we're not deleting other types' junction entries
        $stmt = $db->prepare("
            DELETE
                `tt`
            FROM
                `tags_taggees` `tt`
                LEFT JOIN `{$deleted_item_table}` `tbl` ON `tt`.`type` = '{$tag_type}' AND `tt`.`taggee_id` = `tbl`.`{$deleted_item_table_id_field}`
            WHERE
                `tbl`.`{$deleted_item_table_id_field}` IS NULL
                AND `tt`.`type` = '{$tag_type}';
        ");
        $stmt->execute();
        
        // Clean up every tags that aren't referenced by the junction table
        $stmt = $db->prepare("
            DELETE
                `t`
            FROM
                `tags` `t`
                LEFT JOIN `tags_taggees` `tt` ON `tt`.`tag_id` = `t`.`id`
            WHERE
                `tt`.`taggee_id` IS NULL;
        ");
        $stmt->execute();
    }
    
    db_close($db);
}

/*********************************************
 * FUNCTION: RECURSIVE URL DECODE            *
 * Decodes all layers of URL encoding       *
 * e.g. %2520 -> %20 -> (space)             *
 *********************************************/
function recursive_urldecode($str) {
    $prev = '';
    while ($prev !== $str) {
        $prev = $str;
        $str = urldecode($str);
    }
    return $str;
}

/*******************************************************************************
 * FUNCTION: IP IS LOOPBACK                                                     *
 * Pure (no DNS): is $ip an IPv4 loopback (127.0.0.0/8) or the IPv6 loopback    *
 * (::1)? Used by the outbound-URL SSRF guards to permit self-hosted services.  *
 *******************************************************************************/
function ip_is_loopback($ip) {
    if (filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
        return strpos($ip, '127.') === 0;
    }
    if (filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6)) {
        $packed = @inet_pton($ip);
        return $packed !== false && $packed === inet_pton('::1');
    }
    return false;
}

/*******************************************************************************
 * FUNCTION: IP IS PRIVATE OR RESERVED                                          *
 * Pure (no DNS): true when $ip is NOT a public, globally-routable address —    *
 * i.e. private (RFC1918 / fc00::/7), loopback (127/8, ::1), link-local         *
 * (169.254/16 incl. cloud metadata 169.254.169.254, fe80::/10), or otherwise   *
 * reserved. Anything that is not a valid public IP is treated as unsafe. This  *
 * is the SSRF core the outbound-URL guards build on.                           *
 *******************************************************************************/
function ip_is_private_or_reserved($ip) {
    if (filter_var($ip, FILTER_VALIDATE_IP) === false) {
        return true; // not a valid IP → unsafe
    }
    // filter_var's NO_RES_RANGE misses a few non-routable / internal ranges that
    // are still SSRF-reachable: 100.64.0.0/10 (RFC 6598 CGNAT — e.g. Tailscale mesh
    // and some cloud NAT fabrics), 192.0.0.0/24 (RFC 6890 IETF protocol assignments),
    // and 198.18.0.0/15 (RFC 2544 benchmarking). Flag them explicitly.
    foreach (['100.64.0.0/10', '192.0.0.0/24', '198.18.0.0/15'] as $cidr) {
        if (ip_in_cidr($ip, $cidr)) return true;
    }
    // filter_var returns the address only when it is public and non-reserved.
    return filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE) === false;
}

/*******************************************************************************
 * FUNCTION: RESOLVE HOST IPS                                                   *
 * Resolve a hostname to its IPv4 + IPv6 addresses. A bare IP literal (optionally *
 * bracketed for IPv6) returns itself. Returns [] on resolution failure —       *
 * callers treat an empty result as unsafe (fail-closed).                       *
 *******************************************************************************/
function resolve_host_ips($host) {
    $host = trim((string)$host);
    if ($host === '') return [];
    $bare = trim($host, '[]');
    if (filter_var($bare, FILTER_VALIDATE_IP)) return [$bare];
    $ips = [];
    $a = @gethostbynamel($host);
    if (is_array($a)) $ips = array_merge($ips, $a);
    $aaaa = @dns_get_record($host, DNS_AAAA);
    if (is_array($aaaa)) {
        foreach ($aaaa as $rec) {
            if (!empty($rec['ipv6'])) $ips[] = $rec['ipv6'];
        }
    }
    return array_values(array_unique($ips));
}

/*******************************************************************************
 * FUNCTION: IP IN CIDR                                                          *
 * Pure (no DNS): does $ip fall inside $entry, where $entry is a bare IP literal *
 * (exact match) or a CIDR block (e.g. 10.0.0.0/8, fc00::/7)? IPv4 and IPv6.     *
 * A non-IP/non-CIDR $entry (e.g. a hostname) returns false. Used by the         *
 * outbound-target allow-list matcher.                                          *
 *******************************************************************************/
function ip_in_cidr($ip, $entry) {
    $ip_bin = @inet_pton((string)$ip);
    if ($ip_bin === false) return false;
    $entry = trim((string)$entry);
    if (strpos($entry, '/') === false) {
        $entry_bin = @inet_pton($entry);
        return $entry_bin !== false && $entry_bin === $ip_bin;
    }
    [$subnet, $bits] = explode('/', $entry, 2);
    $subnet_bin = @inet_pton($subnet);
    if ($subnet_bin === false) return false;
    if (strlen($subnet_bin) !== strlen($ip_bin)) return false; // v4 vs v6 mismatch
    $bits = (int)$bits;
    if ($bits < 0 || $bits > strlen($ip_bin) * 8) return false;
    $whole = intdiv($bits, 8);
    $rem   = $bits % 8;
    if ($whole > 0 && substr($ip_bin, 0, $whole) !== substr($subnet_bin, 0, $whole)) return false;
    if ($rem > 0) {
        $mask = chr((0xff << (8 - $rem)) & 0xff);
        if ((ord($ip_bin[$whole]) & ord($mask)) !== (ord($subnet_bin[$whole]) & ord($mask))) return false;
    }
    return true;
}

/*******************************************************************************
 * FUNCTION: OUTBOUND TARGET ALLOWLISTED                                         *
 * Is a single (host, ip) destination explicitly permitted by $allowed — an     *
 * admin-maintained list of hostnames, bare IPs, and/or CIDR blocks in           *
 * config.php? A hostname entry matches the URL host (case-insensitive); an      *
 * IP / CIDR entry matches the resolved IP. This is the config.php half of the   *
 * two-actor control: a destination the in-app admin configured is only reached  *
 * if a system admin also named it here.                                        *
 *******************************************************************************/
function outbound_target_allowlisted($host, $ip, array $allowed) {
    $host = strtolower(trim((string)$host));
    foreach ($allowed as $entry) {
        $entry = trim((string)$entry);
        if ($entry === '') continue;
        if ($host !== '' && strtolower($entry) === $host) return true; // hostname entry
        if (ip_in_cidr($ip, $entry)) return true;                      // IP / CIDR entry
    }
    return false;
}

/*******************************************************************************
 * FUNCTION: SAFE OUTBOUND REQUEST TARGET                                        *
 * SSRF guard for a server-initiated HTTP request to a user/admin-supplied URL.  *
 * Resolves the host ONCE and returns a pin descriptor                          *
 * ['host','port','ip','resolve'] when the URL is safe to fetch, or null.        *
 * Public, routable destinations are always allowed. An internal destination     *
 * (loopback / private / link-local incl. 169.254.169.254 cloud metadata /       *
 * reserved) is allowed ONLY when explicitly named in $allowed (host / IP / CIDR *
 * from config.php) — otherwise denied, along with non-http(s) schemes and       *
 * unresolvable hosts. The returned 'resolve' string ("host:port:ip") is meant   *
 * for CURLOPT_RESOLVE so the request connects to the VALIDATED ip (closing the  *
 * DNS-rebinding TOCTOU); the caller should also disable redirect-following.     *
 *******************************************************************************/
function safe_outbound_request_target($url, array $allowed = []) {
    $scheme = strtolower((string)parse_url((string)$url, PHP_URL_SCHEME));
    if (!in_array($scheme, ['http', 'https'], true)) return null;
    $host = parse_url((string)$url, PHP_URL_HOST);
    if ($host === null || $host === '') return null;
    $port = (int)(parse_url((string)$url, PHP_URL_PORT) ?: ($scheme === 'https' ? 443 : 80));
    $ips = resolve_host_ips($host);
    if (empty($ips)) return null;
    foreach ($ips as $ip) {
        if (ip_is_private_or_reserved($ip) && !outbound_target_allowlisted($host, $ip, $allowed)) {
            return null; // internal / reserved and not explicitly allow-listed
        }
    }
    // All resolved IPs are public or explicitly allow-listed. Pin the first via a
    // CURLOPT_RESOLVE token ONLY when the host is a hostname — a literal IP has no
    // DNS to rebind, and a bracketed IPv6 literal isn't a valid resolve host token.
    $is_literal = filter_var(trim($host, '[]'), FILTER_VALIDATE_IP) !== false;
    return [
        'host'    => $host,
        'port'    => $port,
        'ip'      => $ips[0],
        'resolve' => $is_literal ? null : "{$host}:{$port}:{$ips[0]}",
    ];
}

/*******************************************************************************
 * FUNCTION: IS SAFE OUTBOUND URL                                               *
 * Boolean convenience wrapper over safe_outbound_request_target(): true when    *
 * the URL is http(s) and every resolved IP is public or explicitly named in     *
 * the config.php $allowed list. Default $allowed = [] → deny ALL internal.      *
 *******************************************************************************/
function is_safe_outbound_url($url, array $allowed = []) {
    return safe_outbound_request_target($url, $allowed) !== null;
}

/*******************************************************
 * FUNCTION: BUILD SIMPLERISK BASED URL FROM ARGUMENTS *
 * Takes any number of arguments and                   *
 * builds a URL from them.                             *
 * Romove any double slashes in a url                  *
 * but preserve the double slash                       *
 * after the protocol                                  *
 * (http:// or https:// and so on)                     *
 *******************************************************/
function build_url(...$args) {

    // Get Base URL
    $simplerisk_base_url = !empty($_SESSION['base_url']) ? $_SESSION['base_url'] : get_base_url();

    $safe_segments = [];

    foreach ($args as $part) {

        // Trim whitespace from the part
        $part = trim($part);

        // Fully decode all layers of URL encoding
        $decoded = recursive_urldecode($part);

        // Normalize slashes (replace backslash with forward slash)
        $decoded = str_replace('\\', '/', $decoded);

        // Split into segments
        $segments = explode('/', $decoded);

        foreach ($segments as $segment) {
            // Reject empty, '.', or '..' segments (path traversal)
            if ($segment === '' || $segment === '.' || $segment === '..') {
                continue;
            }

            // Reject control characters or null bytes inside segments
            if (preg_match('/[\x00-\x1F\x7F]/u', $segment)) {
                continue;
            }

            $safe_segments[] = $segment;
        }
    }

    // Join safe segments with slash
    $url_path = implode('/', $safe_segments);

    // Combine with base URL (remove trailing slash from base, leading slash from path)
    $url = rtrim($simplerisk_base_url, '/') . '/' . ltrim($url_path, '/');

    // Remove multiple slashes except after protocol (e.g. 'http://')
    $url = preg_replace('#(?<!:)//+#', '/', $url);

    // Return the cleaned URL
    return rtrim($url, '/');

}

/*************************************
 * FUNCTION: GET ENCODED REQUEST URI *
 *************************************/
function get_encoded_request_uri()
{
    $requested_uri = get_request_uri();
    $uri = parse_url($requested_uri, PHP_URL_PATH);

    if(isset($_GET) && count($_GET) > 0)
    {
        $uri .= "?" . http_build_query($_GET);
    }
    
    return $uri;
}
/*****************************
 * FUNCTION: GET REQUEST URI *
 *****************************/
function get_request_uri()
{
    //$requested_uri = $_SERVER["REQUEST_URI"];
    $dir_path = realpath(dirname(dirname(__FILE__)));
    $file_name = realpath($_SERVER["SCRIPT_FILENAME"]);
    $requested_uri = str_replace($dir_path,"",$file_name);
    $requested_uri = str_replace(DIRECTORY_SEPARATOR ,"/",$requested_uri);
    return $requested_uri;
}

/*************************************
 * FUNCTION: GET OPERATOR FROM VALUE *
    * >  : 0
    * >= : 1
    * =  : 2
    * <= : 3
    * <  : 4
 *************************************/
function get_operator_from_value($value)
{
    $operators = [">", ">=", "=", "<=", "<"];
    return empty($operators[$value]) ? false : $operators[$value];
}

/****************************************************************
 * FUNCTION: GET LATEST APP VERSION                             *
 * Used to get the app's latest version from the session,       *
 * but if it's not set, gets it from the simplerisk servers.    *
 ****************************************************************/
function get_latest_app_version() {
    if (!isset($_SESSION['latest_version_app']) || !$_SESSION['latest_version_app']) {
        // Use the DB-cached value from the version check job to avoid a blocking network call
        $_SESSION['latest_version_app'] = latest_version('app', false);
    }

    return $_SESSION['latest_version_app'];
}

function setup_favicon($path_to_root = "") {   

    global $escaper;

    if ($path_to_root) {
        if($path_to_root[strlen($path_to_root)-1] !== '/') {
            $path_to_root .= '/';
        }
        $path_to_root = $escaper->escapeHtml($path_to_root);
    }

    echo "<link rel='shortcut icon' href='{$path_to_root}favicon.ico' />\n";
}

/**********************************************
 * FUNCTION: GET MITIGATION TEAM QUERY STRING *
 * As of 2020.02.28 it's not used anywhere,   *
 * left here for legacy code                  *
 **********************************************/
function get_mitigation_team_query_string($user_teams, $field_name)
{
    // Create an array based on the colon delimeter
    $teams = explode(":", $user_teams);
    $teams = array_unique(array_map('intval', $teams));

    // String starts as empty
    $string = " FIND_IN_SET({$field_name}, '". implode(",", $teams) ."') ";

    // Return the string
    return $string;
}

