        }
    }
    return true;
}

/***********************************************
 * FUNCTION: CUSTOM COLUMN ORDER IS VALID      *
 * Generic name for the Review Risk validator: *
 * the body was never Review-Risk-specific.    *
 ***********************************************/
function custom_column_order_is_valid($order)
{
    return custom_review_risk_column_order_is_valid($order);
}

/*****************************************************************
 * FUNCTION: PLAN PROJECTS DUE STATUS                            *
 * 'none' (no date), 'overdue' (before today), 'due_soon'        *
 * (today .. today + $due_soon_days), else 'on_track'. The 30-day *
 * default is the same window classify_review_urgency() uses.    *
 *****************************************************************/
function plan_projects_due_status(?string $due_date, ?string $today = null, int $due_soon_days = 30): string
{
    if ($due_date === null || $due_date === '' || strpos((string)$due_date, '0000-00-00') === 0) {
        return 'none';
    }
    $due = strtotime(substr((string)$due_date, 0, 10) . ' 00:00:00');
    if ($due === false) {
        return 'none';
    }
    $today_ts = strtotime(($today ?: date('Y-m-d')) . ' 00:00:00');
    $days = (int)floor(($due - $today_ts) / 86400);
    if ($days < 0) {
        return 'overdue';
    }
    if ($days <= (int)$due_soon_days) {
        return 'due_soon';
    }
    return 'on_track';
}

/*******************************************************************
 * FUNCTION: PLAN PROJECTS REORDER WITHIN STATUS                   *
 * projects.order is ONE global sequence. Given every project and a *
 * new ordering for the ids of one status, refill that status's     *
 * slots in the global sequence and renumber 1..n so the relative   *
 * order of every other status is preserved. Returns [id => order] *
 * or false when $new_ordered_ids is not exactly that status's set. *
 *******************************************************************/
function plan_projects_reorder_within_status(array $projects, int $status, array $new_ordered_ids): array|false
{
    $status = (int)$status;
    $current_ids = [];
    foreach ($projects as $p) {
        if ((int)$p['status'] === $status) {
            $current_ids[] = (int)$p['id'];
        }
    }
    foreach ($new_ordered_ids as $id) {
        if (!is_int($id) && !(is_string($id) && ctype_digit($id))) {
            return false;
        }
    }
    $new_ordered_ids = array_map('intval', $new_ordered_ids);
    if (count($new_ordered_ids) !== count(array_unique($new_ordered_ids))) {
        return false;
    }
    $a = $current_ids;
    $b = $new_ordered_ids;
    sort($a);
    sort($b);
    if ($a !== $b) {
        return false;
    }
    // Stable sort by current order, then id, so stale duplicates resolve deterministically.
    usort($projects, function ($x, $y) {
        return [(int)$x['order'], (int)$x['id']] <=> [(int)$y['order'], (int)$y['id']];
    });
    $result = [];
    $next = 1;
    $slot = 0;
    foreach ($projects as $p) {
        if ((int)$p['status'] === $status) {
            $result[$new_ordered_ids[$slot++]] = $next++;
        } else {
            $result[(int)$p['id']] = $next++;
        }
    }
    return $result;
}

/****************************************************
 * FUNCTION: BUILD ACTIVE REVIEW RISK COLUMNS        *
 ****************************************************/
// Resolves the Customization Extra's active risk fields into the
// {key, label, group} shape review-risk.js's COLUMN_GROUPS already uses --
// mirrors the legacy display_custom_risk_columns()'s own resolution
// (includes/display.php, deleted in a4e1321963 -- see it at a4e1321963~1)
// but WITHOUT that function's basic-field "relabeling" (it never actually
// relabeled anything -- get_dynamic_names_by_main_field_name() returns the
// STANDARD $lang text for a basic field, not an admin-chosen rename; see
// docs/superpowers/specs/2026-09-10-review-risk-dynamic-columns-design.md's
// "Scope correction" section).
//
// Returns null when the Extra isn't active -- callers use this to decide
// whether to fall back to review-risk.js's own static COLUMN_GROUPS.
//
// `label` is DELIBERATELY RAW, not pre-escaped -- double-escaping fix
// (SR follow-up): this array feeds TWO different sinks with two different
// escaping needs -- includes/display.php's three dynamic <th> echoes
// (server-rendered, need escapeHtml() at that echo site) and
// getReviewRiskFilterOptions()'s JSON `active_columns` response
// (review-risk.js's columnLabel()/esc() already HTML-escapes exactly once
// when it renders the label into the picker). Pre-escaping here made both
// sinks double-escape (a label like "Owner's Manager" rendered literally as
// "Owner&#039;s Manager" in the Columns picker) -- each sink now escapes
// exactly once, at its own point of use, per CLAUDE.md's HTML Encoding
// rule. get_dynamic_names_by_main_field_name() (includes/display.php)
// returns its 'text' field raw for the same reason -- it has exactly one
// caller (this function; confirmed via grep, its two other callers only
// ever read 'name', never 'text').
function build_active_review_risk_columns()
{
    if (!customization_extra()) {
        return null;
    }

    // get_dynamic_names_by_main_field_name() below is defined in display.php,
    // not functions.php -- and functions.php does NOT require display.php
    // (see display_the_brand_logo()'s own comment: healthcheck.php loads only
    // functions.php, deliberately). This function's only current caller
    // (api.php) happens to already load both, but per CLAUDE.md's Function
    // Reachability rule every direct consumer declares its own require_once
    // rather than relying on that transitive load -- belt-and-suspenders, and
    // required here since a future functions.php-only caller would otherwise
    // hit a fatal "Call to undefined function" the moment an is_basic=1 field
    // is active. Unguarded, matching api.php's and artificial_intelligence.php's
    // own sibling `require_once(realpath(__DIR__ . '/display.php'))` -- this is
    // a Core-to-Core require of a file that ships in every install (unlike the
    // Extra file below, which the bundle can strip), so no realpath-false guard
    // is needed. Safe to require mid-function: functions.php is already fully
    // parsed by the time any function body executes.
    require_once(realpath(__DIR__ . '/display.php'));

    $file = realpath(__DIR__ . '/../extras/customization/index.php');
    if ($file === false) {
        return null;
    }
    require_once($file);

    $tab_index_to_group = [1 => 'RiskColumns', 2 => 'MitigationColumns', 3 => 'ReviewColumns'];

    $columns = [];
    $active_fields = get_active_fields('risk');
    foreach ($active_fields as $active_field) {
        $group = $tab_index_to_group[(int)($active_field['tab_index'] ?? 0)] ?? null;
        if ($group === null) {
            continue; // Unrecognized tab -- matches the legacy switch's implicit drop of any other tab_index.
        }

        if ((int)($active_field['is_basic'] ?? 0) === 1) {
            $dynamic_field_info = get_dynamic_names_by_main_field_name($active_field['name']);
            if (!$dynamic_field_info) {
                continue; // No resolvable db-column/label pair for this basic field name -- same skip the legacy code applied.
            }
            $columns[] = [
                'key' => $dynamic_field_info['name'],
                // Deliberately RAW, not escaped here -- see this function's
                // own docblock (double-escaping fix). get_dynamic_names_by_
                // main_field_name() also returns 'text' raw now, for the
                // same reason.
                'label' => $dynamic_field_info['text'],
                'group' => $group,
            ];
        } else {
            $columns[] = [
                'key' => 'custom_field_' . (int)$active_field['id'],
                // Deliberately RAW -- see this function's own docblock.
                'label' => $active_field['name'],
                'group' => $group,
            ];
        }
    }

    return $columns;
}

/**
 * Column vocabulary for the Define Control Frameworks page's Columns picker
 * (mirrors build_active_review_risk_columns()/build_active_plan_projects_
 * columns() -- the standing pattern for a page whose custom-field columns are
 * curated by the Customization Extra). NULL when the Extra is off -> the
 * client keeps its own static 8-column list (ControlFamily/Owner/Class/Phase/
 * Priority/ControlType/Maturity/Status) and offers no custom fields.
 *
 * ControlNumber and ControlShortName are the page's pinned lead columns --
 * never toggleable, so they map to null and are dropped, matching
 * build_active_plan_projects_columns()'s 'ProjectName' => null entry.
 *
 * `label` is DELIBERATELY RAW for custom fields (admin-named, not translated)
 * -- same double-escaping contract as the two sibling functions above: the
 * picker's JS escapes it exactly once when it renders the checkbox label.
 */
function build_active_control_columns()
{
    global $lang;
    if (!customization_extra()) {
        return null;
    }
    $file = realpath(__DIR__ . '/../extras/customization/index.php');
    if ($file === false) {
        return null;
    }
    require_once($file);

    $basic_map = [
        'ControlNumber'          => null,
        'ControlShortName'       => null,
        'ControlFamily'          => ['family', $lang['ControlFamily']],
        'ControlOwner'           => ['owner', $lang['Owner']],
        'ControlClass'           => ['class', $lang['ControlClass']],
        'ControlPhase'           => ['phase', $lang['ControlPhase']],
        'ControlPriority'        => ['priority', $lang['ControlPriority']],
        'ControlType'            => ['control_type', $lang['ControlType']],
        'CurrentControlMaturity' => ['maturity', $lang['Maturity']],
        'ControlStatus'          => ['status', $lang['Status']],
    ];

    $columns = [];
    foreach (get_active_fields('control') as $field) {
        if ((int)$field['is_basic'] === 1) {
            $entry = $basic_map[$field['name']] ?? null;
            if ($entry) {
                $columns[] = ['key' => $entry[0], 'label' => $entry[1], 'custom' => false];
            }
        } else {
            $columns[] = [
                'key' => 'custom_field_' . (int)$field['id'],
                // Deliberately RAW -- see this function's own docblock.
                'label' => $field['name'],
                'custom' => true,
            ];
        }
    }
    return $columns;
}

/**
 * Structural sanitizer for a decoded custom_control_frameworks_display_
 * settings row: defends the read path against a row written before this
 * validation existed, or any other stray shape, the same way
 * plan_projects_sanitize_column_settings() (includes/api.php) re-validates
 * its own stored JSON from scratch rather than trusting storage.
 *
 * `columns` pairs are kept only when the name is a plain [A-Za-z0-9_]+ token
 * (SR-1870 -- it is later used as a data-col attribute) and the value is a
 * recognized 0/1 flag. Any other top-level key -- including a `filters` key
 * a pre-fix row may still carry -- is silently dropped: the filter sheet's
 * facet state is not persisted, so a leftover `filters` blob from before
 * this was pulled back out is inert data, never read back into the client.
 *
 * Returns ['columns' => [...]] or null when nothing valid remains.
 */
function control_frameworks_sanitize_display_settings($decoded)
{
    if (!is_array($decoded)) {
        return null;
    }
    $sanitized = [];
    if (isset($decoded['columns']) && is_array($decoded['columns'])) {
        $valid_columns = [];
        foreach ($decoded['columns'] as $pair) {
            $name = is_array($pair) ? ($pair[0] ?? null) : null;
            $value = is_array($pair) ? ($pair[1] ?? null) : null;
            if (is_string($name) && preg_match('/^[A-Za-z0-9_]+$/', $name) && custom_display_column_value_is_valid($value)) {
                $valid_columns[] = [$name, custom_display_normalize_column_flag($value)];
            }
        }
        if (!empty($valid_columns)) {
            $sanitized['columns'] = $valid_columns;
        }
    }
    return empty($sanitized) ? null : $sanitized;
}

/***********************************************
 * FUNCTION: SAVE CUSTOM RISK DISPLAY SETTINGS *
 **********************************************/
function save_custom_risk_display_settings($field = "custom_review_risk_display_settings", $data = [], $user_id = null)
{
    // Defaults to the session user; callers that already know the user (and
    // tests) may pass an explicit id. $field is always a caller-side constant.
    $user_id = ($user_id === null) ? $_SESSION['uid'] : (int)$user_id;
    $data_str = json_encode($data);
    
    // Open the database connection
    $db = db_open();

    $stmt = $db->prepare("UPDATE `user` SET `{$field}` = :data_str WHERE `value` = :value");
    $stmt->bindParam(":data_str", $data_str, PDO::PARAM_STR);
    $stmt->bindParam(":value", $user_id, PDO::PARAM_INT);
    $stmt->execute();

    // Close the database connection
    db_close($db);
}

function get_user_name($user_id) {
    // Open the database connection
    $db = db_open();
    
    // Query the database
    $stmt = $db->prepare("SELECT `name` FROM `user` WHERE `value` = :user_id;");
    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->execute();
    
    $name = $stmt->fetch(PDO::FETCH_COLUMN);
    
    // Close the database connection
    db_close($db);
    
    return $name;
}

/************************************************************************
 * FUNCTION: GET USER WITH PERMISSION                                   *
 * Getting users with a permission, specified by the $permission_key    *
 ************************************************************************/
function get_users_with_permission($permission_key) {
    
    // Open the database connection
    $db = db_open();
    
    if (organizational_hierarchy_extra()) {
        $stmt = $db->prepare("
            SELECT
                `u`.*
            FROM
                `user` u
                INNER JOIN `user_to_team` u2t_bu ON `u2t_bu`.`user_id` = `u`.`value`
                INNER JOIN `business_unit_to_team` bu2t ON `u2t_bu`.`team_id` = `bu2t`.`team_id`
                INNER JOIN `permission_to_user` p2u ON `u`.`value` = `p2u`.`user_id`
                INNER JOIN `permissions` p ON `p`.`id` = `p2u`.`permission_id`
            WHERE
                `bu2t`.`business_unit_id` = :selected_business_unit
                AND `u`.`enabled` = 1
                AND `p`.`key` = :permission_key
            GROUP BY
                `u`.`value`
            ORDER BY
                `u`.`name`;
        ");

        if (!isset($_SESSION['selected_business_unit'])) {
            require_once(realpath(__DIR__ . '/../extras/organizational_hierarchy/index.php'));
            $selected_business_unit = get_selected_business_unit($_SESSION['uid']);
        } else {
            $selected_business_unit = $_SESSION['selected_business_unit'];
        }

        $stmt->bindParam(":selected_business_unit", $selected_business_unit, PDO::PARAM_INT);
        $stmt->bindParam(":permission_key", $permission_key, PDO::PARAM_STR);
    } else {
        $stmt = $db->prepare("
            SELECT
                `u`.*
            FROM
                `user` u
                INNER JOIN `permission_to_user` p2u ON `u`.`value` = `p2u`.`user_id`
                INNER JOIN `permissions` p ON `p`.`id` = `p2u`.`permission_id`
            WHERE
                `u`.`enabled` = 1
                AND `p`.`key` = :permission_key
            GROUP BY 
                `u`.`value`
            ORDER BY
                `u`.`name`;
        ");

        $stmt->bindParam(":permission_key", $permission_key, PDO::PARAM_STR);
    }
    
    $stmt->execute();

    // Store the list in the array
    $users = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Close the database connection
    db_close($db);
    
    return $users;
}

/********************************************************************************
 * FUNCTION: ARRAY ORDERBY                                                      *
 * Reorders an array based on a column value                                    *
 * Ex: $sorted = array_orderby($data, 'volume', SORT_DESC, 'edition', SORT_ASC) *
 ********************************************************************************/
function array_orderby()
{
    $args = func_get_args();
    $data = array_shift($args);
    foreach ($args as $n => $field) {
        if (is_string($field)) {
            $tmp = array();
            foreach ($data as $key => $row)
                $tmp[$key] = $row[$field];
            $args[$n] = $tmp;
            }
    }
    $args[] = &$data;
    call_user_func_array('array_multisort', $args);
    return array_pop($args);
}
/********************************************
 * FUNCTION: GET DATABASE TABLE VALUE BY ID *
 *******************************************/
function get_table_value_by_id($table, $id)
{
    // Open the database connection
    $db = db_open();

    if(field_exists_in_table("value", $table)) {
        $stmt = $db->prepare("SELECT * FROM `{$table}` WHERE `value` = :id");
    } else {
        $stmt = $db->prepare("SELECT * FROM `{$table}` WHERE `id` = :id");
    }
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->execute();

    $result = $stmt->fetch(PDO::FETCH_ASSOC);
    
    db_close($db);
    return $result?$result["name"]:"";    
}
/************************************
 * FUNCTION: ADD CONTRIBUTING RISKS *
 ************************************/
function add_contributing_risks($table, $name, $contributing_risks_id="")
{
    global $lang, $escaper;

    // Open the database connection
    $db = db_open();

    if($table == "likelihood"){
        $table_name = "contributing_risks_likelihood";
        $stmt = $db->prepare("SELECT max(`value`) FROM {$table_name}");
        $stmt->execute();
        $max_value = $stmt->fetch(PDO::FETCH_COLUMN);
        $value = $max_value+1;
        // Add a new value
        $stmt = $db->prepare("INSERT INTO {$table_name} (value, name) VALUES(:value, :name);");
        $stmt->bindParam(":value", $value, PDO::PARAM_INT);
        $stmt->bindParam(":name", $name, PDO::PARAM_STR);
        $stmt->execute();
    } else {
        $table_name = "contributing_risks_impact";
        $stmt = $db->prepare("SELECT max(`value`) FROM {$table_name} WHERE contributing_risks_id = :contributing_risks_id");
        $stmt->bindParam(":contributing_risks_id", $contributing_risks_id, PDO::PARAM_INT);
        $stmt->execute();
        $max_value = $stmt->fetch(PDO::FETCH_COLUMN);
        $value = $max_value+1;
        $stmt = $db->prepare("INSERT INTO {$table_name} (`contributing_risks_id`, `value`, `name`) VALUES (:contributing_risks_id, :value, :name);");
        $stmt->bindParam(":contributing_risks_id", $contributing_risks_id);
        $stmt->bindParam(":value", $value, PDO::PARAM_INT);
        $stmt->bindParam(":name", $name, PDO::PARAM_STR);
        $stmt->execute();
    }

    // Close the database connection
    db_close($db);

    write_log(1000, $_SESSION['uid'] ?? 0, "A new {$table} named \"".$escaper->escapeHtml($name)."\" was created by the \"" . $_SESSION['user'] . "\" user.");

    return $stmt->rowCount();
}
