        }
    } else {
        if(stripos(is_array($filter_value) ? implode('|', $filter_value) : $filter_value, normalize_filter_needle($column_filters[$selected_field_name] ?? '')) === false) {
            $filter_result = true;
        } else {
            $filter_result = false;
        }
    }

    return $filter_result;

}

