/**
 * Compute the final set of JS localization keys for a page render: the keys the
 * page passed explicitly, merged (de-duplicated) with the keys registered for
 * any requested script in the $localization_required_by_scripts map.
 *
 * Pure aside from the array_merge_unique() helper above; directly unit-testable.
 *
 * @param array $required_scripts_or_css         the page's requested script/css tokens
 * @param array $required_localization_keys      keys the page passed explicitly
 * @param array $localization_required_by_scripts map of script token => key list
 * @return array de-duplicated, 0-indexed list of localization keys
 */
function resolve_required_localization_keys(array $required_scripts_or_css, array $required_localization_keys, array $localization_required_by_scripts): array {
    $scripts_with_localization_needs = array_intersect(array_keys($localization_required_by_scripts), $required_scripts_or_css);
    foreach ($scripts_with_localization_needs as $script_with_localization_needs) {
        $required_localization_keys = array_merge_unique($required_localization_keys, $localization_required_by_scripts[$script_with_localization_needs]);
    }
    return $required_localization_keys;
}

/**
 * Build the { key: string } map emitted as the JS `_lang` object for the given
 * localization keys. A key with no entry in $lang falls back to the raw key
 * name, so a missing/misspelled key ships the key text rather than an empty
 * string. Callers that want to surface the drift should log the misses
 * separately (header.php does, at 'debug' level).
 *
 * Pure (no globals, no side effects) so it is directly unit-testable.
 *
 * @param array $keys localization keys to resolve
 * @param array $lang the $lang translation map
 * @return array key => translated-string-or-key-name
 */
function build_js_lang_subset(array $keys, array $lang): array {
    $lang_subset = [];
    foreach ($keys as $key) {
        $lang_subset[$key] = $lang[$key] ?? $key;
    }
    return $lang_subset;
}

/**
 * JSON-encode a `_lang` subset for embedding inside a <script> block. Uses the
 * safe-for-HTML flags — JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS |
 * JSON_HEX_QUOT hex-encode <, >, &, ', " so a stray closing-tag or quote in a
 * translated value can't break out of the <script> or the JS string; and
 * JSON_UNESCAPED_UNICODE keeps non-ASCII readable. This is the security-critical
 * escaper for the JS-localization sink, so it is a named, unit-tested helper.
 *
 * Returns a safe empty object '{}' if json_encode() fails (e.g. invalid UTF-8 in
 * a translation value) so the emitted `var _lang = ...;` — and the sibling
 * `window.L` definition in the same inline block — never becomes malformed JS.
 * JSON_FORCE_OBJECT guarantees an object literal (not '[]') even for an empty
 * subset, so `_lang` is always a JS object.
 *
 * @param array $lang_subset key => string map (see build_js_lang_subset())
 * @return string a valid JS object literal (never false)
 */
function encode_js_lang_subset(array $lang_subset): string {
    $json = json_encode(
        $lang_subset,
        JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_FORCE_OBJECT
    );
    return $json !== false ? $json : '{}';
}

/**
 *
 * It's a helper/wrapper function for changing a column's type from float to double with the required checks and rollback logic.
 *
 * It checks the data of the original and new columns and only allows to do the change if the data in the two columns match.
 * 
 * Since the process of the type change includes deleting the original column the associated indexes are getting dropped as well.
 * There's an option(Default: true) to (re-)create an index for the field. This is a simple index, complex indexes need to be re-created
 * after the function finished.
 *
 * @param PDO $db Database connection
 * @param string $table_name Name of the table
 * @param string $id_column_name Name of ID column of the table
 * @param string $float_column_name Name of the float column that need to be changed to double
 * @param boolean $create_index Whether to (re-)create an index on the column (Default: true)
 * @param boolean $print_messages Print messages during the process(for core) or just return the result(for extras) (Default: true)
 * @param string $double_column_def Specify a different column definition for the double column (Default: 'DOUBLE NOT NULL')
 */
function change_float_column_to_double($db, $table_name, $id_column_name, $float_column_name, $create_index = true, $print_messages = true, $double_column_def = 'DOUBLE NOT NULL') {

    if (getTypeOfColumn($table_name, $float_column_name) == 'float') {
        if ($print_messages) echo "Changing type of column '{$float_column_name}' on table '{$table_name}' from 'float' to 'double'.<br />\n";

        $double_column_name = "dbl_{$float_column_name}";
        
        // Create the new column with a temporary name
        $stmt = $db->prepare("ALTER TABLE `{$table_name}` ADD `{$double_column_name}` {$double_column_def};");
        $stmt->execute();
        
        // Add the data to the temporary column
        $stmt = $db->prepare("UPDATE `{$table_name}` SET `{$double_column_name}` = ROUND(`{$float_column_name}`, 2);");
        $stmt->execute();
        
        // Get float data
        $stmt = $db->prepare("SELECT `{$id_column_name}`, `{$float_column_name}` FROM `{$table_name}`;");
        $stmt->execute();
        $float_data = $stmt->fetchAll(PDO::FETCH_KEY_PAIR);
        
        // Get double data
        $stmt = $db->prepare("SELECT `{$id_column_name}`, `{$double_column_name}` FROM `{$table_name}`;");
        $stmt->execute();
        $double_data = $stmt->fetchAll(PDO::FETCH_KEY_PAIR);

        // Check if the data in the original and the new column matches
        if (!array_equal_assoc($float_data, $double_data)) {
            // Drop the double column because there's an issue with the data
            $stmt = $db->prepare("ALTER TABLE `{$table_name}` DROP COLUMN `{$double_column_name}`;");
            $stmt->execute();

            // Change failed, rolled back
            $success = false;
        } else {
            
            // Data matches, we're good to go
            
            // Drop the original column
            $stmt = $db->prepare("ALTER TABLE `{$table_name}` DROP COLUMN `{$float_column_name}`;");
            $stmt->execute();
            
            // Rename the double column to take the original column's place
            $stmt = $db->prepare("ALTER TABLE `{$table_name}` RENAME COLUMN `{$double_column_name}` TO `{$float_column_name}`;");
            $stmt->execute();

            // Change successful, unnecessary data cleaned up
            $success = true;
        }

        
        
        // Check if the changes were successful. Index (re-)creation is only available if the previous changes succeeded
        // meaning that the original column were dropped(and its index with it)
        if ($success) {
            if ($print_messages) echo "Successfully changed type of column '{$float_column_name}' on table '{$table_name}' from 'float' to 'double'.<br />\n";
            
            // re-create index because indexes on the changed columns are removed
            if ($create_index && !index_exists_on_table($float_column_name, $table_name)) {
                if ($print_messages) echo "Re-creating index '{$float_column_name}' on table '{$table_name}'.<br />\n";
                $stmt = $db->prepare("ALTER TABLE `{$table_name}` ADD INDEX `{$float_column_name}` (`{$float_column_name}`);");
                $stmt->execute();
            }
        } else {
            if ($print_messages) echo "Failed to change type of column '{$float_column_name}' on table '{$table_name}' from 'float' to 'double'. Please contact support@simplerisk.com for assistance.<br />\n";

            return false;
        }
    }

    return true;
}

/************************
 * FUNCTION: DELETE TAG *
 ************************/
function delete_tag($id)
{
    // Open the database connection
    $db = db_open();

    // Delete the tag from the tags table
    $stmt = $db->prepare("DELETE FROM `tags` WHERE id=:id;");
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->execute();

    // Delete the tag from the tags_taggees table
    $stmt = $db->prepare("DELETE FROM `tags_taggees` WHERE tag_id=:id;");
    $stmt->bindParam(":id", $id, PDO::PARAM_INT);
    $stmt->execute();

    // Close the database connection
    db_close($db);
}

/*****************************
 * FUNCTION: DELETE ALL TAGS *
 *****************************/
function delete_all_tags($type)
{
    global $tag_types;
    if ($type === 'all' || in_array($type, $tag_types)) {

        // Open the database connection
        $db = db_open();

        if ($type === 'all') {
            // Delete all tags
            $stmt = $db->prepare("DELETE FROM `tags`;");
            $stmt->execute();
            // Delete all tags_taggees
            $stmt = $db->prepare("DELETE FROM `tags_taggees`;");
            $stmt->execute();
        } else {
            // Delete all tags with this type
            $stmt = $db->prepare("DELETE FROM `tags` WHERE id IN (SELECT tag_id FROM tags_taggees WHERE type=:type);");
            $stmt->bindParam(":type", $type, PDO::PARAM_STR);
            $stmt->execute();
            // Delete all tags_taggees with this type
            $stmt = $db->prepare("DELETE FROM `tags_taggees` WHERE type=:type;");
            $stmt->bindParam(":type", $type, PDO::PARAM_STR);
            $stmt->execute();
        }

        // Close the database connection
        db_close($db);
    }
}

/**
 * Gets the header(first row) of a spreadsheet's first sheet.
 *
 * THEORETICALLY can recognize/handle csv/ods files, but it's not tested
 * Update it later if you need it be able to get the header of other sheets than the first
 *
 * @param string $filePath path to the file
 * @return array the header
 */
function getSpreadsheetHeader($filePath) {
    $header = [];
    // Create the reader based on the extension of the file
    $reader = OpenSpout\Reader\Common\Creator\ReaderFactory::createFromFile($filePath);
    // Open the reader
    $reader->open($filePath);

    // Iterate through the sheets
    foreach ($reader->getSheetIterator() as $sheet) {
        foreach ($sheet->getRowIterator() as $row) {
            // Get the first row
            $header = $row->toArray();
            break;
        }
    }
    $reader->close();
    return $header;
}

/**
 * Gets the data of a spreadsheet's first sheet.
 *
 * THEORETICALLY can recognize/handle csv/ods files, but it's not tested
 * Update it later if you need it be able to get the data of other sheets than the first
 *
 * @param string $filePath path to the file
 * @return array the data
 */
function getSpreadsheetData($filePath) {
    // Create the reader based on the extension of the file
    $reader = OpenSpout\Reader\Common\Creator\ReaderFactory::createFromFile($filePath);
    // Open the reader
    $reader->open($filePath);
    
    // Variable to store the data in
    $data = [];
    
    // Iterate through the sheets
    foreach ($reader->getSheetIterator() as $sheet) {
        foreach ($sheet->getRowIterator() as $row) {
            // Get the first row
            $data []= $row->toArray();
        }
        // Make sure only the first sheet is processed 
        break;
    }
    $reader->close();
    return $data;
}

/*****************************
 * FUNCTION: FETCH COUNTRIES *
 *****************************/
function fetchCountries(?callable $fetcher = null): array
{
    // $fetcher is an injectable seam for tests only -- production callers never
    // pass an argument, so this always resolves to the real API call. Mirrors
    // the same seam on core_countries_update's queue_check (includes/jobs/core_countries_update.php).
    $fetcher ??= 'fetchCountriesFromAPI';

    // Open the database connection
    $db = db_open();

    $setting = get_setting('countries_cache', db: $db);
    $cache = $setting ? json_decode($setting, true) : null;
    // !empty($cache['countries']) -- not just isset() -- so a cache entry
    // that was itself written from a failed fetch (see the write side below,
    // and the bug this guards against) is treated as invalid and retried
    // immediately instead of being served, and stuck being re-served,
    // forever.
    $cache_valid = $cache && isset($cache['fetched_at']) && !empty($cache['countries']);

    if ($cache_valid) {
        // @phan-suppress-next-line PhanTypeArraySuspiciousNullable -- $cache_valid guarantees $cache is array with these keys set
        $age = time() - $cache['fetched_at'];
        if ($age >= 24 * 60 * 60) { // cache older than 1 day
            queue_countries_refresh_if_not_already_queued($db);
        }

        // Return cached countries immediately
        // @phan-suppress-next-line PhanTypeArraySuspiciousNullable -- $cache_valid guarantees $cache is array with 'countries' key set
        return $cache['countries'];
    }

    // Cache missing or invalid. If a live fetch attempt failed recently,
    // don't retry it inline on THIS request -- restcountries.com's v3.1
    // endpoint is currently permanently broken (301-redirects to a
    // deprecation notice), so without this, every single request would
    // synchronously retry a live HTTPS call (with its own internal retries)
    // that's essentially guaranteed to fail again. Serve the fallback
    // immediately and let the background refresh (enqueued below, same as
    // the stale-cache path above) retry on its own schedule instead. A
    // short window distinct from the 24h success-staleness TTL: a genuine
    // outage should degrade to "fallback + occasional background retry,"
    // not "every request blocks on a doomed live HTTP call."
    $last_failed_at = (int) get_setting('countries_cache_last_failed_at', 0, db: $db);
    if ($last_failed_at && (time() - $last_failed_at) < (5 * 60)) {
        queue_countries_refresh_if_not_already_queued($db);
        db_close($db);
        return get_fallback_countries();
    }

    $countries = $fetcher();

    if (!empty($countries)) {
        // Only cache a genuine success. Writing an empty result here is what
        // stranded this field before: it looked identical to a real cache
        // entry, so every request (and every 24h background refresh) kept
        // serving -- and re-confirming -- the same empty list indefinitely.
        update_setting('countries_cache', json_encode([
            'fetched_at' => time(),
            'countries' => $countries
        ]), db: $db);

        db_close($db);

        return $countries;
    }

    // The live fetch failed (or, as with restcountries.com's now-deprecated
    // v3.1 endpoint, the third-party API itself is unusable). Record the
    // failure (read by the negative-cache check above) instead of caching
    // the empty result under 'countries_cache' itself -- that's what
    // stranded this field permanently before this fix.
    update_setting('countries_cache_last_failed_at', (string) time(), db: $db);
    queue_countries_refresh_if_not_already_queued($db);

    db_close($db);

    return get_fallback_countries();
}

/**
 * Enqueue a core_countries_update background refresh unless one is already
 * pending/in-progress. Shared by fetchCountries()'s stale-cache path and its
 * two live-fetch-failure paths so recovery from a broken restcountries.com
 * happens asynchronously instead of on someone's page load, without
 * duplicating the existing-task dedup check three times.
 */
function queue_countries_refresh_if_not_already_queued(PDO $db): void
{
    $existing_tasks = get_queue_items($db, 'core_countries_update', ['pending', 'in_progress']);
    if (empty($existing_tasks)) {
        $queue_task_payload = [
            'triggered_at' => time(),
        ];
        queue_task($db, 'core_countries_update', $queue_task_payload, 25, 5, 3600);
        write_debug_log("Queued core_countries_update task", "info");
    } else {
        write_debug_log("core_countries_update task already queued or in progress", "info");
    }
}

/**
 * Pure decode-and-group step for fetchCountriesFromAPI()'s response body,
 * lifted out so the non-list-response guard and the grouping/sort logic are
 * unit-testable without a live network call (CLAUDE.md: "refactor the
 * testable decision out into a pure helper and test that").
 *
 * @return array<string, string[]>|null null when $decoded is not a JSON
 *         *array* (e.g. restcountries.com's live v3.1 response: a JSON
 *         object -- `{"success":false,"data":null,"errors":[...]}` --
 *         confirmed by requesting the real endpoint, not a list of country
 *         records) -- the caller is responsible for logging that outcome.
 */
function parse_countries_api_response($decoded): ?array
{
    // A 200 response body that isn't a JSON *array* -- a bare scalar/null
    // (invalid JSON), or a JSON *object* like restcountries.com's
    // deprecation-notice body -- would otherwise reach foreach() below.
    // json_decode(..., true) turns a JSON object into a PHP associative
    // array, which is_array() alone cannot tell apart from a real list of
    // country records: without the array_is_list() half of this guard, that
    // object's own values (an error message string, a null, ...) get
    // foreach'd as if they were country entries, and the `?? 'Unknown'`
    // fallbacks turn a should-be-empty result into a non-empty
    // {"Unknown": ["Unknown", ...]} grouping that then gets cached and
    // served as if it were real data instead of falling through to the
    // fallback list.
    if (!is_array($decoded) || !array_is_list($decoded)) {
        return null;
    }

    $grouped_countries = [];
    foreach ($decoded as $country) {
        $region = $country['region'] ?? 'Unknown';
        $name = $country['name']['common'] ?? 'Unknown';
        $grouped_countries[$region][] = $name;
    }

    // Sort regions and countries alphabetically
    ksort($grouped_countries);
    foreach ($grouped_countries as &$region_countries) {
        sort($region_countries);
    }

    return $grouped_countries;
}

/**************************************
 * FUNCTION: FETCH COUNTRIES FROM API *
 **************************************/
function fetchCountriesFromAPI(): array
{
    $http_options = [
        'method' => 'GET',
        'header' => ["Content-Type: application/json"],
        'timeout' => 5,
    ];

    $validate_ssl = ssl_external_verify_enabled();

    $url = 'https://restcountries.com/v3.1/all?fields=name,region';

    $response = fetch_url_content("stream", $http_options, $validate_ssl, $url);
    if (!is_array($response) || $response['return_code'] !== 200) {
        write_debug_log("SimpleRisk was unable to connect to " . $url, "error");
        return [];
    }

    $grouped_countries = parse_countries_api_response(json_decode($response['response'], true));

    if ($grouped_countries === null) {
        write_debug_log("SimpleRisk received an unexpected non-array response from " . $url, "warning");
        return [];
    }

    return $grouped_countries;
}

/*******************************************************************************************
 * FUNCTION: UPDATE POSTED SETTINGS VALUES                                                 *
 * @param $parameter_array: An array containing the list of posted parameters to process   *
 * @param $settings_prefix: A prefix to apply to values written back to the settings table *
 *******************************************************************************************/
function update_posted_settings_values($parameter_array, $settings_prefix)
{
    // Open the database connection
    $db = db_open();

    // Get the list of all settings with the specified prefix
    $stmt = $db->prepare("SELECT name, value FROM `settings` WHERE name like '{$settings_prefix}%';");
    $stmt->execute();
    $settings_table = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Rewrite the array as name value pairs
    $settings = [];
    foreach ($settings_table as $setting)
    {
        $settings[$setting['name']] = $setting['value'];
    }

    // Close the database connection
    db_close($db);

    // For each parameter in the array get the parameter and configuration
    foreach ($parameter_array as $parameter => $configuration)
    {
        // Create a setting name for this parameter
        $setting_name = $settings_prefix . $parameter;

        // If that parameter was POSTed
        if (isset($_POST[$parameter]))
        {
            // Get the POSTed value
            $value = $_POST[$parameter];

            // JSON encode the POSTed value
            $value_json = json_encode($value);

            // Update the setting with the JSON encoded value
            update_setting($setting_name, $value_json);
        }
        // If the parameter was not POSTed
        else
        {
            // Retrieve the existing value from the settings table
            $value = $settings[$setting_name] ?? null;

            // Decode only if a value exists
            if ($value !== null && $value !== '') {
                $decoded = json_decode($value, true); // return arrays
                $value = (json_last_error() === JSON_ERROR_NONE) ? $decoded : $value;
            }

        }

        // Add the value to the parameter array
        $parameter_array[$parameter]['value'] = $value;
    }

    // Return the parameter array
    return $parameter_array;
}

/******************************************************************************************
 * FUNCTION: RETRIEVE SETTINGS VALUES                                                     *
 * @param $parameter_array: An array containing the list of posted parameters to process  *
 * @param $settings_prefix: A prefix to apply to values retrieved from the settings table *
 ******************************************************************************************/
function retrieve_settings_values($parameter_array, $settings_prefix)
{
    // Open the database connection
    $db = db_open();

    // Get the list of all settings with the specified prefix
    $stmt = $db->prepare("SELECT name, value FROM `settings` WHERE name like '{$settings_prefix}%';");
    $stmt->execute();
    $settings_table = $stmt->fetchAll(PDO::FETCH_ASSOC);

    // Rewrite the array as name value pairs
    $settings = [];
    foreach ($settings_table as $setting)
    {
        $settings[$setting['name']] = isset($setting['value']) ? json_decode($setting['value']) : null;
    }

    // Close the database connection
    db_close($db);

    // For each parameter in the array get the parameter and configuration
    foreach ($parameter_array as $parameter => $configuration)
    {
        // Create a setting name for this parameter
        $setting_name = $settings_prefix . $parameter;

        // Add the value from the settings table to the parameter array
        $parameter_array[$parameter]['value'] = $settings[$setting_name];
    }

    // Return the updated parameter array
    return $parameter_array;
}

/**
 * Helper function to sleep for milliseconds instead of seconds sleep() does
 * 
 * @param int $millisecond
 */
function wait(int $millisecond = 0) {
    if (0 !== $millisecond) {
        $seconds = (int) ($millisecond / 1000);
        $nanoSeconds = ($millisecond % 1000) * 1000000;
        time_nanosleep($seconds, $nanoSeconds);
    }
}

/**
 * Sets the default status of the user's layout. If set to true then this layout will be used for users who doesn't have a custom layout set
 * 
 * @param int $user_id
 * @param string $layout_name
 * @param boolean $new_default_status
 */
function set_layout_default_status($user_id, $layout_name, $new_default_status) {
    // Open the database connection
    $db = db_open();

    if ($new_default_status) {
        // To update in a single db call to prevent having no default or having two defaults at the same time
        $stmt = $db->prepare("UPDATE `layouts` l SET `l`.`default` = CASE WHEN `l`.`user_id` = :user_id AND `l`.`layout_name` = :layout_name THEN 1 ELSE NULL END WHERE `l`.`layout_name` = :layout_name ORDER BY `l`.`default` DESC;");
    } else {
        $stmt = $db->prepare("UPDATE `layouts` l SET `l`.`default` = NULL WHERE `l`.`user_id` = :user_id AND `l`.`layout_name` = :layout_name;");
    }

    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":layout_name", $layout_name, PDO::PARAM_STR);
    $stmt->execute();

    // Close the database connection
    db_close($db);
}

/**
 * Saves a layout or updates it if the user already has one custom config for that layout.
 *
 * @param int $user_id
 * @param string $layout_name
 * @param string $layout
 */
function save_layout_for_user($user_id, $layout_name, $layout, $default = false) {
    // Open the database connection
    $db = db_open();

    // To update in a single db call to prevent having no default or having two defaults at the same time
    $stmt = $db->prepare("
        INSERT INTO `layouts`
            (`user_id`, `layout_name`, `layout`)
        VALUES
            (:user_id, :layout_name, :layout)
        ON DUPLICATE KEY UPDATE
            `layout` = :layout;
    ");

    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":layout_name", $layout_name, PDO::PARAM_STR);
    $stmt->bindParam(":layout", $layout, PDO::PARAM_STR);
    $stmt->execute();

    if ($default) {
        set_layout_default_status($user_id, $layout_name, true);
    }

    // Close the database connection
    db_close($db);
}

/**
 * Drop widgets the current user lacks permission for from a layout JSON string,
 * so a permission-adaptive default (e.g. the 'home' layout) never serves tiles
 * that would 400 on fetch and spam permission-denied alerts. Widgets with an
 * empty required_permission are always kept, so layouts whose widgets are all
 * unpermissioned (every layout except 'home' today) are unaffected.
 */
function filter_layout_json_by_permission($layout_json) {
    global $ui_layout_widget_config;
    $entries = json_decode($layout_json, true);
    if (!is_array($entries)) {
        return $layout_json;
    }
    $filtered = array_values(array_filter($entries, function ($entry) use ($ui_layout_widget_config) {
        $name = $entry['name'] ?? '';
        $required = $ui_layout_widget_config[$name]['required_permission'] ?? '';
        return empty($required) || check_permission($required);
    }));
    return json_encode($filtered);
}

/**
 * Gets the default layout.
 * If there's a custom layout marked as 'default' for that layout, then it'll return that,
 * otherwise it'll return the original default layout.
 *
 * @param string $layout_name
 */
function get_default_layout($layout_name) {
    // Open the database connection
    $db = db_open();

    // Gets the custom layout saved by the user
    $stmt = $db->prepare("SELECT `layout` FROM `layouts` WHERE `layout_name` = :layout_name AND `default` = '1';");

    $stmt->bindParam(":layout_name", $layout_name, PDO::PARAM_STR);
    $stmt->execute();

    $layout = $stmt->fetchColumn();

    if (!isset($layout) || !$layout) {
        global $ui_layout_config;
        $layout = json_encode($ui_layout_config[$layout_name]['default_layout']);
    }

    // Close the database connection
    db_close($db);

    return filter_layout_json_by_permission($layout);
}

/**
 * Gets the user's saved custom layout for a layout. If there's no custom layout saved for the user, but there's a
 * custom layout marked as 'default' for that layout, then it'll return that, otherwise it'll return the original default layout.
 *
 * @param string $layout_name
 * @param int $user_id
 * 
 * @return array{0:string,1:bool,2:bool} [$layout, $is_custom, $default_set_by_user]
 */
function get_layout_for_user($layout_name, $user_id = null) {
    // Open the database connection
    $db = db_open();

    // Use the currently authenticated user by default
    $user_id = $user_id ?? $_SESSION['uid'];
    $is_admin = is_admin($user_id);

    // Gets the custom layout saved by the user
    $stmt = $db->prepare("SELECT `layout`" . ($is_admin ? ", `default`" : "") . " FROM `layouts` WHERE `user_id` = :user_id AND `layout_name` = :layout_name;");

    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":layout_name", $layout_name, PDO::PARAM_STR);
    $stmt->execute();

    $result = $stmt->fetch();

    if (!isset($result) || !$result || !isset($result['layout']) || !$result['layout']) {
        $layout = get_default_layout($layout_name);
        $is_custom = false;
    } else {
        // Filter the saved layout by permission too — a user who saved a layout
        // and later lost a permission (or whose saved layout holds a since-forbidden
        // tile) must not be served that tile, or the widget endpoint 400s and spams
        // permission-denied alerts. get_default_layout() already filters; the
        // saved-custom path must match it.
        $layout = filter_layout_json_by_permission($result['layout']);
        $is_custom = true;
    }

    // Check if this is the current default for this layout type and it's set by this user
    $default_set_by_user = $is_custom && isset($result['default']) && $result['default'];

    // Close the database connection
    db_close($db);

    return [$layout, $is_custom, $default_set_by_user];
}

/**
 * Deletes custom layout defined by the user for the specified layout
 * 
 * @param string $layout_name
 * @param boolean $user_id
 */
function delete_layout_for_user($layout_name, $user_id = null) {
    // Open the database connection
    $db = db_open();

    // Use the currently authenticated user as default
    $user_id = $user_id ?? $_SESSION['uid'];

    // Deletes the custom layout saved by the user
    $stmt = $db->prepare("DELETE FROM `layouts` WHERE `user_id` = :user_id AND `layout_name` = :layout_name;");

    $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
    $stmt->bindParam(":layout_name", $layout_name, PDO::PARAM_STR);
    $stmt->execute();

    // Close the database connection
    db_close($db);
}

/**
 * Get the configurations for the widgets allowed for a layout type
 * 
 * @param string $layout_name
 * @return array<string,array> map of widget name => widget configuration
 */
function get_widget_configuration_for_layout_name($layout_name, $is_custom = false) {
    global $lang, $escaper, $ui_layout_config, $ui_layout_widget_config;

    $widget_configurations = [];

    foreach ($ui_layout_config[$layout_name][$is_custom ? 'available_custom_widgets' : 'available_widgets'] as $widget_name) {
        // A layout may list a widget registered only by an Extra (e.g. the
        // Incident widgets on the universal home dashboard). When that Extra is
        // inactive its config isn't registered, so skip it rather than fatal.
        if (!isset($ui_layout_widget_config[$widget_name])) {
            continue;
        }
        $widget_config = $ui_layout_widget_config[$widget_name];

        // Permission-adaptive: hide widgets the current user lacks rights to,
        // so forbidden widgets never appear in the add-widget picker.
        if (!empty($widget_config['required_permission']) && !check_permission($widget_config['required_permission'])) {
            continue;
        }

        $widget_config['name'] = $widget_name;
        // Raw lang value: this is consumed client-side via jQuery .text() (UILayout.php),
        // which sets textContent and does its own escaping. Pre-escaping here would
        // double-encode — e.g. "What's Next?" would render literally as "What&#039;s Next?".
        $widget_config['localization'] = $lang[$widget_config['localization_key']];
        $widget_config['layout'] = $layout_name;

        // Domain group for the add-widget picker's section headers, derived from
        // the widget's required permission. Charts/KPIs/lists inherit their
        // domain; cross-cutting widgets (Getting Started, What's Next) fall to
        // General. Ordered so the sections read General → Risk → Compliance →
        // Governance → Incident (General first, then the domain groups).
        $group_map = [
            'riskmanagement' => ['RiskManagement', 1],
            'compliance'     => ['Compliance', 2],
            'governance'     => ['Governance', 3],
            'im_reporting'   => ['IncidentManagement', 4],
        ];
        [$group_key, $group_order] = $group_map[$widget_config['required_permission'] ?? ''] ?? ['General', 0];
        $widget_config['group'] = $lang[$group_key] ?? $group_key;
        $widget_config['group_order'] = $group_order;

        $defaults = $widget_config['defaults'];

        unset($widget_config['localization_key']);
        unset($widget_config['required_permission']);
        unset($widget_config['defaults']);

        $widget_config = [...$widget_config, ...$defaults];

        $widget_configurations[$widget_name]= $widget_config;
    }

    return $widget_configurations;
}

/*************************************
 * FUNCTION: WHATS NEXT BAND WEIGHT  *
 *************************************/
// Priority weight for a "What's Next?" item band. Lower = higher priority.
function whats_next_band_weight($band)
{
    switch ($band) {
        case 'overdue':       return 0;
        case 'due_soon':      return 1;
        case 'setup':         return 2;
        case 'informational': return 3;
        default:              return 99;
    }
}

/*************************************
 * FUNCTION: SORT WHATS NEXT ITEMS   *
 *************************************/
// Sort feed items by band weight ascending, then by count descending.
// Pure: returns a new array, does not mutate the input.
function sort_whats_next_items($items)
{
    $sorted = $items;
    usort($sorted, function ($a, $b) {
        $wa = whats_next_band_weight($a['band'] ?? '');
        $wb = whats_next_band_weight($b['band'] ?? '');
        if ($wa !== $wb) {
            return $wa <=> $wb;
        }
        return ($b['count'] ?? 0) <=> ($a['count'] ?? 0);
    });
    return $sorted;
}

/*********************************
 * FUNCTION: GET WHATS NEXT ITEMS *
 *********************************/
// Assemble the "What's Next?" feed from all v1 sources. Each item is gated by
// permission and by live state; setup items appear only while their
// prerequisite is missing. Returns a priority-sorted array.
function get_whats_next_items($domain = null)
{
    $items = [];

    // Setup: register the instance (admin only)
    if (!empty($_SESSION['admin']) && get_setting('registration_registered') == 0) {
        $items[] = ['key' => 'register_instance', 'label_key' => 'WhatsNextRegisterInstance',
            'cta_url' => '../admin/register.php', 'band' => 'setup', 'domain' => 'setup', 'count' => 1];
    }

    // Setup: install the Secure Controls Framework — download the extra from the
    // Register/Upgrade page. Shown once the instance is registered (registration
    // grants the SCF Extra) but the extra's files are not yet present.
    if (!empty($_SESSION['admin']) && get_setting('registration_registered') == 1
        && !is_extra_installed('complianceforgescf')) {
        $items[] = ['key' => 'install_scf', 'label_key' => 'WhatsNextInstallSCF',
            'cta_url' => '../admin/register.php', 'band' => 'setup', 'domain' => 'setup', 'count' => 1];
    }

    // Setup: activate the Secure Controls Framework — turn on the installed extra
    // from the SCF admin page. Shown once the files are present but not yet active.
    if (!empty($_SESSION['admin']) && is_extra_installed('complianceforgescf')
        && function_exists('complianceforge_scf_extra') && !complianceforge_scf_extra()) {
        $items[] = ['key' => 'activate_scf', 'label_key' => 'WhatsNextActivateSCF',
            'cta_url' => '../admin/securecontrolsframework.php', 'band' => 'setup', 'domain' => 'setup', 'count' => 1];
    }

    // Setup: enable applicable frameworks — once the SCF is active but no framework
    // has been enabled (activated) yet.
    if (!empty($_SESSION['admin']) && function_exists('complianceforge_scf_extra')
        && complianceforge_scf_extra() && get_frameworks_count(1) == 0) {
        $items[] = ['key' => 'enable_frameworks', 'label_key' => 'WhatsNextEnableFrameworks',
            'cta_url' => '../admin/securecontrolsframework.php', 'band' => 'setup', 'domain' => 'setup', 'count' => 1];
    }

    // Setup: take a self-assessment — once the SCF is active with its control data
    // present, and the calling user has not started one yet.
    if (check_permission('assessments') && get_setting('registration_registered') == 1
        && function_exists('complianceforge_scf_extra') && complianceforge_scf_extra()
        && table_exists('scf_controls') && table_exists('scf_frameworks')) {
        $sa_taken = 0;
        if (table_exists('self_assessments')) {
            $sa_db = db_open();
            $sa_stmt = $sa_db->prepare("SELECT COUNT(*) FROM `self_assessments` WHERE `started_by` = :uid");
            $sa_stmt->execute([':uid' => (int)($_SESSION['uid'] ?? 0)]);
            $sa_taken = (int)$sa_stmt->fetchColumn();
            db_close($sa_db);
        }
        if ($sa_taken == 0) {
            $items[] = ['key' => 'take_self_assessment', 'label_key' => 'WhatsNextTakeSelfAssessment',
                'cta_url' => '../assessments/index.php', 'band' => 'setup', 'domain' => 'risk', 'count' => 1];
        }
    }

    // Setup: configure AI — admin only, until the AI context has been saved.
    // Mirrors the Getting Started 'ai' step (same admin gate + ai_context_last_saved
    // completion signal) so the two stay in lock-step.
    if (!empty($_SESSION['admin']) && empty(get_setting('ai_context_last_saved'))) {
        $items[] = ['key' => 'configure_ai', 'label_key' => 'WhatsNextConfigureAI',
            'cta_url' => '../admin/artificial_intelligence_core.php', 'band' => 'setup', 'domain' => 'setup', 'count' => 1];
    }

    // Risk-management items
    if (check_permission('riskmanagement')) {

        // Setup: submit the first risk (no risks yet)
        if ((get_open_risks() + get_closed_risks()) == 0) {
            $items[] = ['key' => 'submit_first_risk', 'label_key' => 'WhatsNextSubmitFirstRisk',
                'cta_url' => '../management/index.php', 'band' => 'setup', 'domain' => 'risk', 'count' => 1];
        }

        // Work: risks needing review → the Review Risk action queue (Task 22
        // retired the separate management_review.php page). Home lives in
        // /reports/, so links to other top-level dirs are relative with ../.
        $unreviewed = get_unreviewed_open_risk_count();
        if ($unreviewed > 0) {
            $items[] = ['key' => 'unreviewed_risks', 'label_key' => 'WhatsNextUnreviewedRisks',
                'cta_url' => '../management/review_risk.php', 'band' => 'due_soon', 'domain' => 'risk', 'count' => $unreviewed];
        }

        // Work: risks needing mitigation → the Review Risk action queue (Task 22
        // retired the separate plan_mitigations.php page)
        $unmitigated = get_unmitigated_open_risk_count();
        if ($unmitigated > 0) {
            $items[] = ['key' => 'unmitigated_risks', 'label_key' => 'WhatsNextUnmitigatedRisks',
                'cta_url' => '../management/review_risk.php', 'band' => 'due_soon', 'domain' => 'risk', 'count' => $unmitigated];
        }
    }

    // Governance items
    if (check_permission('governance')) {
        // Setup: load a control framework (none active yet)
        if (get_frameworks_count(1) == 0) {
            $items[] = ['key' => 'load_framework', 'label_key' => 'WhatsNextLoadFramework',
                'cta_url' => '../governance/index.php', 'band' => 'setup', 'domain' => 'governance', 'count' => 1];
        }
    }

    // Compliance items
    if (check_permission('compliance')) {
        // Work: compliance audits ready to initiate
        $to_initiate = get_tests_to_auto_initiate();
        $initiate_count = is_array($to_initiate) ? count($to_initiate) : 0;
        if ($initiate_count > 0) {
            $items[] = ['key' => 'initiate_audits', 'label_key' => 'WhatsNextInitiateAudits',
                'cta_url' => '../compliance/index.php', 'band' => 'due_soon', 'domain' => 'compliance', 'count' => $initiate_count];
        }
    }

    // Dismissing a card in the Getting Started ("Welcome to SimpleRisk") widget
    // also hides its equivalent What's Next setup item — the onboarding dismissal
    // is shared. Only the setup steps have a Getting Started counterpart; work
    // items (risks to review/mitigate, audits to initiate) are not mapped.
    if (table_exists('getting_started_dismissed')) {
        $wn_to_gs = [
            'register_instance'    => 'register',
            'install_scf'          => 'install_scf',
            'activate_scf'         => 'activate_scf',
            'enable_frameworks'    => 'enable_frameworks',
            'take_self_assessment' => 'self_assessment',
            'submit_first_risk'    => 'submit_risks',
            'configure_ai'         => 'ai',
        ];
        $gsd_db   = db_open();
        $gsd_stmt = $gsd_db->prepare("SELECT `step_key` FROM `getting_started_dismissed` WHERE `user_id` = :uid");
        $gsd_stmt->execute([':uid' => (int)($_SESSION['uid'] ?? 0)]);
        $dismissed = $gsd_stmt->fetchAll(PDO::FETCH_COLUMN) ?: [];
        db_close($gsd_db);

        if ($dismissed) {
            $items = array_values(array_filter($items, function ($i) use ($wn_to_gs, $dismissed) {
                $gs = $wn_to_gs[$i['key']] ?? null;
                return $gs === null || !in_array($gs, $dismissed, true);
            }));
        }
    }

    // Optionally scope to a single dashboard's domain (compliance/governance/risk
    // dashboards show only their own items; the home dashboard passes null = all).
    if ($domain !== null) {
        $items = array_values(array_filter($items, function ($i) use ($domain) {
            return ($i['domain'] ?? null) === $domain;
        }));
    }

    return sort_whats_next_items($items);
}


/**
 * Creates a new custom widget or updates an existing one.
 * If a user tries to update a widget that wasn't created by them, a new one will be created.
 * 
 * @param int $user_id ID of the user who submitted the data
 * @param int $id ID of the widget. Only used if it's not a new widget
 * @param string $type Type of the widget.
 * @param bool $new Whether it's a new widget or an update to an existing one
 * @param string $data Data of the widget that needs to be saved
 * 
 * @return int ID of the custom widget
 */
function save_custom_ui_widget_data($user_id, $id, $type, $new, $data) {

    $db = db_open();
    
    // Only check this if it's a pre-existing widget
    if (!$new) {

        // Check if the custom widget with the provided ID exists and was created by the user
        $stmt = $db->prepare("SELECT 5 FROM `custom_ui_widgets` WHERE `id` = :id AND `created_by` = :user_id;");
        $stmt->bindParam(":id", $id, PDO::PARAM_INT);
        $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
        $stmt->execute();
    
        $result = $stmt->fetchColumn();
        
        // If it doesn't exist or wasn't created by the user then it can't be updated, a new one will be created for the user
        $can_update_widget = !empty($result) && (int)$result === 5;
    
    } else {
        // If it's a new widget, it can't be updated, have to create a new one
        $can_update_widget = false;
    }

    if ($can_update_widget) {
        // update the widget's data
        $stmt = $db->prepare("UPDATE `custom_ui_widgets` SET `data` = :data WHERE `id` = :id AND `created_by` = :user_id;");
        $stmt->bindParam(":data", $data, PDO::PARAM_STR);
        $stmt->bindParam(":id", $id, PDO::PARAM_INT);
        $stmt->bindParam(":user_id", $user_id, PDO::PARAM_INT);
        $stmt->execute();
    } else {
        // create a new entry for the widget's data
        $stmt = $db->prepare("INSERT INTO `custom_ui_widgets`(`type`, `data`, `created_by`) VALUES (:type, :data, :created_by);");
        $stmt->bindParam(":type", $type, PDO::PARAM_STR);
        $stmt->bindParam(":data", $data, PDO::PARAM_STR);
        $stmt->bindParam(":created_by", $user_id, PDO::PARAM_INT);
        $stmt->execute();

        // Get the new widget's ID so we can return it
        $id = $db->lastInsertId();
    }

    // Close the database connection
    db_close($db);

    // Return the new or existing widget's ID
    return $id;
}



/*
 * Sanitize and clean JSON response (from Claude)
 */
function sanitize_json_response($json_string) {
    // First, decode any unicode escapes
    $json_string = preg_replace_callback('/\\\\u([0-9a-fA-F]{4})/', function ($match) {
        return mb_convert_encoding(pack('H*', $match[1]), 'UTF-8', 'UCS-2BE');
    }, $json_string);

    // Remove any potential UTF-8 BOM and control characters
    $json_string = preg_replace('/[\x00-\x1F\x80-\xFF]/', '', $json_string);

    // Remove any potential leading/trailing whitespace
    $json_string = trim($json_string);

    // Extract the actual content
    if (preg_match('/\{.*\}/s', $json_string, $matches)) {
        $json_string = $matches[0];
    }

    // Parse the content into an array
    $data = [
        'details' => '',
        'mitigation' => ''
    ];

    // Extract details and mitigation using regex
    if (preg_match('/"details":\s*"([^"]+)"/', $json_string, $matches)) {
        $data['details'] = str_replace('\n', "\n", $matches[1]);
    }
    if (preg_match('/"mitigation":\s*"([^"]+)"/', $json_string, $matches)) {
        $data['mitigation'] = str_replace('\n', "\n", $matches[1]);
    }

    // Create a clean JSON string
    return json_encode([
        'details' => trim($data['details']),
        'mitigation' => trim($data['mitigation'])
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
}

/***************************
 * FUNCTION: IS VALID JSON *
 ***************************/
function isValidJson($string, $type = 'array') {
    // Decode the JSON string
    $decoded = json_decode($string, true); // true = decode as associative array

    // Check for JSON errors
    if (json_last_error() !== JSON_ERROR_NONE) {
        return false; // Invalid JSON
    }

    // Check if the decoded value matches the expected type
    if ($type === 'array' && is_array($decoded)) {
        return true;
    } elseif ($type === 'object' && is_object(json_decode($string))) {
        return true;
    }

    return false; // Valid JSON but not the expected type
}

/********************************************
 * FUNCTION: SANITIZE ARRAY FOR JSON ENCODE *
 ********************************************/
function sanitze_array_for_json_encode($array)
{
    // If we were provided with a PHP array
    if (is_array($array))
    {
        // Recursively traverse the array
        array_walk_recursive($array, function (&$item)
        {
            // If the item is a string
            if (is_string($item))
            {
                // Remove invalid characters
                $item = preg_replace('/[\x00-\x1F\x80-\xFF]/', '', $item);
            }
        });

        // Return the updated array
        return $array;
    }
    // Return false if this is not an array
    else return false;
}

/**
 * A helper function to centralize the logging for toggling extras on or off.
 * 
 * @param string $extra Localization key for the name of the extra
 * @param boolean $on Activated state of the extra (true = ON, false = OFF) Default: true
 */
function audit_log_extra_toggle(string $extra, bool $on = true) {
    global $lang;

    $on_off = $on ? 'On' : 'Off';

    if (!empty($_SESSION['uid']) && !empty($_SESSION['user'])) {
        write_log(1000, $_SESSION['uid'] ?? 0, _lang("ExtraToggled{$on_off}", ['extra_name' => $lang[$extra], 'user' => $_SESSION['user']]), 'extra');
    } else {
        write_log(1000, 0, _lang("ExtraTechnicalToggled{$on_off}", ['extra_name' => $lang[$extra]]), 'extra');
    }
}

/**
 * Deleting a single backup entry and its files 
 *
 * @param array $backup_to_delete a single entry from the `backups` table`
 * @param boolean $called_from_ui whether it was called from the UI. Will display toasts if true, add debug messages if false.
 */
function delete_backup($backup_to_delete, $called_from_ui = false) {

    // Initializing variables
    $parent_directory = dirname($backup_to_delete['app_zip_file_name']);
    $missing_backup_directory = !is_dir($parent_directory);
    $backup_directory_delete_successful = false;

    $success = false;
    $message = "";

    // If the backup directory exists
    if (!$missing_backup_directory) {

        // Remove all files from this directory
        array_map('unlink', glob("$parent_directory/*.*"));

        // Remove the directory
        rmdir($parent_directory);

        // Check if the directory was successfully removed
        $backup_directory_delete_successful = !is_dir($parent_directory);
        if ($backup_directory_delete_successful) {
            if ($called_from_ui) {
                global $lang;
                $message = $lang['DeleteBackup_Success'];
            } else {
                $message = _lang("DeleteBackup_Expired_Success", ['backup_remove' => (int)get_setting('backup_remove'), 'parent_directory' => $parent_directory]);
            }

            $success = true;
        } else {
            $message = _lang("DeleteBackup_Failed", ['parent_directory' => $parent_directory]);
        }
    } else {
        $message = _lang("DeleteBackup_Cleanup_Success", ['parent_directory' => $parent_directory]);
        $success = true;
    }

    // Delete the database entry if the directory was either missing already or successfully deleted
    if ($missing_backup_directory || $backup_directory_delete_successful) {
        // Open the database connection
        $db = db_open();

        $stmt = $db->prepare("DELETE FROM `backups` WHERE `random_id` = :random_id;");
        $stmt->bindParam(":random_id", $backup_to_delete['random_id'], PDO::PARAM_STR);
        $stmt->execute();

        // Close the database connection
        db_close($db);
    }

    if ($called_from_ui) {
        set_alert(true, $success ? "good" : "bad", $message);
    } else {
        write_debug_log($message, "info");
        write_log(0, 0, $message, 'backup');
    }
}

/***************************
 * FUNCTION: SAVE TMP DATA *
 ***************************/
function save_tmp_data(PDO $db, string $name, mixed $data, int $user_id = 0): string {
    $unique_name = uniqid('data_', true);

    // Debugging: warn if data is not an array or string
    if (!is_array($data) && !is_string($data)) {
        write_debug_log("save_tmp_data: Unexpected data type for '$name': " . gettype($data) . ". Raw data: " . var_export($data, true), "warning");
    }

    // Recursive sanitization to remove invalid UTF-8 characters
    $sanitize = function($item) use (&$sanitize) {
        if (is_array($item)) {
            return array_map($sanitize, $item);
        } elseif (is_string($item)) {
            // Ensure UTF-8
            $item = mb_convert_encoding($item, 'UTF-8', 'UTF-8');

            // Replace common problematic characters
            $replacements = [
                "\x92" => "'",   // ’
                "\x93" => '"',  // “
                "\x94" => '"',  // ”
                "\x96" => '-',  // –
                "\x97" => '—',  // —
                "\x85" => '...',// …
                "\x91" => "'",   // ‘
                "\x95" => '*',  // •
            ];

            return strtr($item, $replacements);
        } else {
            return $item;
        }
    };

    $data = $sanitize($data);

    // Convert array to JSON if needed, leave strings as-is
    if (is_array($data)) {
        $data_to_save = json_encode($data, JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
        if ($data_to_save === false) {
            $err = json_last_error_msg();
            write_debug_log("save_tmp_data: Failed to json_encode '$name': $err. Raw data: " . var_export($data, true), "error");
            $data_to_save = '';
        }
    } else {
        $data_to_save = (string) $data;
    }

    $size = strlen($data_to_save);

    // Debugging: warn if content is empty
    if ($size === 0) {
        write_debug_log("save_tmp_data: Saving empty content for '$name'. Raw data: " . var_export($data, true), "warning");
    }

    $stmt = $db->prepare("
        INSERT INTO tmp_files (unique_name, name, user, content)
        VALUES (:unique_name, :name, :user, :content)
    ");

    $stmt->execute([
        ':unique_name' => $unique_name,
        ':name' => $name,
        ':user' => $user_id,
        ':content' => $data_to_save
    ]);

    return $unique_name;
}

/***************************
 * FUNCTION: LOAD TMP DATA *
 ***************************/
function load_tmp_data(PDO $db, string $unique_name): mixed {
    $stmt = $db->prepare("SELECT content FROM tmp_files WHERE unique_name = :unique_name");
    $stmt->execute([':unique_name' => $unique_name]);
    $row = $stmt->fetch(PDO::FETCH_ASSOC);

    if (!$row) return null;

    $content = $row['content'];

    // If content is JSON (from an array), decode it; else return string
    $decoded = json_decode($content, true);
    return (json_last_error() === JSON_ERROR_NONE) ? $decoded : $content;
}

/*****************************
 * FUNCTION: DELETE TMP DATA *
 *****************************/
function delete_tmp_data(PDO $db, string $unique_name): bool {
    $stmt = $db->prepare("DELETE FROM tmp_files WHERE unique_name = :unique_name");
    return $stmt->execute([':unique_name' => $unique_name]);
}

/**
 * Sanitize text to ensure valid UTF-8 encoding.
 *
 * PDFs can contain malformed UTF-8 sequences from corrupted encodings,
 * special symbols, or embedded fonts. This method ensures the output
 * is always valid UTF-8 that can be safely JSON-encoded.
 *
 * @param string $text Input text that may contain malformed UTF-8
 * @return string Valid UTF-8 text
 */
function sanitizeUtf8(string $text): string
{
    // Return empty string if input is empty
    if ($text === '') {
        return '';
    }

    // Strategy 1: Try to fix the encoding by re-encoding
    $cleaned = mb_convert_encoding($text, 'UTF-8', 'UTF-8');

    // Strategy 2: Verify it's actually valid UTF-8 now
    if (!mb_check_encoding($cleaned, 'UTF-8')) {
        // If still invalid, use iconv to strip problematic sequences
        // The //IGNORE flag removes characters that cannot be converted
        $cleaned = iconv('UTF-8', 'UTF-8//IGNORE', $text);

        // If iconv also fails, fall back to a more aggressive approach
        if ($cleaned === false) {
            // Remove any non-UTF-8 bytes using a regex
            $cleaned = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x80-\x9F]/u', '', $text);

            // If even that fails, strip to ASCII-safe characters only
            if ($cleaned === null || !mb_check_encoding($cleaned, 'UTF-8')) {
                $cleaned = preg_replace('/[^\x20-\x7E\x0A\x0D\t]/u', '', $text);
            }
        }
    }

    // Final safety check: ensure we return a string, not false/null
    return is_string($cleaned) ? $cleaned : '';
}

/**
 * Matches a stray control character that is never legitimate in imported GRC
 * field data, while excluding tab/CR/LF (0x09/0x0A/0x0D), which are. Shared
 * between sanitize_import_cell_value() (strips these) and
 * has_invalid_text_encoding() in includes/data_integrity.php (detects
 * these) so the two stay in sync -- the Data Integrity scanner's notion of
 * "genuine corruption" must match exactly what the repair actually fixes.
 */
const STRAY_CONTROL_CHARACTER_PATTERN = '/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u';

/**
 * Sanitize a raw cell value extracted from an imported spreadsheet/CSV row
 * (Import-Export Extra and any other spreadsheet-driven importer).
 *
 * Files exported from Excel as "CSV (Comma delimited)" on Windows are commonly
 * Windows-1252 encoded rather than UTF-8; their smart quotes/dashes are single
 * bytes (0x91-0x97) that are invalid as standalone UTF-8. Left unsanitized,
 * those bytes reach json_encode() in a DataTables API response, which silently
 * returns false on invalid UTF-8 -- breaking the entire table's Ajax response
 * for every row, not just the corrupted one.
 *
 * @param mixed $value Raw value pulled from the parsed spreadsheet row
 * @return string Sanitized, guaranteed-valid-UTF-8 string
 */
function sanitize_import_cell_value(mixed $value): string
{
    if (!is_string($value)) {
        $value = (string)$value;
    }

    if ($value === '') {
        return '';
    }

    // Only attempt Windows-1252 punctuation recovery when the raw bytes are NOT
    // already valid UTF-8. The recovery itself is scoped to bytes that aren't
    // part of a valid UTF-8 sequence anywhere in the string (see
    // recover_cp1252_stray_bytes()), so a cell mixing one stray CP1252 byte with
    // legitimate multi-byte text elsewhere (many CJK/Cyrillic code points use
    // 0x91-0x97 as a continuation byte) doesn't have that valid text corrupted.
    if (!mb_check_encoding($value, 'UTF-8')) {
        $value = recover_cp1252_stray_bytes($value);
    }

    // Guarantee valid UTF-8 for anything still broken (or introduced by a byte
    // sequence the table above doesn't cover)
    $value = sanitizeUtf8($value);

    // Strip stray control characters -- never legitimate in imported GRC field
    // data -- while preserving tab/CR/LF
    $value = preg_replace(STRAY_CONTROL_CHARACTER_PATTERN, ' ', $value);

    return trim($value);
}

/**
 * Recover Windows-1252 smart-quote/dash punctuation from bytes that are NOT
 * part of a valid UTF-8 sequence, leaving valid multi-byte sequences
 * untouched even when they use the same byte values as continuation bytes.
 *
 * Walks the string as a sequence of "valid UTF-8 sequence | single byte"
 * tokens (the alternation below is the standard UTF-8-validating regex) and
 * only maps a token through the CP1252 table when it matched as a single,
 * otherwise-unconsumed byte -- i.e. it wasn't part of a longer valid
 * sequence. This is what keeps a stray invalid byte elsewhere in the same
 * cell from corrupting legitimate CJK/Cyrillic text that happens to contain
 * the same byte values as valid continuation bytes.
 *
 * @param string $value Raw bytes, already known not to be valid UTF-8 as a whole
 * @return string Same bytes with only the genuinely-stray CP1252 punctuation bytes recovered
 */
function recover_cp1252_stray_bytes(string $value): string
{
    static $cp1252_punctuation = [
        "\x91" => "'", "\x92" => "'", "\x93" => '"', "\x94" => '"',
        "\x96" => '-', "\x97" => '—', "\x85" => '...', "\x95" => '*',
    ];
    static $pattern = '/[\x09\x0A\x0D\x20-\x7E]|[\xC2-\xDF][\x80-\xBF]|\xE0[\xA0-\xBF][\x80-\xBF]|[\xE1-\xEC\xEE\xEF][\x80-\xBF]{2}|\xED[\x80-\x9F][\x80-\xBF]|\xF0[\x90-\xBF][\x80-\xBF]{2}|[\xF1-\xF3][\x80-\xBF]{3}|\xF4[\x80-\x8F][\x80-\xBF]{2}|./s';

    $recovered = preg_replace_callback($pattern, static function (array $m) use ($cp1252_punctuation): string {
        $token = $m[0];
        // Only a lone byte can be a CP1252 punctuation candidate -- every
        // multi-byte alternative above matched a valid sequence and must be
        // passed through unchanged.
        return strlen($token) === 1 ? ($cp1252_punctuation[$token] ?? $token) : $token;
    }, $value);

    return $recovered ?? $value;
}

/*********************************
 * FUNCTION: REQUIRE POST FIELDS *
 *********************************/
function require_post_fields(array $postData, array $requiredFields): bool
{
    foreach ($requiredFields as $field) {
        if (!isset($postData[$field]) || $postData[$field] === '' || $postData[$field] === null) {
            set_alert(true, "bad", "Missing required field: {$field}");
            return false;
        }
    }
    return true;
}

/*****************************
 * FUNCTION: GET TABLE COUNT *
 *****************************/
function get_table_count(PDO $db, string $table): int
{
    $stmt = $db->prepare("SELECT COUNT(*) FROM `$table`;");
    $stmt->execute();
    return (int) $stmt->fetchColumn();
}

/**************************
 * FUNCTION: REMOVE FILES *
 **************************/
function remove_files(array $files): int
{
    // Track the number of successful file removals
    $files_removed = 0;

    // If files is not an array
    if (!is_array($files))
    {
        write_debug_log("[REMOVE FILES] Files parameter was not an array.", "error");
        return $files_removed;
    }

    // Iterate through the files array
    foreach ($files as $file)
    {
        // If the file does not exist
        if (!file_exists($file))
        {
            write_debug_log("[REMOVE FILES] The file '{$file}' does not exist.", "warning");
            continue;
        }

        // If the file is not writeable
        if (!is_writeable($file))
        {
            write_debug_log("[REMOVE FILES] The file '{$file}' is not writeable.", "warning");
            continue;
        }

        // The file exists and is writeable so try to remove it
        $success = delete_file($file);

        // If the removal failed
        if (!$success)
        {
            write_debug_log("[REMOVE FILES] Failed to remove the file '{$file}'.", "warning");
            continue;
        }

        // We successfully removed the file
        write_debug_log("[REMOVE FILES] Successfully removed the file '{$file}'.", "info");
        $files_removed++;
    }

    // Return the number of files removed
    return $files_removed;
}

/************************
 * FUNCTION: SAFE ROUND *
 ************************/
function safe_round($value, $precision = 2)
{
    return is_numeric($value) ? round((float)$value, $precision) : null;
}

// *****************************************************************************************
// FUNCTION: GET DYNAMIC RISKS DATA FOR OUTPUT                                             *
// This function retrieves dynamic risks data for output, either for display or download.  *
// It returns [xlsHeader, xlsRows] arrays containing the risk data formatted for output.   *
// Returned results are the same for the download and html options                         *
// *****************************************************************************************
function get_dynamic_risks_data_for_output($filter_status, $group, $sort, $download_group_value="", $selected_columns=[], $column_filters=[], $order_column=null, $order_dir="asc", $option="download", $force_user_id=null) {
    
    global $escaper, $lang;

    // Allow this to run as long as necessary
    ini_set('max_execution_time', 0);

    // For downloading table, disregard column_filters
    if($option == "download" || $option == "html") {
        $risks = get_risks_only_dynamic($need_total_count=false, $filter_status, $sort, 0, $column_filters, $rowCount, 0, -1, "", "", [], force_user_id: $force_user_id);
    } else {
        $risks = get_risks_only_dynamic($need_total_count=false, $filter_status, $sort, $group, $column_filters, $rowCount, 0, -1, $download_group_value, "", [], $order_column, $order_dir, force_user_id: $force_user_id);
    }

    // Get group name from $group
    list($group_name, $order_query) = get_group_name_for_dynamic_risk($group, "");

    // Save it in a boolean so don't have to check a string
    $grouped = $group_name !== "none";

    $xlsHeader = array();
    $xlsRows = array();

    $xlsRow = array();
    $str = "";
    foreach($selected_columns as $column=>$status){
        $name = '';
        if(stripos($column, "custom_field_") === false){
            $name = get_label_by_risk_field_name($column);
        } else {
            // If customization extra is enabled, includes customization fields
            if(customization_extra()){
                $custom_cols = "";

                // Include the extra
                require_once(realpath(__DIR__ . '/../extras/customization/index.php'));

                $field_id = str_replace("custom_field_", "", $column);
                $custom_field = get_field_by_id($field_id);
                $name = $escaper->escapeHtml($custom_field['name']);
            }
        }
        if($status == true) array_push($xlsRow, $name);
    }

    $xlsHeader = $xlsRow;

    $risk_levels = get_risk_levels();
    $review_levels = get_review_levels();

    // If the group name is none
    if (!$grouped) {

        $xlsRows[] = $xlsHeader;

        // For each risk in the risks array
        foreach ($risks as $risk) {
            $xlsRows[] = get_risk_columns_for_download($risk, $risk_levels, $review_levels, $selected_columns);
        }
    }
    else
    {
        $displayed_group_names = [];
        // For each risk in the risks array
        foreach ($risks as $risk)
        {
            // We only need these for grouping, it's a waste of time to calculate the rest.
            // In case you add a new grouping add to this list
            // so the $group_value = ${$group_name}; expression can get its value
            $status = $risk['status'];
            $scoring_method = get_scoring_method_name($risk['scoring_method']);
            $risk_level = get_risk_level_name((float)$risk['calculated_risk']);
            $location = $risk['location'];
            $source = $risk['source'];
            $category = $risk['category'];
            $team = $risk['team'];
            $technology = $risk['technology'];
            $owner = $risk['owner'];
            $manager = $risk['manager'];
            $regulation = try_decrypt($risk['regulation']);
            $project = try_decrypt($risk['project']);
            $next_step = $risk['next_step'];
            if (!$risk['submission_date'] || stripos($risk['submission_date'], "0000-00-00") !== false)
            {
                // Set the review date to empty
                $month_submitted = "";
            }
            else
            {
                $month_submitted = date('Y F', strtotime($risk['submission_date']));
            }

            if($group_name == "month_submitted"){
                if (!$download_group_value || stripos($download_group_value, "0000-00-00") !== false)
                {
                    // Set the review date to empty
                    $download_group_value = "";
                }
                else
                {
                    $download_group_value = date('Y F', strtotime($download_group_value)); 
                }
            }else{
                switch($group_name){
                    case "risk_level":
                        $download_group_value = get_risk_level_name($download_group_value);
                    break;
                }
            }
            if($option == "download" || $option == "html"){
                $initial_group_value = trim(${$group_name} ?? '');
                
                // Check comma splitted group
                if($group_name == "team" || $group_name == "technology")
                {
                    if($initial_group_value)
                    {
                        $group_values_including_empty = array_map("trim", explode(",", $initial_group_value));
                        $group_values = [];
                        foreach($group_values_including_empty as $val){
                            // Remove empty values from group_values
                            if($val) $group_values[] = $val;
                        }
                    }
                    else
                    {
                        $group_values = [""];
                    }
                }
                else
                {
                    $group_values = [$initial_group_value];
                }
            } else {
                $group_values = [$download_group_value];
            }

            foreach($group_values as $group_value)
            {
                // If the selected group value is empty
                if ($group_value == "")
                {
                    // Current group is Unassigned
                    $group_value = $lang['Unassigned'];
                }

                if (!in_array($group_value, $displayed_group_names))
                {
                    $displayed_group_names[] = $group_value;
                    if($option == "download" || $option == "html"){
                        switch($group_name){
                            case "risk_level":
                                $group_value_from_db = $risk['calculated_risk'];
                            break;
                            case "month_submitted":
                                $group_value_from_db = $risk['submission_date'];
                            break;
                            // Comma splitted group
                            case "team":
                            case "technology":
                                $group_value_from_db = get_value_by_name($group_name, $group_value);
                            break;
                            default:
                                $group_value_from_db = $risk[$group_name];
                            break;
                        }
                        if(!$group_value_from_db) $group_value_from_db = "";
                        $display_group_name = $group_value;
                    } else {
                        $group_value_from_db = $download_group_value;
                        $display_group_name = get_group_name_from_value($group, $group_value);
                    }
                    $xlsRows[] = $display_group_name;
                    $xlsRows[] = $xlsHeader;
                    $risks_by_group = get_risks_only_dynamic($need_total_count=false, $filter_status, $sort, $group, $column_filters, $rowCount, 0, -1, $group_value_from_db, "", [], $order_column, $order_dir, force_user_id: $force_user_id);
                    // For each risk in the risks array
                    foreach ($risks_by_group as $risk) {
                        $xlsRows[] = get_risk_columns_for_download($risk, $risk_levels, $review_levels, $selected_columns);
                    }
                }
            }
        }
    }

    return [$xlsHeader, $xlsRows, $grouped];

}

/*****************************************************
 * FUNCTION: GET NON-ADMIN USERS FOR TEAM MANAGEMENT *
 *****************************************************/
function get_non_admin_users_for_team_management($team_id = 0) {
    $team_id = (int)$team_id;

    if (organizational_hierarchy_extra()) {
        if (!$team_id) {
            return [];
        }

        $db = db_open();

        $stmt = $db->prepare("
            SELECT
                u.`value`,
                u.`username`
            FROM
                `user` u
            WHERE
                u.`admin` = 0
                AND u.`selected_business_unit` IN (
                    SELECT
                        `business_unit_id`
                    FROM
                        `business_unit_to_team`
                    WHERE
                        `team_id` = :team_id
                )
            ORDER BY
                u.`username` ASC
        ");
        $stmt->bindParam(':team_id', $team_id, PDO::PARAM_INT);
        $stmt->execute();
        $users = $stmt->fetchAll(PDO::FETCH_ASSOC);

        db_close($db);

        return $users;
    }

    $db = db_open();

    $stmt = $db->prepare("
        SELECT
            `value`,
            `username`
        FROM
            `user`
        WHERE
            `admin` = 0
        ORDER BY
            `username` ASC;
    ");
    $stmt->execute();
    $users = $stmt->fetchAll(PDO::FETCH_ASSOC);

    db_close($db);

    return $users;
}

/**********************************************
 * FUNCTION: UPDATE TEAM MEMBERSHIP FOR USERS *
 **********************************************/
function update_team_membership_for_users($team_id, $selected_user_ids, $all_user_ids) {
    foreach ($all_user_ids as $user_id) {
        $current_teams = get_user_teams($user_id);
        if (!$current_teams) {
            $current_teams = [];
        }

        $is_team_member = in_array($team_id, $current_teams);
        $should_be_member = in_array($user_id, $selected_user_ids);

        if ($is_team_member === $should_be_member) {
            continue;
        }

        if ($should_be_member) {
            $updated_teams = array_unique(array_merge($current_teams, [$team_id]));
        } else {
            $updated_teams = array_values(array_diff($current_teams, [$team_id]));
        }

        set_teams_of_user($user_id, $updated_teams);
    }
}

/****************************************
 * FUNCTION: DB SESSION HANDLER MODE    *
 ****************************************/
/**
 * Decide which session-save-handler registration strategy applies for the
 * given handler class, tolerant of Extra/Core version skew (a newer Extra
 * running against an older Core). Side-effect-free for an already-loaded class
 * (the production case — callers require_once authenticate.php first), so it is
 * unit testable without bootstrapping a real session. class_exists() is called
 * with autoload disabled; method_exists() can still autoload an unknown class,
 * so do not call this on arbitrary untrusted class names.
 *
 * Returns one of:
 *   'register' — the class exposes the static register() method (current Core);
 *                callers invoke SimpleRiskSessionHandler::register().
 *   'object'   — the class exists but predates register() (older Core); callers
 *                register it as an object implementing SessionHandlerInterface
 *                (never the individual-callback form, which PHP 8 deprecates).
 *   'legacy'   — the class is absent entirely (Core predating it); callers use
 *                the individual sess_* callbacks as a last resort.
 *
 * Test for the METHOD, not just the class: the legacy SimpleRiskSessionHandler
 * predates register(), so class_exists() alone would select a method the class
 * lacks (the original /metrics fatal this guards against).
 */
function db_session_handler_mode(string $handler_class): string
{
    if (method_exists($handler_class, 'register')) {
        return 'register';
    }

    if (class_exists($handler_class, false)) {
        return 'object';
    }

    return 'legacy';
}

/**
 * Whether an address is deliverable enough to hand to the mailer. Single source
 * of truth for "is this a sendable email address?", shared by
 * send_email_immediate() and the pre-send guards (assessments invite / result
 * share / send-assessment) so their validation can never drift apart. Rejects
 * null, '', whitespace, and malformed addresses — including the '' that
 * try_decrypt() returns when an encrypted address cannot be decrypted.
 */
function is_sendable_email_address(?string $email): bool
{
    return $email !== null && filter_var($email, FILTER_VALIDATE_EMAIL) !== false;
}

/**
 * The current session's user id, or null when there isn't one — e.g. under
 * cron, where there is no HTTP session. Treats a falsy uid (unset or 0) the
 * same as "no session", since 0 is not a real user id. A plain `??` would
 * keep 0, since it only catches null.
 */
function current_session_uid_or_null(): ?int
{
    return !empty($_SESSION['uid']) ? (int)$_SESSION['uid'] : null;
}

/*********************************************************************
 * FUNCTION: RISKS ASSOCIATED WITH                                   *
 * Every risk connected to a given entity, as RAW risks.id values.   *
 *                                                                   *
 * Deliberately NOT the graph walkers. get_risk_connectivity_for_    *
 * asset() applies strip_no_access_risks() (entity_graph.php:786),   *
 * and the control/exception/test-result walkers inherit the same     *
 * Team Separation filter through graph_risk_edge_rows() (:195).      *
 * That is right for the Explorer and for ai_get_context(), and wrong *
 * here: invalidation is system bookkeeping, not a user-facing read.  *
 * Filtering it would mean a user who can see 10 of 50 affected risks *
 * silently leaves the other 40 serving stale analysis.               *
 *                                                                   *
 * The joins below mirror the graph's own so the two cannot disagree  *
 * about what "connected" means.                                      *
 *********************************************************************/
function risks_associated_with(string $type, int $id, PDO $db): array
{
    if ($id <= 0) {
        return [];
    }

    switch ($type) {
        case 'asset':
            // Direct attachment, plus membership of any attached asset group.
            $sql = "SELECT DISTINCT rta.risk_id AS id
                    FROM risks_to_assets rta WHERE rta.asset_id = :id
                    UNION
                    SELECT DISTINCT rtag.risk_id AS id
                    FROM risks_to_asset_groups rtag
                    JOIN assets_asset_groups aag ON aag.asset_group_id = rtag.asset_group_id
                    WHERE aag.asset_id = :id2";
            $params = [':id' => $id, ':id2' => $id];
            break;

        case 'exception':
            // associated_risks is a CSV of RAW risks.id values, not display ids.
            // The exception form posts the raw id (governance/document_exceptions.php
            // renders <option value='{$risk['id']}'> and only the LABEL adds 1000),
            // and every existing reader joins raw — see
            // get_risk_connectivity_for_exception() in entity_graph.php, whose
            // docblock says "matching the raw ids stored in associated_risks".
            // Mirroring that join here is what makes the docblock's promise true;
            // an earlier version subtracted 1000 and silently resolved risk 42 to
            // -958 (dropped) or raw 1200 to 200 (the WRONG risk marked stale).
            $sql = "SELECT DISTINCT r.id AS id
                    FROM document_exceptions de
                    JOIN risks r ON FIND_IN_SET(r.id, de.associated_risks) > 0
                    WHERE de.value = :id";
            $params = [':id' => $id];
            break;

        case 'test_result':
            $sql = "SELECT DISTINCT fctrr.risk_id AS id
                    FROM framework_control_test_results_to_risks fctrr
                    WHERE fctrr.test_results_id = :id";
            $params = [':id' => $id];
            break;

        default:
            return [];
    }

    try {
        $stmt = $db->prepare($sql);
        $stmt->execute($params);

        return array_values(array_filter(
            array_map('intval', $stmt->fetchAll(PDO::FETCH_COLUMN)),
            fn($rid) => $rid > 0
        ));
    } catch (Throwable $e) {
        write_debug_log("[risks_associated_with] {$type}: " . $e->getMessage(), "error");
        return [];
    }
}

/*********************************************************************
 * FUNCTION: AI INVALIDATE RISK ANALYSIS                             *
 * Stamp association_last_update for a set of RAW risks.id values.   *
 *                                                                   *
 * Invalidation is deliberately CHEAP and UNBOUNDED: one asset can be *
 * attached to thousands of risks and a bulk import invalidates all   *
 * of them at once. Bounding AI spend is the sweep's job (5 per tick  *
 * plus a settle window), never this function's — conflating the two  *
 * is exactly how the original requeue storm happened.                *
 *                                                                   *
 * Touches only `risks`, never the AI Extra's ai_recommendations_risk,*
 * so it is safe on a Core-only install and needs no table_exists()   *
 * guard. last_update is left alone: that column means "the risk      *
 * record changed" and is read elsewhere in the product.              *
 *********************************************************************/
function ai_invalidate_risk_analysis(array $risk_ids, ?PDO $db = null): int
{
    $ids = array_values(array_unique(array_filter(
        array_map('intval', $risk_ids),
        fn($id) => $id > 0
    )));

    if (empty($ids)) {
        return 0;
    }

    $close_db = false;
    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        $placeholders = implode(',', array_fill(0, count($ids), '?'));
        $stmt = $db->prepare(
            "UPDATE `risks` SET `association_last_update` = NOW() WHERE `id` IN ({$placeholders})"
        );
        $stmt->execute($ids);

        return $stmt->rowCount();
    } catch (Throwable $e) {
        write_debug_log("[ai_invalidate_risk_analysis] " . $e->getMessage(), "error");
        return 0;
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/*********************************************************************
 * FUNCTION: AI INVALIDATE RISK ANALYSIS FOR                         *
 * Resolve every risk connected to an entity and mark them stale.     *
 *                                                                   *
 * Callers on a DELETE path must invoke this BEFORE removing the      *
 * association rows — afterwards the resolver finds nothing and the   *
 * affected risks are never invalidated.                              *
 *********************************************************************/
function ai_invalidate_risk_analysis_for(string $type, int $id, ?PDO $db = null): int
{
    $close_db = false;
    if ($db === null) {
        $db = db_open();
        $close_db = true;
    }

    try {
        return ai_invalidate_risk_analysis(risks_associated_with($type, $id, $db), $db);
    } finally {
        if ($close_db) {
            db_close($db);
        }
    }
}

/*******************************************************************************
 * FUNCTION: NORMALIZE BULK IDS                                                *
 * Shared "select all N" id-list sanitizer behind every batch-mutation         *
 * endpoint's own normalize_*_ids() wrapper -- normalize_bulk_risk_ids()       *
 * (includes/api.php), normalize_bulk_approve_ids() (includes/governance.php), *
 * and manage_audits_normalize_batch_delete_ids() /                            *
 * define_tests_normalize_batch_ids() (api/v2/includes/compliance.php). Those  *
 * four were hand-duplicated copies of this exact loop, differing only in      *
 * which cap constant they close over -- consolidated here so there is        *
 * exactly one implementation to audit; each wrapper keeps its own name (and   *
 * its own fixed cap constant) for its existing callers and tests, and just    *
 * delegates to this function.                                                 *
 *                                                                              *
 * Drops any member that isn't a scalar decimal-digit string -- a nested-array *
 * member would otherwise reach the (string) cast and raise "Array to string   *
 * conversion"; is_scalar() alone would also admit bool true, which casts to   *
 * "1" and would silently target record 1 -- then caps the result at $cap so   *
 * one authorized request can't drive an unbounded number of mutations.        *
 * $truncated is set true only when a real (numeric, positive) id was dropped  *
 * by the cap -- never for junk that was filtered out anyway -- so the         *
 * caller's batch response can tell "you sent exactly the cap" apart from      *
 * "you sent more than the cap and some were silently never touched".         *
 *                                                                              *
 * Pure: no session, no DB. Directly unit-testable.                            *
 *                                                                              *
 * @param  mixed $raw_ids
 * @param  int   $cap
 * @param  bool  $truncated
 * @return int[]
 *******************************************************************************/
function normalize_bulk_ids($raw_ids, $cap, &$truncated = null) {
    $truncated = false;

    if (!is_array($raw_ids)) {
        return [];
    }

    $ids = [];
    foreach ($raw_ids as $raw_id) {
        if (!is_int($raw_id) && !is_string($raw_id)) {
            continue;
        }
        $candidate = (string)$raw_id;
        if ($candidate === '' || !ctype_digit($candidate) || (int)$candidate <= 0) {
            continue;
        }
        if (count($ids) >= $cap) {
            $truncated = true;
            continue;
        }
        $ids[] = (int)$candidate;
    }

    return $ids;
}

// "Select all N"'s shared cap-exceeded message: Manage Audits, Define Tests,
// and Review Risk's own filtered_ids endpoints all hit this exact branch
// when the resolved id count exceeds their (independent) cap constant.
// $noun_lang_key names a plain $lang[] key (e.g. 'Audits'/'Tests'/'Risks')
// -- passed as the RAW lookup, not through _lang(), and deliberately so:
// _lang() escapes every param it's given, and its own return value already
// carries that escaping, so handing $lang[$noun_lang_key] straight to the
// outer _lang() call here (which escapes it once) is correct, while nesting
// a second _lang() call to resolve the noun would escape it twice
// (Phan: SecurityCheck-DoubleEscaped -- this is exactly the bug that shipped
// independently at all 3 call sites this helper replaces, and had to be
// fixed independently at all 3).
function select_all_too_many_matches_message(int $max, string $noun_lang_key): string
{
    global $lang;

    return _lang('SelectAllTooManyMatches', ['max' => $max, 'noun' => $lang[$noun_lang_key] ?? '']);
}

?>